def test_a_take_pointer_escaping_the_output_directory_is_refused(tmp_path: Path):
    """A `latest_output` carrying `..` may not hand an arbitrary file to the node."""
    client, store, comfy = make_client(tmp_path)
    project = restorable_project(store, tmp_path, take="../../escaped.mp4")

    response = restore_audio(client, project)

    assert response.status_code == 422
    assert comfy.prompts == []


def test_a_shot_running_past_the_end_of_the_song_is_refused_by_the_renders_own_rule(
    tmp_path: Path,
):
    """The matrix's past-the-end row, and that it is inherited rather than a second rule.

    The refusal a restoration gives is byte-identical to the one an H3 submission gives for the
    same shot, because both come from `song_audio_window`. A second rule written on this path
    would drift from that one the first time either changed.
    """
    client, store, comfy = make_client(tmp_path)
    project = restorable_project(store, tmp_path, start=152.0, duration=5.0)

    response = restore_audio(client, project)

    assert response.status_code == 422
    assert "runs past the end of the master song" in response.json()["detail"]
    assert comfy.prompts == []
    # The same sentence the shared function produces, so the two stages refuse alike.
    with pytest.raises(ValueError) as shared:
        song_audio_window(start=152.0, duration=5.0, song_duration=RESTORE_SONG_DURATION)
    assert response.json()["detail"] == str(shared.value)


def test_a_restoration_reports_both_lengths_and_never_pads_or_cuts(tmp_path: Path):
    """The matrix's length-mismatch row, reported against the take rather than the window.

    A 3.75 s shot is **107** frames since the over-render margin, which is 4.4583 s, and the
    audio this stage sends is those same 4.4583 s. Both numbers used to describe something else:
    the picture through the pre-margin formula (90 frames), the audio as the shot's bare
    duration. Reported together they now agree by construction, which is the fix — the pair is
    the report, and a report that disagrees with the take is what the Director would have read
    as truth.
    """
    client, store, comfy = make_client(tmp_path)
    exact = restore_audio(client, restorable_project(store, tmp_path)).json()

    assert exact["requested_frames"] == 107
    assert exact["requested_picture_seconds"] == pytest.approx(107 / 24)
    assert exact["audio_seconds"] == pytest.approx(107 / 24)
    assert exact["lengths_match"] is True

    # A micro-cut: 2.083 s of window, the same 107 frames of take, centred. The number this
    # route reported for it before 2026-08-21 was 50 frames.
    micro = restore_audio(
        client, restorable_project(store, tmp_path, start=12.0, duration=2.083)
    ).json()

    assert micro["requested_frames"] == 107
    assert micro["audio_seconds"] == pytest.approx(107 / 24)
    assert micro["lengths_match"] is True
    assert "107 frames" in micro["length_note"]
    # The sentence names the seconds actually sent, not the window's.
    assert "10.7917s to 15.25s" in micro["length_note"]

    # Both numbers in the sentence, and the sentence is present either way.
    for body in (exact, micro):
        assert "trim_to_audio is off" in body["length_note"]
        assert "ffprobe" in body["length_note"]
        assert "107 frames" in body["length_note"]
    assert all(
        prompt["mvp:save"]["inputs"]["trim_to_audio"] is False for prompt in comfy.prompts
    )


def test_the_restored_window_is_the_takes_own_seconds_for_every_window_shape(tmp_path: Path):
    """Defect 1, across the four shapes a take can have. Nothing here renders.

    The take is the whole rendered clip and not the exposed slice, so the audio must cover the
    whole take at the take's own offset:

        take second `t` is song second `start - lead + t`

    — one invariant, four clamps, and the clamps move the buffer rather than the exposure. A
    normal window leads by a quarter second; a micro-cut is centred on its window and leads by
    half its buffer; a shot at 0.0 s cannot lead at all because there is no song before 0 s; a
    shot at the song's end has its whole buffer ahead of it. In every one of them the audio is
    the take's own length, and `seek_seconds + lead` is the window's first second exactly.
    """
    client, store, comfy = make_client(tmp_path)
    song_end = RESTORE_SONG_DURATION
    cases = {
        "normal": (12.0, 3.75),
        "micro-cut, centred": (12.0, 2.083),
        "at the song's start": (0.0, 2.083),
        "at the song's end": (song_end - 2.083, 2.083),
    }

    for name, (start, duration) in cases.items():
        project = restorable_project(store, tmp_path, start=start, duration=duration)
        assert restore_audio(client, project).status_code == 202, name

        shot = store.get(project.id).shots[0]
        window = comfy.prompts[-1]["mvp:song"]["inputs"]
        expected_start, expected_end = over_render_window(
            start=start,
            lead=shot.latest_take_lead,
            picture_seconds=over_render_frames(duration) / 24,
            song_duration=song_end,
        )
        assert window["seek_seconds"] == pytest.approx(expected_start), name
        assert window["duration"] == pytest.approx(expected_end - expected_start), name
        # The take's whole length, every time: 107 frames, floored at H3's own four-second
        # minimum. The bare window — 3.75 s, or 2.083 s three times over — is what this stage
        # used to send.
        assert window["duration"] == pytest.approx(107 / 24), name
        assert window["duration"] != pytest.approx(duration), name
        # The invariant, which is the whole claim: the take's own frame `round(lead * 24)` is
        # the window's first second, in the restored audio exactly as in the conditioning.
        assert window["seek_seconds"] + shot.latest_take_lead == pytest.approx(start), name
        # Nothing before the song, nothing past its end.
        assert window["seek_seconds"] >= 0, name
        assert window["seek_seconds"] + window["duration"] <= song_end + 1e-9, name

    # The two edges really are the edges, so the clamps above were exercised rather than
    # trivially satisfied: the shot at 0 s takes the song from its first sample, and the shot at
    # the end takes it to its last.
    starts = [prompt["mvp:song"]["inputs"]["seek_seconds"] for prompt in comfy.prompts]
    assert starts[2] == 0.0
    assert starts[3] + 107 / 24 == pytest.approx(song_end)


def test_a_take_whose_audio_runs_out_at_the_songs_end_says_so_instead_of_padding(
    tmp_path: Path,
):
    """The one length mismatch left, and the only way to reach it.

    For a shot rendered where it sits, the pair always agrees: `over_render_lead` grows the lead
    to keep the tail inside the song, and it always has the room to. What is left is a take whose
    *song* got shorter — the lead was recorded against a longer master, so the take's own seconds
    now reach past the end of the one on disk. (Before the window snapshot this was also how a
    moved window surfaced; since 2026-08-21 the take carries the window it was rendered for, so
    dragging the clip no longer changes these numbers at all.) The tail is clamped at the song's
    end, the audio comes up short of the picture by that much, and both numbers are reported
    rather than the picture being cut to fit (`trim_to_audio` is off) or the audio padded.

    The sentence is scoped to the two numbers it is about (2026-08-21): `over_render_window`'s
    only clamp is the song's own end, so a shortfall between *these two* is always the master
    running out before the requested picture would reach — but "the picture" was reading as the
    file, and on a take with no window snapshot the requested picture is the plan's count rather
    than the render's. Saying "the requested picture" is what keeps this branch from explaining
    a mismatch with a cause that may not have produced it.
    """
    client, store, comfy = make_client(tmp_path)
    project = restorable_project(
        store,
        tmp_path,
        start=150.0,
        duration=4.0,
        song_duration=154.0,
        latest_take_lead=0.25,
    )

    body = restore_audio(client, project).json()

    window = comfy.prompts[-1]["mvp:song"]["inputs"]
    assert window["seek_seconds"] == 149.75
    # Clamped to the song's last second, not to the take's own 124 frames (5.1667 s).
    assert window["duration"] == pytest.approx(4.25)
    assert body["audio_seconds"] == pytest.approx(4.25)
    assert body["requested_frames"] == 124
    assert body["requested_picture_seconds"] == pytest.approx(124 / 24)
    assert body["lengths_match"] is False
    assert (
        "The two differ: the master runs out before the requested picture does"
        in body["length_note"]
    )
    assert comfy.prompts[-1]["mvp:save"]["inputs"]["trim_to_audio"] is False


def test_the_restored_window_is_the_one_the_render_conditioned_with(tmp_path: Path):
    """The anti-drift pin: two stages, two code paths, one window — read off both graphs.

    `generate_h3` submits the master with a `trim`; this route submits it as `seek_seconds` and
    `duration`. They were separate arithmetic until 2026-08-21 and the restore half was wrong.
    Compared here as *submitted graphs* rather than as two calls to the same helper, because the
    failure being guarded is precisely a route computing its own window on the way.
    """
    client, store, comfy = make_client(tmp_path)

    for start, duration in ((12.0, 3.75), (12.0, 2.083), (0.0, 2.083)):
        rendered = windowed_project(store, client, start=start, duration=duration)
        assert submit_h3(client, rendered.id, rendered.shots[0].id).status_code == 202
        trim = next(
            item for item in submitted_media(comfy) if item["label"] == "master song"
        )["trim"]
        # The lead this submission recorded, carried onto the take the restore stage reads —
        # which is exactly what the manifest carries after a real render.
        recorded = ProjectStore(tmp_path).get(rendered.id).shots[0].latest_take_lead

        restoring = restorable_project(
            store,
            tmp_path,
            start=start,
            duration=duration,
            # `windowed_project`'s song, so the two stages are answering about one track.
            song_duration=154.0,
            latest_take_lead=recorded,
        )
        assert restore_audio(client, restoring).status_code == 202

        window = comfy.prompts[-1]["mvp:song"]["inputs"]
        assert window["seek_seconds"] == pytest.approx(trim["start"]), (start, duration)
        assert window["duration"] == pytest.approx(trim["end"] - trim["start"]), (
            start,
            duration,
        )


def test_a_take_with_no_recorded_lead_is_refused_rather_than_given_a_guessed_offset(
    tmp_path: Path,
):
    """The legacy take, and the shot at 0 s that is not one.

    Since the margin shipped, a song-audio submission records `min(ideal, extra, start)` with
    `ideal` at least a quarter second and `extra` always positive, so a recorded lead is zero
    exactly when the shot starts at 0 s. A zero lead any later means the take predates the margin
    or its bookkeeping was cleared for a hand-picked clip — and which of those it is, and how far
    before the window the picture begins, cannot be worked out from the manifest. Refused by name
    rather than windowed on a guess, for the same reason a shot that never rode the master is.
    """
    client, store, comfy = make_client(tmp_path)
    legacy = restorable_project(store, tmp_path, latest_take_lead=0.0)

    response = restore_audio(client, legacy)

    assert response.status_code == 422
    assert response.json()["detail"] == RESTORE_AUDIO_NO_LEAD_REFUSAL.format(
        shot=shot_label(store.get(legacy.id), store.get(legacy.id).shots[0]),
        start=RESTORE_SHOT_START,
    )
    # No GPU time, and no submission of any kind.
    assert comfy.prompts == []

    # A shot at 0 s records a lead of 0 legitimately — its take begins at the window and the
    # whole buffer is tail — so it is not the legacy case and is not refused.
    opening = restorable_project(store, tmp_path, start=0.0, latest_take_lead=0.0)

    assert restore_audio(client, opening).status_code == 202
    assert comfy.prompts[-1]["mvp:song"]["inputs"]["seek_seconds"] == 0.0

    # The question is asked of the take's window, not the shot's (2026-08-21). A take rendered
    # for 12 s that records no lead stays unplaceable however the clip is dragged afterwards —
    # and the refusal names 12 s, which is where the picture it cannot place actually is.
    dragged = restorable_project(
        store,
        tmp_path,
        start=0.0,
        latest_take_start=RESTORE_SHOT_START,
        latest_take_duration=RESTORE_SHOT_DURATION,
        latest_take_lead=0.0,
    )
    refused = restore_audio(client, dragged)

    assert refused.status_code == 422
    assert refused.json()["detail"] == RESTORE_AUDIO_NO_LEAD_REFUSAL.format(
        shot=shot_label(store.get(dragged.id), store.get(dragged.id).shots[0]),
        start=RESTORE_SHOT_START,
    )
    assert len(comfy.prompts) == 1  # the 0 s shot above, and nothing since


def test_a_window_edited_after_the_render_restores_the_take_and_not_the_new_window(
    tmp_path: Path,
):
    """Finding 2, the whole of it: the take is fixed and the window is not.

    A shot rendered at 12 s for 3.75 s records a 0.25 s lead, and its take is 107 frames of song
    from 11.75 s. Drag that rendered clip's left edge a quarter second right — `start` becomes
    12.25 and `trim_nudge` compensates, which is exactly what the timeline does — and the take
    still begins at song second 11.75. Until the window snapshot existed this route read the
    live `start`, so the master went on the take a quarter second off the lip-sync it was
    performed against, by a frame count the render had not asked for, while the response called
    it "the same count the submission sent".

    The window here is dragged at *both* edges — 12.0 s for 3.75 s becomes 12.25 s for 5.25 s —
    because the offset and the length are two separate claims and a drag that changed only the
    offset would leave the second one untested: `over_render_frames` answers 107 for every
    window under four seconds, so 3.75 and 3.5 are the same count and a report reading the live
    duration would still look right.

    Now the numbers come off `latest_take_start`/`latest_take_duration`, so the payload is the
    same payload as before the drag, and the report says the window has moved instead of
    quietly reporting the moved one as the take's.
    """
    client, store, comfy = make_client(tmp_path)
    project = restorable_project(store, tmp_path)
    unmoved = restore_audio(client, project).json()

    moved_project = restorable_project(
        store,
        tmp_path,
        # The window as it reads after the drag...
        start=RESTORE_SHOT_START + 0.25,
        duration=5.25,
        trim_nudge=-0.25,
        # ...over the take that was rendered before it.
        latest_take_start=RESTORE_SHOT_START,
        latest_take_duration=RESTORE_SHOT_DURATION,
        latest_take_lead=0.25,
    )
    response = restore_audio(client, moved_project)

    assert response.status_code == 202
    body = response.json()
    # The take's seconds, unchanged by the drag: 11.75 s, not 12.0 s, and 107 frames' worth.
    window = comfy.prompts[-1]["mvp:song"]["inputs"]
    assert window["seek_seconds"] == 11.75
    assert window["duration"] == pytest.approx(107 / 24)
    # The same window the undragged shot sent, field for field. Reading the live `start` would
    # have made this 12.0 s — a quarter second off the mouth — for 124 frames' worth of song.
    first = comfy.prompts[0]["mvp:song"]["inputs"]
    assert (window["seek_seconds"], window["duration"]) == (
        first["seek_seconds"],
        first["duration"],
    )
    # The count the render asked for, not the count a render of the new window would: the
    # edited window is 5.25 s, which is 141 frames, and none of these three numbers is it.
    assert over_render_frames(5.25) == 141
    assert body["requested_frames"] == unmoved["requested_frames"] == 107
    assert body["requested_picture_seconds"] == pytest.approx(107 / 24)
    assert body["audio_seconds"] == pytest.approx(unmoved["audio_seconds"])

    # The claim is now true, and the move is said rather than hidden.
    assert body["describes_take"] is True
    assert "window has been edited since the take was rendered" in body["length_note"]
    assert "12.25s for 5.25s" in body["length_note"]  # what the timeline reads now
    assert "12s for 3.75s" in body["length_note"]  # what the take was rendered for
    # And an unmoved window says none of it: the sentence appears only when a window moved.
    assert "window has been edited" not in unmoved["length_note"]
    assert unmoved["describes_take"] is True


def test_an_unmoved_window_reports_exactly_what_it_did_before_the_snapshot_existed(
    tmp_path: Path,
):
    """The pin on the other side: recording the window changed nothing for a take nobody moved.

    Same shot twice — once with the snapshot a render now writes, once with the pre-2026-08-21
    manifest that carries the lead alone. The payload and every number in the report are
    identical; the only difference is `describes_take` and the sentence that says why, which is
    the whole of what "stop claiming" means here.
    """
    from music_video_producer.app import RESTORE_AUDIO_UNDESCRIBED_TAKE

    client, store, comfy = make_client(tmp_path)
    described = restore_audio(client, restorable_project(store, tmp_path)).json()
    undescribed = restore_audio(
        client,
        restorable_project(
            store, tmp_path, latest_take_start=0.0, latest_take_duration=0.0
        ),
    ).json()

    windows = [
        (prompt["mvp:song"]["inputs"]["seek_seconds"], prompt["mvp:song"]["inputs"]["duration"])
        for prompt in comfy.prompts
    ]
    assert windows[1] == windows[0]
    for field in ("audio_seconds", "requested_picture_seconds", "requested_frames"):
        assert described[field] == undescribed[field], field
    assert described["lengths_match"] == undescribed["lengths_match"] is True

    assert described["describes_take"] is True
    assert RESTORE_AUDIO_UNDESCRIBED_TAKE not in described["length_note"]
    assert undescribed["describes_take"] is False
    assert RESTORE_AUDIO_UNDESCRIBED_TAKE in undescribed["length_note"]
    # The undescribed note never claims the window moved either — it cannot know.
    assert "window has been edited" not in undescribed["length_note"]


def test_a_legacy_take_at_zero_seconds_is_placed_but_never_described(tmp_path: Path):
    """Finding 4: the 0 s exemption, and the sentence it used to make untrue.

    `RESTORE_AUDIO_NO_LEAD_REFUSAL` exempts a shot at 0 s, and the argument it used to give —
    "a post-margin submission records zero only at 0 s" — is true and proves nothing: a take at
    0 s is exactly as likely to be a legacy one as a take at 12 s, and a recorded zero there
    could not have been anything else. What makes the exemption safe is the *offset*: at a
    window start of 0 s the take begins at song second 0 whether it was rendered before the
    over-render margin or after it, so there is no sync to guess wrong about.

    What can still differ is the length — a pre-margin take holds 90 frames where this route
    reports the 107 a render would ask for now — and that is why the report must not describe
    such a take. It does not: `describes_take` is false and the note says where its numbers came
    from. And it does not explain anything either, because nothing here is a mismatch: the two
    lengths agree, so the branch that names the song running out is not reached at all.
    """
    from music_video_producer.app import RESTORE_AUDIO_UNDESCRIBED_TAKE

    client, store, comfy = make_client(tmp_path)
    legacy = restorable_project(
        store,
        tmp_path,
        start=0.0,
        latest_take_lead=0.0,
        latest_take_start=0.0,
        latest_take_duration=0.0,
    )

    response = restore_audio(client, legacy)

    assert response.status_code == 202
    body = response.json()
    # Placed at the song's first sample, which is where such a take begins either way.
    assert comfy.prompts[-1]["mvp:song"]["inputs"]["seek_seconds"] == 0.0
    # Not described, and the sentence says so instead of asserting the render asked for 107.
    assert body["describes_take"] is False
    assert RESTORE_AUDIO_UNDESCRIBED_TAKE in body["length_note"]
    # No mismatch here, so no cause is named for one. This is the assertion the old wording
    # failed: the `else` branch had become reachable for a second reason it did not name.
    assert body["lengths_match"] is True
    assert "The two agree." in body["length_note"]
    assert "runs out" not in body["length_note"]
    assert "ends before" not in body["length_note"]


def test_a_submission_records_the_window_its_take_is_rendered_for(tmp_path: Path):
    """The other half of finding 2: the number that was missing is now written.

    Recorded at the moment of truth beside `latest_take_lead`, because it cannot be derived
    later — nothing in a take's bytes says which window produced it. Written on every H3
    submission and not only on the song-audio ones: the snapshot describes the take, and which
    of them can be restored is a different question asked later. (Its clearing for a hand-picked
    clip is pinned with the lead's, in the select-take test.)
    """
    client, store, comfy = make_client(tmp_path)
    project = windowed_project(store, client, start=12.0, duration=3.75)

    assert submit_h3(client, project.id, project.shots[0].id).status_code == 202

    assert len(comfy.prompts) == 1  # one render, and the snapshot is that render's
    recorded = store.get(project.id).shots[0]
    assert recorded.latest_take_start == 12.0
    assert recorded.latest_take_duration == 3.75
    assert recorded.latest_take_lead == 0.25
    # It is the window as it read at submission, so editing the shot afterwards leaves it be —
    # which is the entire point of recording it.
    live = store.get(project.id)
    live.shots[0].start = 20.0
    live.shots[0].duration = 6.0
    store.save(live)
    after = store.get(project.id).shots[0]
    assert (after.latest_take_start, after.latest_take_duration) == (12.0, 3.75)


def test_a_restoration_in_flight_refuses_a_second_one_and_so_does_a_live_render(
    tmp_path: Path,
):
    """Concurrency, read off the job records alone.

    A restoration writes nothing to the Shot, so `Shot.status` is not evidence about it — the
    jobs are. Covers a live render and a live enhancement too: both can move the take this reads
    or the file it writes beside.
    """
    client, store, comfy = make_client(tmp_path)
    project = restorable_project(store, tmp_path)
    assert restore_audio(client, project).status_code == 202
    assert store.get(project.id).shots[0].status == "complete"

    second = restore_audio(client, store.get(project.id))

    assert second.status_code == 409
    assert second.json()["detail"] == RESTORE_AUDIO_IN_FLIGHT_REFUSAL.format(
        shot=shot_label(store.get(project.id), store.get(project.id).shots[0])
    )
    assert len(comfy.prompts) == 1

    rendering = restorable_project(store, tmp_path)
    rendering.shots[0].status = "queued"
    store.save(rendering)

    assert restore_audio(client, rendering).status_code == 409
    assert len(comfy.prompts) == 1


def test_a_restoration_never_asks_the_readiness_questions_a_render_asks(tmp_path: Path):
    """No prompt gate and no `ready` status gate: this graph has neither a prompt nor a sampler.

    Borrowing `generate_h3`'s gates here would refuse a real take for fields the work does not
    read. What must exist is a take and a window, which the refusals above check.
    """
    client, store, comfy = make_client(tmp_path)
    project = restorable_project(store, tmp_path, prompt="", status="draft")

    assert restore_audio(client, project).status_code == 202
    assert len(comfy.prompts) == 1


def test_a_shot_without_an_expansion_submits_exactly_what_it_always_did():
    """The safety argument for the whole expansion feature, as one equality.

    `reference_prompt` is the only thing between a Shot and what the reference render
    submits. For a Shot nobody has expanded it must produce the string this route built
    before the field existed — reference map, then intent — because anything else would
    silently change every render in every existing project.

    Written as the literal pre-change expression rather than a call back into the helper,
    which would pass no matter what the helper did.
    """
    shot = Shot(start=0.0, duration=3.75, prompt="The wolf paces through birch.")
    tags = ["<Picture 1> is Lucy", "<Audio 1> is the master song for synchronization"]

    assert reference_prompt(shot, tags) == (
        f"Reference map: {'; '.join(tags)}. {shot.prompt}"
    )


def test_an_expansion_is_submitted_alone_without_the_reference_map_preamble():
    """Dropping the preamble is the point, not an omission.

    An H3-format prompt is a document with a required shape — an optional instruction
    line first, then the three named fields. Prefixing prose to it would put text in
    front of the instruction line and break the very format the expansion exists to
    produce. The tags are not lost: the specialist was given them and wrote them into
    the description as <Picture 1>, which is where the guide puts them.
    """
    expansion = (
        "integrated_multimodal_description: [Shot 1] <Picture 1> stands in the warehouse.\n"
        "overall_soundscape: Distant traffic behind a low room tone.\n"
        "non_diegetic_music: N/A"
    )
    shot = Shot(start=0.0, duration=3.75, prompt="Wide on Lucy.", h3_prompt=expansion)

    submitted = reference_prompt(shot, ["<Picture 1> is Lucy"])
    assert submitted == expansion
    assert "Reference map" not in submitted
    assert submitted.startswith("integrated_multimodal_description:")


def test_an_expansion_of_only_whitespace_is_treated_as_absent():
    """Otherwise a field cleared to spaces would submit a blank prompt and render noise."""
    blank = "   " + "\n" + "  "
    shot = Shot(start=0.0, duration=3.75, prompt="Wide on Lucy.", h3_prompt=blank)
    assert reference_prompt(shot, ["<Picture 1> is Lucy"]).startswith("Reference map:")


def test_a_project_deletes_only_with_its_confirmation_and_takes_survive(tmp_path: Path):
    """The switcher can finally shed a night of experiments (analyst finding, 2026-08-20).
    The first call is the sentence naming the loss; only the flag deletes; rendered takes
    live outside the project directory and are untouched by design."""
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Disposable"))
    unconfirmed = client.delete(f"/api/projects/{project.id}")
    assert unconfirmed.status_code == 409
    assert "confirm_delete" in unconfirmed.json()["detail"]
    assert store.manifest_path(project.id).is_file()
    deleted = client.delete(f"/api/projects/{project.id}?confirm_delete=true")
    assert deleted.status_code == 200
    assert not store.project_dir(project.id).exists()
    assert client.get(f"/api/projects/{project.id}").status_code == 404


def test_an_asset_deletes_unless_a_shot_cites_it(tmp_path: Path):
    """Two dialogs promised deletion and no route existed. The citation refusal names the
    shots, because a dangling citation is the render-time 422 this would manufacture."""
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Prunable"))
    (store.project_dir(project.id) / "media" / "assets").mkdir(parents=True)
    (store.project_dir(project.id) / "media" / "assets" / "w.png").write_bytes(b"png")
    project.assets = [Asset(id="asset_w", name="Wolf", kind="image",
                            path="media/assets/w.png", source="upload")]
    project.shots = [Shot(id="shot_c", start=0, duration=4, prompt="Wolf B-roll",
                          citations=[AssetCitation(asset_id="asset_w", role="reference", order=0)])]
    store.save(project)
    cited = client.delete(f"/api/projects/{project.id}/assets/asset_w")
    assert cited.status_code == 422
    assert "SHOT 01" in cited.json()["detail"]
    fresh = store.get(project.id)
    # Both projections: the model reconciles `citations` back from a lingering `asset_ids`.
    fresh.shots[0].citations = []
    fresh.shots[0].asset_ids = []
    store.save(fresh)
    freed = client.delete(f"/api/projects/{project.id}/assets/asset_w")
    assert freed.status_code == 200
    assert freed.json()["assets"] == []
    assert not (store.project_dir(project.id) / "media" / "assets" / "w.png").exists()


def test_cancelling_a_job_settles_it_and_releases_the_shot(tmp_path: Path):
    """Both halves in one act — dequeue on ComfyUI AND settle the record — because this
    same night proved what a queue-only cancel leaves behind: a job stuck 'queued' until
    the reconciler's strike counter cleans it up.

    And "releases" now means what the `×`'s tooltip has always claimed. Until 2026-08-23 this
    route wrote `error` onto a shot that had never produced anything, which is what put
    **Flag for re-render** — a control about a take the Director does not like — in front of a
    Director whose render had produced no take at all. It goes back to `ready`.
    """
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Cancellable"))
    project.shots = [Shot(id="shot_r", start=0, duration=4, prompt="Wide", status="queued")]
    project.jobs = [RenderJob(id="job_r", kind="h3", target_id="shot_r",
                              status="queued", prompt_id="prompt-r")]
    store.save(project)
    cancelled = client.delete(f"/api/projects/{project.id}/jobs/job_r")
    assert cancelled.status_code == 200
    assert comfy.cancelled == ["prompt-r"]
    body = cancelled.json()
    assert body["jobs"][0]["status"] == "cancelled"
    assert body["shots"][0]["status"] == "ready"
    settled = client.delete(f"/api/projects/{project.id}/jobs/job_r")
    assert settled.status_code == 422


def test_cancelling_a_render_over_an_existing_take_leaves_the_shot_settled(tmp_path: Path):
    """The other half of the release rule, and the one that must NOT move: a shot re-rendering
    over a take it already holds is settled as `error`, keeps the take, and goes on offering
    Render again and Flag for re-render — which are the right controls for a take that exists.

    Releasing this one to `ready` would put a shot with a perfectly good take straight back into
    Generate All's ready set to be rendered over, which is the harm the two cases exist to keep
    apart. `latest_output` is the test, never `status` — see `batch.shot_has_take`.
    """
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Retake"))
    project.shots = [Shot(id="shot_k", start=0, duration=4, prompt="Wide", status="queued",
                          latest_output="takes/kept_00001.mp4")]
    project.jobs = [RenderJob(id="job_k", kind="h3", target_id="shot_k",
                              status="running", prompt_id="prompt-k")]
    store.save(project)
    cancelled = client.delete(f"/api/projects/{project.id}/jobs/job_k")
    assert cancelled.status_code == 200
    shot = cancelled.json()["shots"][0]
    assert shot["status"] == "error"
    # The take is untouched by the cancellation: nothing here clears a pointer.
    assert shot["latest_output"] == "takes/kept_00001.mp4"


def test_select_take_switches_takes_and_attaches_video_assets(tmp_path: Path):
    """The Director's asks (2026-08-20): switch a shot's clip to a different take, and
    attach an uploaded video as a shot's clip. One pointer moves; provenance is the job
    history; an uploaded video is copied under the output root so every reader of
    latest_output keeps its single root."""
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Takes"))
    shot = Shot(id="shot_t", start=0.0, duration=4.0, prompt="Wide", status="complete",
                latest_output="p/shots/take_00002.mp4")
    project.shots = [shot]
    project.jobs = [
        RenderJob(kind="h3", target_id="shot_t", status="complete", prompt_id="p1",
                  output_files=["p/shots/take_00001.mp4"]),
        RenderJob(kind="h3", target_id="shot_t", status="complete", prompt_id="p2",
                  output_files=["p/shots/take_00002.mp4"]),
    ]
    project.assets = [
        Asset(id="asset_clip", name="B-roll drive", kind="video",
              path="media/assets/broll.mp4", source="upload"),
        Asset(id="asset_img", name="Poster", kind="image", path="media/assets/p.png",
              source="upload"),
    ]
    store.save(project)
    output_root = tmp_path / "comfy" / "output"
    (output_root / "p" / "shots").mkdir(parents=True)
    (output_root / "p" / "shots" / "take_00001.mp4").write_bytes(b"one")
    (output_root / "p" / "shots" / "take_00002.mp4").write_bytes(b"two")
    (store.project_dir(project.id) / "media" / "assets").mkdir(parents=True)
    (store.project_dir(project.id) / "media" / "assets" / "broll.mp4").write_bytes(b"clip")

    # An earlier take of the shot's own history.
    switched = client.post(
        f"/api/projects/{project.id}/shots/shot_t/select-take",
        json={"output": "p/shots/take_00001.mp4"},
    )
    assert switched.status_code == 200
    assert switched.json()["shots"][0]["latest_output"] == "p/shots/take_00001.mp4"

    # Another shot's file is refused: the job history is the provenance check.
    foreign = client.post(
        f"/api/projects/{project.id}/shots/shot_t/select-take",
        json={"output": "p/shots/other_take.mp4"},
    )
    assert foreign.status_code == 422

    # An uploaded video asset lands under the output root and becomes the clip, with the
    # over-render bookkeeping cleared — no margin exists in a hand-picked file.
    stored = store.get(project.id)
    stored.shots[0].latest_take_lead = 0.25
    stored.shots[0].latest_take_start = 12.0
    stored.shots[0].latest_take_duration = 3.75
    stored.shots[0].trim_nudge = 0.1
    store.save(stored)
    attached = client.post(
        f"/api/projects/{project.id}/shots/shot_t/select-take",
        json={"asset_id": "asset_clip"},
    )
    assert attached.status_code == 200
    body = attached.json()["shots"][0]
    assert body["latest_output"] == f"music-video-producer/{project.id}/clips/asset_clip.mp4"
    assert body["latest_take_lead"] == 0 and body["trim_nudge"] == 0
    # The window snapshot goes with the lead: no render of this plan made that file, so it
    # describes no window of it either, and `restore_song_audio` reads the absence.
    assert body["latest_take_start"] == 0 and body["latest_take_duration"] == 0
    assert (output_root / "music-video-producer" / project.id / "clips" / "asset_clip.mp4").read_bytes() == b"clip"

    # Not a video: refused with the remedy.
    not_video = client.post(
        f"/api/projects/{project.id}/shots/shot_t/select-take",
        json={"asset_id": "asset_img"},
    )
    assert not_video.status_code == 422


def test_expansion_allows_rederiving_prose_on_a_rendered_song_audio_shot():
    """The Director's live break (2026-08-20): on a fully-rendered plan, no intent edit
    could ever reach the prompt again — "Expand Prompt Again" refused every shot as
    rendered. A song-audio reference shot's expansion is deterministic prose, so
    re-deriving it loses no record; locked stays locked, and the document modes keep the
    full refusal because their expansions are model output."""
    from music_video_producer.app import expansion_write_refusal

    rendered = {"start": 0.0, "duration": 4.0, "prompt": "Lean-in at the mic.",
                "status": "complete", "latest_output": "takes/one.mp4"}
    assert expansion_write_refusal(Shot(**rendered, use_song_audio=True)) is None
    assert expansion_write_refusal(Shot(**rendered)) == "rendered"
    assert expansion_write_refusal(
        Shot(**rendered, use_song_audio=True, mode="first_last")
    ) == "rendered"
    assert expansion_write_refusal(
        Shot(**rendered, use_song_audio=True, locked=True)
    ) == "locked"


def test_align_lyrics_hears_the_track_once_and_fills_the_sections(tmp_path: Path):
    """The Director's ask (2026-08-20): the tagged sheet plus Whisper's clock fills the
    section boxes. One transcription, kept on the Song beside the vocal spans; existing
    boxes are the Director's marks and are refused without replace_sections; a sheet
    with no [Tag] blocks is a remedy sentence, not a guess."""
    words = []
    clock = 8.0
    for text in ["I", "keep", "running", "through", "the", "night", "chasing", "every", "fading", "light"]:
        words.append((text, clock, clock + 0.4)); clock += 0.5
    clock = 30.0
    for text in ["lick", "it", "hard", "lap", "it", "up", "right", "now", "come", "do", "that", "wicked", "deed"]:
        words.append((text, clock, clock + 0.4)); clock += 0.5
    transcriptions = []

    def transcriber(path):
        transcriptions.append(str(path))
        return words

    client, store, _ = make_client(tmp_path, transcriber=transcriber)
    project = store.create(Project(name="Aligned"))
    media = store.media_dir(project.id) / "songs"
    media.mkdir(parents=True)
    (media / "track.mp3").write_bytes(b"not audio, never decoded: the transcriber is ours")
    project.song = Song(
        title="Night Runner", source="imported", path="media/songs/track.mp3",
        duration=60.0,
        lyrics="[Verse]\nI keep runnin' through the night\nchasing every fadin' light\n"
               "[Chorus]\nlick it hard lap it up right now\ncome do that wicked deed\n",
    )
    store.save(project)

    aligned = client.post(f"/api/projects/{project.id}/song/align-lyrics", json={})
    assert aligned.status_code == 200
    body = aligned.json()
    assert [s["label"] for s in body["sections"]] == ["Intro", "Verse", "Chorus"]
    assert body["sections"][1]["start"] == 8.0
    assert body["sections"][2]["start"] == 30.0
    assert body["sections"][-1]["start"] + body["sections"][-1]["duration"] == 60.0
    assert all(s["prompt"] == "" for s in body["sections"])
    stored = store.get(project.id)
    assert stored.song.lyric_words and stored.song.vocal_spans
    assert len(transcriptions) == 1

    # Boxes exist now: refused without the flag, replaced with it — and the stored words
    # are reused, so the track is never transcribed twice.
    refused = client.post(f"/api/projects/{project.id}/song/align-lyrics", json={})
    assert refused.status_code == 409
    assert "replace_sections" in refused.json()["detail"]
    replaced = client.post(
        f"/api/projects/{project.id}/song/align-lyrics", json={"replace_sections": True}
    )
    assert replaced.status_code == 200
    assert len(transcriptions) == 1

    # A sheet without tags is a remedy, not a guess.
    untagged = store.get(project.id)
    untagged.song.lyrics = "just words with no structure tags"
    store.save(untagged)
    no_tags = client.post(
        f"/api/projects/{project.id}/song/align-lyrics", json={"replace_sections": True}
    )
    assert no_tags.status_code == 422
    assert "[Verse]" in no_tags.json()["detail"]


def test_the_shots_write_refuses_a_stale_revision_when_the_client_sends_one(tmp_path: Path):
    """The whole-manifest guard hole, finally with a lock the interface sends.

    Live on 2026-08-19: the Director's open tab fired a background shot save with a list
    loaded before a repair pass, and one PUT reverted 32 prompts and four singing flags at
    once. `updated_at` in the body is the revision the list was edited against — enforced
    when present, in `replace_project`'s exact words; absent keeps the wire every script
    and older client already speaks, hazard and all."""
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Revisions"))
    project.shots = [Shot(id="shot_a", start=0, duration=5, prompt="Wide on the room")]
    store.save(project)
    current = client.get(f"/api/projects/{project.id}").json()

    # Fresh revision: accepted, and the reply carries the new one.
    body = {"shots": current["shots"], "updated_at": current["updated_at"]}
    first = client.put(f"/api/projects/{project.id}/shots", json=body)
    assert first.status_code == 200
    assert first.json()["updated_at"] != current["updated_at"]

    # The same (now stale) revision again: refused, nothing written.
    body["shots"][0]["prompt"] = "A stale tab's idea of the plan"
    stale = client.put(f"/api/projects/{project.id}/shots", json=body)
    assert stale.status_code == 409
    assert "refresh before replacing" in stale.json()["detail"]
    assert store.get(project.id).shots[0].prompt == "Wide on the room"

    # No revision: the wire every existing caller speaks, accepted exactly as before.
    bare = client.put(f"/api/projects/{project.id}/shots", json={"shots": current["shots"]})
    assert bare.status_code == 200


def test_a_singing_song_audio_shot_gains_the_measured_sings_clause():
    """The lipsync half of the 2026-08-19 measurements: the takes the Director praised
    both said the character sings to camera, and a prompt with no singing language
    rendered a closed mouth. The clause is appended only when the intent does not
    already say so, only for song-audio shots, and only when the shot sings."""
    from music_video_producer.app import (
        SONG_AUDIO_CONTINUITY_CLAUSE,
        SONG_AUDIO_SINGS_CLAUSE,
        SONG_AUDIO_SINGS_CLAUSE_BARE,
    )

    tags = ["<Picture 1> is Lucy", "<Audio 1> is the master song for synchronization"]
    base = {"start": 0.0, "duration": 3.75, "prompt": "Close on her face at the mic.",
            "use_song_audio": True}
    cited = [AssetCitation(asset_id="asset_1", role="reference", order=0)]

    singing = Shot(**base, singing="singing", citations=cited)
    assert reference_prompt(singing, tags).endswith(
        f"{SONG_AUDIO_SINGS_CLAUSE} {SONG_AUDIO_CONTINUITY_CLAUSE}"
    )
    # Without a reference sheet the wording cannot claim one.
    uncited = Shot(**base, singing="singing")
    assert f"{SONG_AUDIO_SINGS_CLAUSE_BARE} " in reference_prompt(uncited, tags)
    # An intent that already sings gets no doubled clause.
    already = Shot(start=0.0, duration=3.75, prompt="She sings to camera, leaning in.",
                   use_song_audio=True, singing="singing", citations=cited)
    assert "sings to camera." not in reference_prompt(already, tags).removeprefix(
        f"Reference map: {'; '.join(tags)}. {already.prompt}"
    )
    # Not singing: no sings clause, but the continuity anchor still lands — the live
    # sheet-morph artifact hit a NOT-singing establishing shot (run 2 shot 07).
    silent = Shot(**base, singing="not_singing", citations=cited)
    assert reference_prompt(silent, tags) == (
        f"Reference map: {'; '.join(tags)}. {silent.prompt} {SONG_AUDIO_CONTINUITY_CLAUSE}"
    )
    # A shot not riding the song: the string this route always built, byte-identical.
    plain = Shot(start=0.0, duration=3.75, prompt="Close on her face at the mic.",
                 singing="not_singing", citations=cited)
    assert reference_prompt(plain, tags) == (
        f"Reference map: {'; '.join(tags)}. {plain.prompt}"
    )
    # The section look still lands after every clause.
    sectioned = reference_prompt(singing, tags, section_prompt="on the canopy bed")
    assert sectioned.endswith(
        f"{SONG_AUDIO_SINGS_CLAUSE} {SONG_AUDIO_CONTINUITY_CLAUSE} "
        "Section look: on the canopy bed"
    )


def test_measured_silence_outranks_a_singing_mark():
    """The Director's live catch (2026-08-19): shot 02 was marked singing over the
    instrumental intro, so the sings clause told H3 to sing over a voiceless reference —
    and it invented its own words and lipsynced to them. With `Song.vocal_spans`
    measured, a voiceless window gets no clause whatever the mark says; an unmeasured
    song (`[]` → overlap None) changes nothing, and a window with voice keeps its clause."""
    from music_video_producer.app import SONG_AUDIO_SINGS_CLAUSE_BARE
    from music_video_producer.timeline import shot_vocal_overlap

    song = Song(title="Harder Faster", source="imported", duration=154.6,
                vocal_spans=[(11.0, 87.7), (89.1, 99.2)])
    intro = Shot(id="shot_i", start=4.0, duration=5.66, prompt="Slow push down the aisle.",
                 singing="singing", use_song_audio=True)
    sung = Shot(id="shot_s", start=19.33, duration=4.0, prompt="Lean-in at the mic.",
                singing="singing", use_song_audio=True)
    assert shot_vocal_overlap(song, start=4.0, duration=5.66) == 0.0
    assert shot_vocal_overlap(None, start=4.0, duration=5.66) is None
    assert shot_vocal_overlap(
        Song(title="x", source="imported"), start=4.0, duration=5.66
    ) is None

    measured = Project(name="Measured", song=song, shots=[intro, sung])
    assert "sings to camera" not in song_audio_prose(measured, intro)
    assert f"{SONG_AUDIO_SINGS_CLAUSE_BARE} " in song_audio_prose(measured, sung)
    # Unmeasured: the mark is trusted, exactly as before spans existed.
    unmeasured = Project(
        name="Unmeasured",
        song=Song(title="Harder Faster", source="imported", duration=154.6),
        shots=[intro.model_copy(deep=True)],
    )
    assert f"{SONG_AUDIO_SINGS_CLAUSE_BARE} " in song_audio_prose(
        unmeasured, unmeasured.shots[0]
    )


def test_song_audio_prose_is_the_submit_walks_own_string(tmp_path: Path):
    """The prose expansion and the render must name the same slots: `song_audio_prose`
    stores what `generate_h3`'s reference branch will submit, byte for byte — same
    citation walk, same numbering, same master-song line — even while a stale document
    expansion is still on the Shot."""
    from music_video_producer.app import (
        reference_map_tag_lines,
    )

    project = Project(
        name="Prose",
        song=Song(title="Harder Faster", source="imported", duration=154.6),
        assets=[
            Asset(id="asset_sheet", name="HarderFaster · multiview", kind="character",
                  path="a.png", source="upload"),
        ],
        shots=[
            Shot(id="shot_p", start=19.33, duration=4.0, prompt="Over-the-shoulder lean-in.",
                 singing="singing", use_song_audio=True,
                 h3_prompt="integrated_multimodal_description: stale document",
                 citations=[AssetCitation(asset_id="asset_sheet", role="reference", order=0)]),
        ],
        sections=[SongSection(label="Verse", start=10.0, duration=20.0,
                              prompt="moonlit warehouse")],
    )
    shot = project.shots[0]
    tags = reference_map_tag_lines(project, shot)
    assert tags == [
        "<Picture 1> is HarderFaster · multiview",
        "<Audio 1> is the master song for synchronization",
    ]
    prose = song_audio_prose(project, shot)
    assert prose == (
        "Reference map: <Picture 1> is HarderFaster · multiview; "
        "<Audio 1> is the master song for synchronization. "
        "Over-the-shoulder lean-in. "
        "The character from the reference sheet sings to camera. "
        "Stable face and wardrobe, one continuous take. "
        "Section look: moonlit warehouse"
    )
    assert "integrated_multimodal_description" not in prose


def test_a_song_audio_reference_shots_expansion_is_deterministic_and_calls_no_model():
    """The night's decisive measurement (2026-08-19, eight renders, one A/B shot): every
    H3-document prompt made the sampler synthesize its own score over the referenced
    track (≤0.43 envelope correlation), every plain-prose reference-map prompt followed
    it (≥0.77; 0.94 with the sings clause). So a song-audio reference shot's expansion
    is `song_audio_prose`, and the director is never called for it."""
    from music_video_producer.app import attempt_expansion

    class ExplodingDirector:
        async def expand_shot(self, **_):
            raise AssertionError("the model must not be called for song-audio prose")

    project = Project(
        name="Prose",
        song=Song(title="Harder Faster", source="imported", duration=154.6),
        shots=[Shot(id="shot_p", start=19.33, duration=4.0, prompt="Lean-in at the mic.",
                    singing="singing", use_song_audio=True)],
    )
    outcome = asyncio.run(
        attempt_expansion(project, project.shots[0], director=ExplodingDirector())
    )
    assert outcome.kind == "expanded"
    assert outcome.text == song_audio_prose(project, project.shots[0])


GOOD_EXPANSION = (
    "integrated_multimodal_description: [Shot 1] A grey wolf paces through birch trunks "
    "under low amber light; the camera drifts with it, handheld.\n"
    "overall_soundscape: Dry needles compress underfoot. Wind moves through the branches.\n"
    "non_diegetic_music: A low cello figure at a slow tempo, swelling once and receding."
)


class ExpandingShotDirector(FakeDirector):
    """Returns one fixed H3 prompt and records the input it was handed."""

    def __init__(self, text: str = GOOD_EXPANSION):
        self.text = text
        self.inputs: list[dict] = []
        self.prompts: list[str] = []

    async def expand_shot(self, *, shot_input, system_prompt, **_):
        self.inputs.append(shot_input)
        self.prompts.append(system_prompt)
        return self.text


def _expandable(client, store, **shot_kwargs):
    project = store.create(Project(name="Pass two"))
    shot = Shot(start=0.0, duration=3.75, prompt="Wolf B-roll", **shot_kwargs)
    client.put(
        f"/api/projects/{project.id}/shots",
        json={"shots": [json.loads(shot.model_dump_json())]},
    )
    return project.id, shot.id


def test_expanding_a_shot_writes_only_its_h3_prompt(tmp_path: Path):
    """The intent survives, which is the whole reason this is a second field."""
    director = ExpandingShotDirector()
    client, store = make_client_with_director(tmp_path, director)
    project_id, shot_id = _expandable(client, store)

    response = client.post(f"/api/projects/{project_id}/shots/{shot_id}/expand-prompt")

    assert response.status_code == 200
    body = response.json()
    assert body["applied"] is True
    assert body["problems"] == []

    stored = store.get(project_id).shots[0]
    assert stored.h3_prompt == GOOD_EXPANSION
    assert stored.prompt == "Wolf B-roll"
    assert stored.status == "draft"
    assert stored.prompt_id == ""


def test_a_malformed_expansion_is_reported_and_never_stored(tmp_path: Path):
    """The one outcome checking before a render exists to prevent.

    A malformed prompt in the manifest would be submitted by the *next* render, and the
    failure would surface as a bad take rather than as a message. So it is returned with its
    problems and the Shot is left exactly as it was.
    """
    director = ExpandingShotDirector("A grey wolf pacing through trees. 35mm, grainy.")
    client, store = make_client_with_director(tmp_path, director)
    project_id, shot_id = _expandable(client, store)

    body = client.post(
        f"/api/projects/{project_id}/shots/{shot_id}/expand-prompt"
    ).json()

    assert body["applied"] is False
    assert body["problems"]
    # The refused text comes back so the Director can read and judge it, the same argument
    # `MessageNotice.raw` makes for refused Director output.
    assert body["prompt"] == "A grey wolf pacing through trees. 35mm, grainy."
    assert store.get(project_id).shots[0].h3_prompt == ""


