def test_unapproving_rescues_a_status_only_approval(tmp_path: Path):
    """The one way out of a state only hand-edits can make.

    A Shot with the `approved` status and no `approved_output` is refused by mark-ready (not its
    status class), by render-again (the approval refusal reads either signal) and by everything
    downstream — so un-approve must recognise the same either-signal definition render-again
    refuses by, or the Shot is stuck.
    """
    client, store, _ = make_client(tmp_path)
    project = drafted_shot(
        store, "Status only", status="approved", latest_output="takes/one.mp4"
    )
    assert render_again(client, project.id, "shot_first").status_code == 422

    response = unapprove(client, project.id, "shot_first")

    assert response.status_code == 200
    saved = ProjectStore(tmp_path).get(project.id).shots[0]
    assert saved.status == "complete"
    assert saved.approved_output == ""


def test_the_approve_route_is_the_one_writer_of_approval(tmp_path: Path):
    """AGENTS.md's rule and the spec's single-writer clause, asserted both ways.

    Behaviorally: a completion that lands a take — the likeliest place a second writer would
    creep in, because `apply_job_history` is already writing the Shot — moves `latest_output`
    and stops there. And in the source: exactly two assignments to `approved_output` exist in
    the whole package, both in `app.py`'s approve/unapprove pair, and exactly one write of the
    `approved` status. The scan is what fails when a well-meaning writer is added somewhere the
    behavioral half does not exercise.
    """
    client, store, comfy = make_client(tmp_path)
    project_id, _, _ = rendered_shot(client, store, comfy, "Completed, not approved")
    landed = ProjectStore(tmp_path).get(project_id).shots[0]
    assert landed.latest_output.endswith("shot_take-h3_00001.mp4")
    assert landed.status == "complete"
    assert landed.approved_output == ""

    package = Path("src/music_video_producer")
    assignments: dict[str, int] = {}
    status_writes: dict[str, int] = {}
    for source in package.rglob("*.py"):
        text = source.read_text(encoding="utf-8")
        wrote = len(re.findall(r"\.approved_output\s*=[^=]", text))
        if wrote:
            assignments[source.name] = wrote
        wrote_status = len(re.findall(r"\.status\s*=\s*['\"]approved['\"]", text))
        if wrote_status:
            status_writes[source.name] = wrote_status
    assert assignments == {"app.py": 2}, assignments
    assert status_writes == {"app.py": 1}, status_writes
    # And the frontend never writes it either: the one assignment in the workspace is the empty
    # default a brand-new Shot is born with.
    workspace = (package / "web" / "assets" / "app.js").read_text(encoding="utf-8")
    contract = (package / "web" / "assets" / "api.js").read_text(encoding="utf-8")
    for name, text in (("app.js", workspace), ("api.js", contract)):
        writes = re.findall(r"approved_output\s*[:=]\s*(?!\s*['\"]['\"])", text)
        assert writes == [], (name, writes)


def test_while_approved_the_take_cannot_move_and_unapproval_is_the_way_back(tmp_path: Path):
    """The invariant, pinned end to end: `approved_output == latest_output` for the life of an
    approval — because everything that could move the pointer refuses an approved Shot — and
    un-approve is the one gate back to an ordinary re-renderable complete Shot.

    The round trip renders again after un-approving and lands a second take, which also proves
    the other single-writer half in motion: the completion moves `latest_output` and leaves the
    cleared approval cleared.
    """
    client, store, comfy = make_client(tmp_path)
    project_id, shot_id, _ = rendered_shot(client, store, comfy, "Invariant")
    assert approve(client, project_id, shot_id).status_code == 200
    approved = ProjectStore(tmp_path).get(project_id).shots[0]
    assert approved.approved_output == approved.latest_output

    # Every route that could displace the take refuses, and the refusal names the approval.
    reopen = render_again(client, project_id, shot_id)
    assert reopen.status_code == 422
    assert reopen.json()["detail"] == RENDER_AGAIN_APPROVED_REFUSAL.format(
        shot=f"SHOT 01 ({shot_id})"
    )
    assert mark_ready(client, project_id, shot_id).status_code == 422
    assert mark_draft(client, project_id, shot_id).status_code == 422
    assert submit_h3(client, project_id, shot_id).status_code == 422
    still = ProjectStore(tmp_path).get(project_id).shots[0]
    assert still.approved_output == still.latest_output
    assert still.status == "approved"
    assert len(comfy.prompts) == 1

    # Un-approve, and the same Shot is an ordinary complete Shot again: re-openable,
    # submittable, and its second take lands without resurrecting the withdrawn approval.
    assert unapprove(client, project_id, shot_id).status_code == 200
    assert render_again(client, project_id, shot_id).status_code == 200
    resubmitted = submit_h3(client, project_id, shot_id)
    assert resubmitted.status_code == 202
    assert len(comfy.prompts) == 2
    land_take(client, comfy, project_id, resubmitted.json()["id"], "shot_take-h3_00002.mp4")
    second = ProjectStore(tmp_path).get(project_id).shots[0]
    assert second.latest_output.endswith("shot_take-h3_00002.mp4")
    assert second.approved_output == ""
    assert second.status == "complete"

    # Approving now names the second take: what is approved is always the take that was watched.
    assert approve(client, project_id, shot_id).status_code == 200
    reapproved = ProjectStore(tmp_path).get(project_id).shots[0]
    assert reapproved.approved_output == second.latest_output


def test_approval_snapshots_the_window_and_unapproval_clears_it(tmp_path: Path):
    """AD-13's amendment, both halves of the write and the one-writer scan.

    The approval is a decision about one take *in one window* — assembly trims the take to
    the window, so a window edited after approval makes the approved file the wrong length
    for the plan. The snapshot is what makes that staleness decidable, and it must ride the
    same two writes approval itself rides: set at approve, cleared at un-approve, touched by
    nothing else in the package.
    """
    client, store, comfy = make_client(tmp_path)
    project_id, shot_id, _ = rendered_shot(client, store, comfy, "Snapshot")

    assert approve(client, project_id, shot_id).status_code == 200
    approved = ProjectStore(tmp_path).get(project_id).shots[0]
    assert approved.approved_start == approved.start == 0
    assert approved.approved_duration == approved.duration == 5

    # The reversal clears the snapshot with the approval it described: a snapshot outliving
    # its approval would make the *next* approval's staleness check read a window nobody
    # decided about.
    assert unapprove(client, project_id, shot_id).status_code == 200
    cleared = ProjectStore(tmp_path).get(project_id).shots[0]
    assert cleared.approved_start == 0
    assert cleared.approved_duration == 0

    # Move the window, re-approve: the snapshot is the window at the *moment of approval*,
    # not the one the first approval saw.
    stored = store.get(project_id)
    stored.shots[0].start = 2.5
    stored.shots[0].duration = 3.75
    store.save(stored)
    assert approve(client, project_id, shot_id).status_code == 200
    reapproved = ProjectStore(tmp_path).get(project_id).shots[0]
    assert reapproved.approved_start == 2.5
    assert reapproved.approved_duration == 3.75

    # The one-writer scan, mirroring the `approved_output` scan: exactly one set and one
    # clear of each snapshot field, both in app.py's approve/unapprove pair.
    package = Path("src/music_video_producer")
    writes: dict[str, int] = {}
    for source in package.rglob("*.py"):
        text = source.read_text(encoding="utf-8")
        count = len(re.findall(r"\.approved_(?:start|duration)\s*=[^=]", text))
        if count:
            writes[source.name] = count
    assert writes == {"app.py": 4}, writes


def test_expansion_refuses_a_route_approved_shot(tmp_path: Path):
    """The downstream refusal, wired end to end rather than hand-built.

    Every existing expansion-refusal test constructs its approval by writing fields onto a Shot,
    which proves the guard reads the fields and nothing about whether the approve route writes
    the ones the guard reads. This one approves through the route and watches the same refusal
    fire on what the route wrote.
    """
    client, store, comfy = make_client(tmp_path, ExpandingDirector())
    project_id, shot_id, _ = rendered_shot(client, store, comfy, "Approved, then expanded")
    stored = store.get(project_id)
    stored.shots.append(Shot(id="shot_second", start=10, duration=6, prompt="", status="draft"))
    store.save(stored)
    assert approve(client, project_id, shot_id).status_code == 200

    response = client.post(f"/api/projects/{project_id}/director/expand")

    assert response.status_code == 200
    saved = ProjectStore(tmp_path).get(project_id)
    assert saved.shots[0].prompt == "A singer turns toward camera"
    assert saved.shots[0].approved_output == saved.shots[0].latest_output
    # The draft Shot beside it still moves, so the approval is per Shot and not a plan veto.
    assert saved.shots[1].prompt == "Prompt for shot_second at index 1"
    notice = saved.messages[-1].content
    assert "a render or a take already depends on the prompt" in notice
    assert shot_id in notice.split("already depends on the prompt")[1]
    assert len(comfy.prompts) == 1


def test_sage_attention_setting_patches_every_attention_node_at_submission(tmp_path: Path):
    """MVP_SAGE_ATTENTION's one choke point: configured, every submitted H3 payload's
    PathchSageAttentionKJ carries the configured kernel; unset (the default), the payload
    is byte-identical to the adapters' evidence value (`disabled`) — every other test in
    this file runs unset, so the whole suite is the byte-identity half."""
    settings = Settings(
        data_root=tmp_path, comfy_root=tmp_path / "comfy", sage_attention="auto"
    )
    store = ProjectStore(tmp_path)
    comfy = FakeComfy()
    app = create_app(settings=settings, store=store, comfy=comfy, director=FakeDirector())
    client = TestClient(app)
    project = store.create(Project(name="Sage"))
    media = store.media_dir(project.id)
    (media / "lead.png").write_bytes(b"png")
    project.assets = [Asset(id="asset_sage", name="Lead", kind="character", path="media/lead.png")]
    # A references shot: the text-only Director graph carries no attention node,
    # so the patch is asserted where the node exists (reference/keyframe/edit graphs).
    project.shots = [
        Shot(id="shot_sage", start=0, duration=4, prompt="p", asset_ids=["asset_sage"], status="ready")
    ]
    store.save(project)

    assert submit_h3(client, project.id, "shot_sage").status_code == 202
    attention = [
        node for node in comfy.prompts[-1].values()
        if node["class_type"] == "PathchSageAttentionKJ"
    ]
    assert attention and all(
        node["inputs"]["sage_attention"] == "auto" for node in attention
    )


def test_sections_route_sorts_refuses_overlap_and_reaches_the_expansion(tmp_path: Path):
    """The Director's section marks end to end: saved sorted, overlaps refused by name,
    and the expansion payload reads the section (label, shared prompt, lyric block) for a
    shot inside one — the fix for the wrong-verse lipsync the first batch rendered."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Sections"))
    project.song = Song(
        title="S", source="imported", path="m.mp3", duration=60.0,
        lyrics="[Verse]\nverse words here\n\n[Chorus]\nchorus hook words\n",
    )
    project.shots = [Shot(id="shot_c", start=27, duration=6, prompt="Glamour angle")]
    store.save(project)

    overlapping = client.put(f"/api/projects/{project.id}/sections", json={"sections": [
        {"label": "Verse", "start": 0, "duration": 30},
        {"label": "Chorus", "start": 24, "duration": 20},
    ]})
    assert overlapping.status_code == 422
    assert "may not overlap" in overlapping.json()["detail"]

    saved = client.put(f"/api/projects/{project.id}/sections", json={"sections": [
        {"label": "Chorus", "start": 24, "duration": 20, "prompt": "on the canopy bed"},
        {"label": "Verse", "start": 0, "duration": 24, "prompt": "at the mic"},
    ]})
    assert saved.status_code == 200
    labels = [s["label"] for s in saved.json()["sections"]]
    assert labels == ["Verse", "Chorus"]  # sorted by start on write

    from music_video_producer.timeline import shot_expansion_input

    stored = store.get(project.id)
    section = shot_expansion_input(stored, stored.shots[0])["shot"]["section"]
    assert section["label"] == "Chorus"
    assert section["prompt"] == "on the canopy bed"
    # Lyric text never rides the expansion payload (2026-08-19, twice-measured).
    assert "lyrics" not in section


def test_the_generic_project_put_holds_sections_to_the_same_rule_as_the_sections_route(
    tmp_path: Path,
):
    """**Finding 7, and the ninth time this route has been the hole for a guarded field.**

    `PUT /sections` sorts and refuses overlaps; the generic `PUT /api/projects/{id}` — the normal
    save path for every edit the browser makes — validated the field not at all. Everything
    downstream reads the layer as sorted and disjoint, and an unsorted one used to make
    `timeline.layout_spans` emit *duplicate* spans: the song tiled twice, `SNAP_NESTED` raised,
    and populate answered an unhandled 500 after a ~110 s model call.

    Unlike the `_adopt_*` helpers beside it this is validation and not adoption — sections are
    the Director's own hand-dragged structure and this is where the browser saves them, so taking
    the stored value back would make the boxes undraggable. Both writers now go through
    `app.legal_sections`, so the rule cannot drift between them.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Sections via the generic PUT"))
    project.song = Song(title="S", source="imported", path="m.mp3", duration=60.0)
    stored = store.save(project)

    def save(sections):
        body = stored.model_dump(mode="json")
        body["sections"] = sections
        return client.put(f"/api/projects/{stored.id}", json=body)

    overlapping = save([
        {"label": "Verse", "start": 0, "duration": 30},
        {"label": "Chorus", "start": 24, "duration": 20},
    ])
    assert overlapping.status_code == 422
    assert "may not overlap" in overlapping.json()["detail"]
    # A refusal must not have written anything, or it is not a refusal.
    assert store.get(stored.id).sections == []

    unsorted_save = save([
        {"label": "Chorus", "start": 30, "duration": 30},
        {"label": "Verse", "start": 0, "duration": 30},
    ])
    assert unsorted_save.status_code == 200
    assert [section["label"] for section in unsorted_save.json()["sections"]] == [
        "Verse", "Chorus"
    ]
    assert [section.label for section in store.get(stored.id).sections] == ["Verse", "Chorus"]

    # And the two writers give the same answer to the same body, which is the point of sharing
    # one implementation rather than writing the rule twice.
    from music_video_producer.app import SECTIONS_OVERLAP_REFUSAL

    through_the_narrow_route = client.put(
        f"/api/projects/{stored.id}/sections",
        json={"sections": [
            {"label": "Verse", "start": 0, "duration": 30},
            {"label": "Chorus", "start": 24, "duration": 20},
        ]},
    )
    assert through_the_narrow_route.status_code == 422
    assert through_the_narrow_route.json()["detail"] == overlapping.json()["detail"]
    assert through_the_narrow_route.json()["detail"] == SECTIONS_OVERLAP_REFUSAL.format(
        first="Verse", end=30.0, second="Chorus", start=24.0
    )


def test_a_save_that_does_not_touch_the_sections_is_never_refused_over_them(tmp_path: Path):
    """The gate is on *changing* the layer, which is the Song guard's shape on this same route.

    This is the normal save path for every edit in the interface. A manifest written before the
    rule existed can hold an overlapping layer — the generic `PUT` was the only door wide enough
    to have written one — and refusing an ordinary save over it would make that project
    unsaveable *and* unfixable, because `PUT /sections` refuses the same body. So a save that
    round-trips the stored sections passes untouched, and only a save that introduces or edits an
    overlap is held to the rule.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Legacy overlap"))
    project.song = Song(title="S", source="imported", path="m.mp3", duration=60.0)
    # Written past the routes, which is the only way this state exists at all.
    project.sections = [
        SongSection(id="section_0", label="Verse", start=0.0, duration=30.0),
        SongSection(id="section_1", label="Chorus", start=24.0, duration=20.0),
    ]
    stored = store.save(project)

    body = stored.model_dump(mode="json")
    body["name"] = "Renamed while the overlap sits there"
    ordinary = client.put(f"/api/projects/{stored.id}", json=body)
    assert ordinary.status_code == 200, ordinary.text
    assert ordinary.json()["name"] == "Renamed while the overlap sits there"
    # The layer is untouched — not repaired behind the Director's back, and not refused.
    assert [(s["label"], s["start"]) for s in ordinary.json()["sections"]] == [
        ("Verse", 0.0), ("Chorus", 24.0)
    ]

    # And editing the layer to a *different* overlap is still refused.
    body = store.get(stored.id).model_dump(mode="json")
    body["sections"][1]["start"] = 20.0
    assert client.put(f"/api/projects/{stored.id}", json=body).status_code == 422


# --------------------------------------------------------------------------------------------
# Fill section looks. The Director's report (2026-08-20): a Section clicked in the timeline
# had an empty shared prompt, so nothing of the Treatment reached the shots inside it. The
# sections came from the Whisper alignment pass, which is exactly the branch populate does
# *not* ask the model for structure on, and no other path writes `SongSection.prompt`.
#
# Every test below runs against a recording double. **No live model validated the prompt
# wording**: the GPU and the model host were contended and the task forbade a live call.
# --------------------------------------------------------------------------------------------

#: The live project's treatment, verbatim (project_59f14d19ff10, read-only). It is here rather
#: than paraphrased because the whole label-matching question is a property of *this* prose:
#: the headings group sections ("Verse 1 & Verse 2", "Chorus 1 & Chorus 2") while the timeline
#: numbers them the lyric sheet's way ("Verse", "Verse 2"), and a test written against tidy
#: one-heading-per-section prose would never meet the case that matters.
DIRECTOR_TREATMENT = (
    "The video follows a dualistic performance structure that oscillates between raw rock "
    "energy and dark, erotic glamour.\n\n"
    "**Intro:** We begin with atmospheric establishing shots of the empty, moonlit "
    "warehouse. The mood is lonely, industrial, and heavy with anticipation.\n\n"
    "**Verse 1 & Verse 2:** The energy is driven by high-intensity performance at a vintage "
    "chrome microphone. The camera work is aggressive - handheld, shaky, and low-angle - "
    "capturing the character's raw power and 'animalistic' movement through the shadows of "
    "the warehouse aisles.\n\n"
    "**Chorus 1 & Chorus 2:** A dramatic shift in tone. The setting moves to the black "
    "draped canopy bed. The camera transitions from handheld grit to slow, sweeping, "
    "cinematic glides.\n\n"
    "**Outro:** The energy dissipates into a haunting, cinematic stillness. We return to "
    "wide shots of the empty bed and the abandoned microphone."
)

#: The live project's style bible, trimmed to the paragraphs a look is written out of.
DIRECTOR_STYLE_BIBLE = (
    "**Color Palette:** Deep midnight blues, charcoal blacks, oxblood red, cool white "
    "moonlight.\n**Lighting:** Chiaroscuro; a single volumetric moonbeam through high "
    "warehouse windows.\n**Lens & Grain:** 35mm film aesthetic with heavy cinematic grain."
)

#: The live project's seven sections: label, start, duration — the Whisper alignment's own
#: output, ids substituted for readable ones. Note the repeats and note that the *order* of
#: the labels is not the order of the treatment's headings: Verse, Chorus, Verse 2, Chorus 2
#: against Intro, Verses, Choruses, Outro. Anything matching by position gets this wrong.
DIRECTOR_SECTIONS = [
    ("section_intro", "Intro", 0.0, 11.0),
    ("section_v1", "Verse", 11.0, 21.54),
    ("section_c1", "Chorus", 32.54, 23.82),
    ("section_v2", "Verse 2", 56.36, 20.84),
    ("section_c2", "Chorus 2", 77.2, 26.0),
    ("section_bridge", "Bridge", 103.2, 20.9),
    ("section_outro", "Outro", 124.1, 30.54),
]


class SectionLookingDirector(FakeDirector):
    """A director double whose section looks are chosen by the test, request recorded.

    Recording rather than fixed, because the *input* is half the contract: this pass is shown
    the treatment, the style bible and the section boxes **with their ids**, and a double that
    swallowed `looks_input` would let the ids stop being sent without a test noticing — and
    the ids are the entire matching rule.

    `looks` is a list of `(section_id, label, prompt)` triples, or a callable handed the input
    so a test can answer the way the treatment actually reads. Triples rather than a dict
    keyed by id so a test can send two entries for one id, or an entry for an id that does not
    exist, which are two of the failure modes the route has to survive.
    """

    def __init__(self, looks=(), message="Read the treatment onto the sections."):
        self.looks = looks
        self.message = message
        self.calls = []

    async def section_looks(self, *, looks_input):
        self.calls.append(looks_input)
        entries = self.looks(looks_input) if callable(self.looks) else list(self.looks)
        return type(
            "SectionLooks",
            (),
            {
                "message": self.message,
                "looks": [
                    type(
                        "SectionLook",
                        (),
                        {"section_id": section_id, "label": label, "prompt": prompt},
                    )()
                    for section_id, label, prompt in entries
                ],
            },
        )()


def sectioned_project(store, director_sections=DIRECTOR_SECTIONS, **fields):
    """A project carrying the live treatment, the live style bible and given sections."""
    project = store.create(Project(name="Looks"))
    project.song = Song(title="S", source="imported", path="m.mp3", duration=155.0)
    project.treatment = fields.pop("treatment", DIRECTOR_TREATMENT)
    project.style_bible = fields.pop("style_bible", DIRECTOR_STYLE_BIBLE)
    project.sections = [
        SongSection(id=section_id, label=label, start=start, duration=duration)
        for section_id, label, start, duration in director_sections
    ]
    for key, value in fields.items():
        setattr(project, key, value)
    return store.save(project)


def fill_looks(client, project_id: str, **body):
    return client.post(f"/api/projects/{project_id}/sections/fill-looks", json=body)


def fill_looks_applying(client, project_id: str, **body):
    """Report, then confirm **with that report as the plan** — the two calls this route takes.

    Every test below that used to say `fill_looks(..., confirm_apply=True)` says this instead,
    and the change is the fix rather than an accommodation of it: a single confirming call used
    to read the treatment a second time at `PLAN_TEMPERATURE` and write whatever that reading
    said, so the look that landed was not the look the report showed. A confirm now has to
    carry the report it is confirming, so a test that applies has to read one first, like a
    person.

    A non-200 report is handed straight back, so the refusal tests still read as one call: the
    refusals they are about happen before any model is asked, which is where they always were.
    The model is asked exactly **once** across the two calls — on the report — and
    `director.calls` is asserted on below.
    """
    report = fill_looks(client, project_id, **body)
    if report.status_code != 200:
        return report
    return fill_looks(client, project_id, confirm_apply=True, plan=report.json(), **body)


def test_fill_section_looks_reports_first_then_writes_and_reaches_the_prompts(tmp_path: Path):
    """The gap closed end to end.

    A report writes nothing and says so on the wire (`project` is null, the manifest is
    unchanged); the confirmed call writes; and the look then arrives everywhere a section
    look is consumed — the whole-plan expansion input, the per-shot expansion input, and the
    submitted H3 text as "Section look: …". Stored is not the claim; reaching the prompts is.
    """
    from music_video_producer.timeline import expansion_input, shot_expansion_input

    director = SectionLookingDirector(
        looks=[
            ("section_intro", "Intro", "The empty moonlit warehouse, wide and lonely."),
            ("section_v1", "Verse", "Handheld and low-angle at the vintage chrome mic."),
        ]
    )
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(
        store,
        [("section_intro", "Intro", 0.0, 11.0), ("section_v1", "Verse", 11.0, 21.54)],
    )
    project.shots = [Shot(id="shot_v", start=12, duration=6, prompt="She grips the mic.")]
    store.save(project)

    report = fill_looks(client, project.id)
    assert report.status_code == 200, report.text
    body = report.json()
    assert body["applied"] is False
    # The absence *is* the statement that nothing was written.
    assert body["project"] is None
    assert body["filled"] == 2 and body["skipped"] == 0
    assert [row["label"] for row in body["sections"]] == ["Intro", "Verse"]
    assert body["sections"][0]["prompt"].startswith("The empty moonlit warehouse")
    assert body["sections"][0]["previous"] == ""
    # Nothing on disk moved on the report path.
    assert [s.prompt for s in store.get(project.id).sections] == ["", ""]

    applied = fill_looks_applying(client, project.id)
    assert applied.status_code == 200, applied.text
    assert applied.json()["applied"] is True
    assert applied.json()["project"] is not None

    # Persistence through a *fresh* store, not the handle that wrote it.
    reread = ProjectStore(tmp_path).get(project.id)
    assert [s.prompt for s in reread.sections] == [
        "The empty moonlit warehouse, wide and lonely.",
        "Handheld and low-angle at the vintage chrome mic.",
    ]

    # It reaches the two expansion payloads — the whole-plan pass and the per-shot pass.
    whole = expansion_input(reread)
    assert whole["shots"][0]["section"]["prompt"].startswith("Handheld and low-angle")
    one = shot_expansion_input(reread, reread.shots[0])
    assert one["shot"]["section"]["prompt"].startswith("Handheld and low-angle")

    # Nothing rendered, armed, queued or approved on any path above.
    assert comfy.prompts == []

    # And it reaches the string H3 is actually submitted, which is the claim that matters.
    media = store.media_dir(project.id)
    (media / "lead.png").write_bytes(b"png")
    written = store.get(project.id)
    written.assets = [
        Asset(id="asset_lead", name="Lead", kind="character", path="media/lead.png")
    ]
    written.shots = [
        Shot(id="shot_v", start=12, duration=6, prompt="She grips the mic.",
             status="ready", asset_ids=["asset_lead"])
    ]
    store.save(written)
    assert submit_h3(client, project.id, "shot_v").status_code == 202
    assert comfy.prompts[-1]["mvp:condition"]["inputs"]["prompt"].endswith(
        "Section look: Handheld and low-angle at the vintage chrome mic."
    )


def test_fill_section_looks_never_replaces_a_written_look_without_consent(tmp_path: Path):
    """Rule one. A section look is editable in the inspector, so a sentence the Director
    typed is exactly the thing a bulk fill must not quietly replace.

    Confirming *this pass* is not the same act as agreeing to lose that sentence, so the two
    flags are separate: `confirm_apply` fills the empty ones and leaves the written one with
    its reason named in the report; `overwrite` is the second, explicit consent. The report
    carries the proposed text and the existing text side by side, so the trade is visible
    before it is taken rather than after.
    """
    from music_video_producer.app import SECTION_LOOK_SKIP_WRITTEN

    director = SectionLookingDirector(
        looks=[
            ("section_intro", "Intro", "A model look for the intro."),
            ("section_v1", "Verse", "A model look for the verse."),
        ]
    )
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(
        store,
        [("section_intro", "Intro", 0.0, 11.0), ("section_v1", "Verse", 11.0, 21.54)],
    )
    project.sections[0].prompt = "MY OWN INTRO LOOK, typed by hand."
    store.save(project)

    report = fill_looks(client, project.id)
    written_row = report.json()["sections"][0]
    assert written_row["filled"] is False
    assert written_row["reason"] == SECTION_LOOK_SKIP_WRITTEN
    assert written_row["previous"] == "MY OWN INTRO LOOK, typed by hand."
    # The proposal rides the report so the Director can see what consent would buy.
    assert written_row["prompt"] == "A model look for the intro."
    assert report.json()["filled"] == 1

    applied = fill_looks_applying(client, project.id)
    assert applied.status_code == 200
    saved = store.get(project.id)
    assert saved.sections[0].prompt == "MY OWN INTRO LOOK, typed by hand."  # untouched
    assert saved.sections[1].prompt == "A model look for the verse."

    # The consent path: both flags, and only then does the hand-written sentence go.
    overwritten = fill_looks_applying(client, project.id, overwrite=True)
    assert overwritten.status_code == 200
    assert overwritten.json()["filled"] == 2
    assert store.get(project.id).sections[0].prompt == "A model look for the intro."
    assert comfy.prompts == []


def test_fill_section_looks_is_a_no_op_when_every_section_already_has_one(tmp_path: Path):
    """Every look written and no consent to replace them: the answer is already known, so
    the 300 s local-model call is not spent to arrive at it. A report, not a refusal —
    nothing is wrong — and the sentence names the step that would overrule it."""
    from music_video_producer.app import SECTION_LOOK_SKIP_ALL_WRITTEN, SECTION_LOOKS_ALL_WRITTEN

    director = SectionLookingDirector(looks=[("section_intro", "Intro", "Replacement.")])
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(store, [("section_intro", "Intro", 0.0, 11.0)])
    project.sections[0].prompt = "Already written."
    store.save(project)

    response = fill_looks(client, project.id)
    assert response.status_code == 200
    assert response.json()["filled"] == 0
    assert response.json()["applied"] is False
    assert response.json()["message"] == SECTION_LOOKS_ALL_WRITTEN
    # Every row says why, and says it in this report's own words rather than the ordinary
    # written-skip's: there is no proposed look on these rows to send a consent about.
    assert [row["reason"] for row in response.json()["sections"]] == [
        SECTION_LOOK_SKIP_ALL_WRITTEN
    ]
    assert [row["prompt"] for row in response.json()["sections"]] == [""]
    assert director.calls == []  # the model was never asked
    assert store.get(project.id).sections[0].prompt == "Already written."
    assert comfy.prompts == []


def test_the_all_written_report_is_refused_as_a_plan_rather_than_writing_nothing(
    tmp_path: Path,
):
    """Finding 5: the report that tells you what to do next is not itself the thing to send.

    The short-circuit above returns *ahead of* the model call, so every row carries an empty
    `prompt`. Confirming it — which is exactly what the old message's "send overwrite=true to
    replace what is there" described — walked every plan check, `continue`d past every row for
    want of a prompt, and answered 200 with `applied: false` and an untouched project: the route
    answering its own documented sequence with silence.

    Both halves are pinned here. The sentence now names the step that works, and the step that
    does not is refused by name whether or not anybody reads the sentence.
    """
    from music_video_producer.app import SECTION_LOOKS_ALL_WRITTEN, SECTION_LOOKS_UNREAD_PLAN

    director = SectionLookingDirector(looks=[("section_intro", "Intro", "Replacement.")])
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(store, [("section_intro", "Intro", 0.0, 11.0)])
    project.sections[0].prompt = "Already written."
    store.save(project)

    report = fill_looks(client, project.id).json()
    # The message names re-reporting, and does not tell a caller to confirm this report.
    assert report["message"] == SECTION_LOOKS_ALL_WRITTEN
    assert "run this again with overwrite=true" in SECTION_LOOKS_ALL_WRITTEN
    assert "send overwrite=true" not in SECTION_LOOKS_ALL_WRITTEN

    for body in (
        {"confirm_apply": True, "overwrite": True, "plan": report},
        {"confirm_apply": True, "plan": report},
    ):
        refused = fill_looks(client, project.id, **body)
        assert refused.status_code == 422, body
        assert refused.json()["detail"] == SECTION_LOOKS_UNREAD_PLAN, body

    # Nothing written, no model asked, no GPU touched — on either attempt.
    assert store.get(project.id).sections[0].prompt == "Already written."
    assert director.calls == []
    assert comfy.prompts == []

    # And the step the sentence names does work, end to end: report again with the consent, and
    # that report is a plan the confirm writes.
    second = fill_looks(client, project.id, overwrite=True)
    assert second.status_code == 200
    assert second.json()["filled"] == 1
    applied = fill_looks(
        client, project.id, confirm_apply=True, overwrite=True, plan=second.json()
    )
    assert applied.status_code == 200
    assert applied.json()["applied"] is True
    assert store.get(project.id).sections[0].prompt == "Replacement."
    assert len(director.calls) == 1  # the model was asked once, on the report
    assert comfy.prompts == []


def test_fill_section_looks_matches_the_directors_seven_by_id_and_label(tmp_path: Path):
    """Rule two, against the live project's real seven.

    The treatment groups sections ("Verse 1 & Verse 2", "Chorus 1 & Chorus 2") while the
    timeline numbers them the lyric sheet's way ("Verse", "Verse 2"), and the two orders do
    not agree — the treatment reads Intro, Verses, Choruses, Outro while the timeline runs
    Intro, Verse, Chorus, Verse 2, Chorus 2, Bridge, Outro. So the match is by the id each
    section was handed, corroborated by its own label, never by position: getting Chorus 2's
    canopy bed onto the Bridge would be worse than leaving the Bridge empty.

    A grouped heading is not an ambiguity: both verses take the verse look, and the two
    sections carrying the same sentence is the right answer. The Bridge is the label this
    treatment never mentions, and it stays empty with the reason said out loud.
    """
    from music_video_producer.app import SECTION_LOOK_SKIP_UNDESCRIBED

    verse_look = "Handheld, low-angle, aggressive at the vintage chrome microphone."
    chorus_look = "Slow cinematic glides across the black draped canopy bed."

    def read_the_treatment(looks_input):
        """What the treatment says for each label, keyed off the input's own ids."""
        by_label = {
            "intro": "The empty moonlit warehouse; lonely, industrial, anticipatory.",
            "verse": verse_look,
            "verse 2": verse_look,
            "chorus": chorus_look,
            "chorus 2": chorus_look,
            "bridge": "",  # this treatment has no Bridge paragraph
            "outro": "Wide, still and haunting on the empty bed and abandoned microphone.",
        }
        return [
            (entry["section_id"], entry["label"], by_label[entry["label"].lower()])
            for entry in looks_input["sections"]
        ]

    director = SectionLookingDirector(looks=read_the_treatment)
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(store)

    response = fill_looks_applying(client, project.id)
    assert response.status_code == 200, response.text

    # The input the model was shown: the two documents and the boxes with their ids, in song
    # order, and nothing else — no shots, no assets, no lyrics to leak a name out of.
    sent = director.calls[0]
    assert set(sent) == {"treatment", "style_bible", "sections"}
    # Both documents go whole — the treatment is the source the looks are read out of and
    # the style bible is the language they are written in, and an input that dropped either
    # would still produce looks, just invented ones.
    assert sent["treatment"] == DIRECTOR_TREATMENT
    assert sent["style_bible"] == DIRECTOR_STYLE_BIBLE
    assert [entry["label"] for entry in sent["sections"]] == [
        "Intro", "Verse", "Chorus", "Verse 2", "Chorus 2", "Bridge", "Outro",
    ]
    assert [entry["section_id"] for entry in sent["sections"]][:3] == [
        "section_intro", "section_v1", "section_c1",
    ]

    saved = {section.id: section.prompt for section in store.get(project.id).sections}
    # Both verses take the verse look and both choruses the chorus look — and, decisively,
    # the second verse did NOT take the chorus paragraph that sits third in the treatment.
    assert saved["section_v1"] == verse_look
    assert saved["section_v2"] == verse_look
    assert saved["section_c1"] == chorus_look
    assert saved["section_c2"] == chorus_look
    assert saved["section_intro"].startswith("The empty moonlit warehouse")
    assert saved["section_outro"].startswith("Wide, still and haunting")
    # The label this treatment never mentions is left empty, with the reason said out loud.
    assert saved["section_bridge"] == ""
    bridge = next(r for r in response.json()["sections"] if r["label"] == "Bridge")
    assert bridge["filled"] is False and bridge["reason"] == SECTION_LOOK_SKIP_UNDESCRIBED
    assert response.json()["filled"] == 6 and response.json()["skipped"] == 1
    assert comfy.prompts == []


def test_fill_section_looks_refuses_a_look_whose_id_and_label_disagree(tmp_path: Path):
    """The checksum, and the reason the entry carries a label at all.

    The id is the address, but a model copying ids down a numbered list can copy a
    right-looking one off the wrong row — and with "Verse"/"Verse 2" and "Chorus"/"Chorus 2"
    in play, one row off is Chorus 2's setting landing on the Bridge. So a pair that
    disagrees writes nothing and says so; an id no section has writes nothing and is
    counted; a section the model never answered for writes nothing. Casing and stray space
    are not a disagreement — "chorus 2 " is the Director's "Chorus 2".
    """
    from music_video_producer.app import SECTION_LOOK_SKIP_UNANSWERED

    director = SectionLookingDirector(
        looks=[
            # Right id, wrong name: the model was one row off. Refused.
            ("section_bridge", "Chorus 2", "Slow glides across the canopy bed."),
            # Same label, different case and spacing: the same box, accepted.
            ("section_c2", " chorus 2 ", "The canopy bed, sweeping and glacial."),
            # An id this project does not have: dropped, and counted in the message.
            ("section_ghost", "Verse", "A look for a section that is not here."),
            # Two answers for one id: the first wins, so the written text cannot depend on
            # emission order.
            ("section_intro", "Intro", "The first answer."),
            ("section_intro", "Intro", "The second answer."),
        ]
    )
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(store)

    response = fill_looks_applying(client, project.id)
    assert response.status_code == 200, response.text
    rows = {row["label"]: row for row in response.json()["sections"]}

    assert rows["Bridge"]["filled"] is False
    assert "called it 'Chorus 2'" in rows["Bridge"]["reason"]
    assert rows["Chorus 2"]["filled"] is True
    assert rows["Verse"]["reason"] == SECTION_LOOK_SKIP_UNANSWERED

    saved = {section.id: section.prompt for section in store.get(project.id).sections}
    assert saved["section_bridge"] == ""  # the mislabelled look never landed
    assert saved["section_c2"] == "The canopy bed, sweeping and glacial."
    assert saved["section_intro"] == "The first answer."
    assert saved["section_v1"] == "" and saved["section_v2"] == ""
    assert "1 answer(s) addressed no section" in response.json()["message"]
    assert comfy.prompts == []


def test_fill_section_looks_refuses_absent_source_material_without_a_model_call(tmp_path: Path):
    """Rule three, and the codebase's absent-analysis convention applied to prose.

    An empty treatment is *unwritten*, not "no look wanted" — the same distinction
    `shot_vocal_overlap` draws between a measured silence and an unmeasured song. There is
    nothing to read a section's look out of, so the honest answer is a refusal naming the
    document to write, not a fabricated sentence and not a 200 saying "0 filled" as though
    the model had been asked and had nothing to say. Refused before the call, so an
    unwritten project costs no model time at all.
    """
    from music_video_producer.app import (
        SECTION_LOOKS_NO_SECTIONS,
        SECTION_LOOKS_NO_STYLE_BIBLE,
        SECTION_LOOKS_NO_TREATMENT,
    )

    director = SectionLookingDirector(looks=[("section_intro", "Intro", "Invented.")])
    client, store, comfy = make_client(tmp_path, director=director)

    no_sections = sectioned_project(store, [])
    refused = fill_looks_applying(client, no_sections.id)
    assert refused.status_code == 422
    assert refused.json()["detail"] == SECTION_LOOKS_NO_SECTIONS

    blank = sectioned_project(
        store, [("section_intro", "Intro", 0.0, 11.0)], treatment="   \n "
    )
    refused = fill_looks_applying(client, blank.id)
    assert refused.status_code == 422
    assert refused.json()["detail"] == SECTION_LOOKS_NO_TREATMENT

    bibleless = sectioned_project(
        store, [("section_intro", "Intro", 0.0, 11.0)], style_bible=""
    )
    refused = fill_looks_applying(client, bibleless.id)
    assert refused.status_code == 422
    assert refused.json()["detail"] == SECTION_LOOKS_NO_STYLE_BIBLE

    # Nothing asked, nothing written, nothing queued on any of the three.
    assert director.calls == []
    assert store.get(blank.id).sections[0].prompt == ""
    assert comfy.prompts == []


def test_fill_section_looks_translates_the_model_being_down(tmp_path: Path):
    """The two director failures, at this route's own boundary: unconfigured is a 503 (the
    host is not there), an unusable reply is a 502 (it is, and it answered badly). Neither
    writes, which is the half worth pinning — a fill that half-landed on a 502 would leave
    the section layer in a state nobody chose."""

    class DownDirector(FakeDirector):
        def __init__(self, error):
            self.error = error

        async def section_looks(self, *, looks_input):
            raise self.error

    from music_video_producer.director import DirectorError, DirectorUnavailable

    for error, code in (
        (DirectorUnavailable("LLM director is not configured."), 503),
        (DirectorError("LLM director returned an invalid response: nope"), 502),
    ):
        client, store, comfy = make_client(tmp_path / f"root{code}", director=DownDirector(error))
        project = sectioned_project(store, [("section_intro", "Intro", 0.0, 11.0)])
        response = fill_looks_applying(client, project.id)
        assert response.status_code == code, response.text
        assert store.get(project.id).sections[0].prompt == ""
        assert comfy.prompts == []


def test_fill_section_looks_writes_the_look_that_was_read_and_asks_no_model_to_write_it(
    tmp_path: Path,
):
    """The report-then-confirm finding, closed on this route (2026-08-21).

    The route asked the model *before* it looked at `confirm_apply`, so the confirming call
    read the treatment a second time at `PLAN_TEMPERATURE = 0.7` and wrote whatever that
    reading said — the look that landed was not the look the confirm dialog showed. The double
    here answers differently on every call, which is what makes the difference visible: a
    section either holds "take 1", the words that were read, or "take 2", which is the bug.
    """
    takes = {"n": 0}

    def drifting(looks_input):
        takes["n"] += 1
        return [
            ("section_intro", "Intro", f"The empty moonlit warehouse, take {takes['n']}."),
            ("section_v1", "Verse", f"Handheld at the chrome mic, take {takes['n']}."),
        ]

    director = SectionLookingDirector(looks=drifting)
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(
        store,
        [("section_intro", "Intro", 0.0, 11.0), ("section_v1", "Verse", 11.0, 21.54)],
    )

    report = fill_looks(client, project.id)
    assert report.status_code == 200, report.text
    plan = report.json()
    assert len(director.calls) == 1
    assert len(plan["plan_id"]) == 64 and plan["updated_at"]
    assert [row["prompt"] for row in plan["sections"]] == [
        "The empty moonlit warehouse, take 1.",
        "Handheld at the chrome mic, take 1.",
    ]

    applied = fill_looks(client, project.id, confirm_apply=True, plan=plan)
    assert applied.status_code == 200, applied.text
    body = applied.json()
    # The cost half: the confirm asked no model. This fails on the pre-fix route.
    assert len(director.calls) == 1
    assert body["applied"] is True and body["project"] is not None
    assert {key: value for key, value in body.items() if key not in {"applied", "project"}} == {
        key: value for key, value in plan.items() if key not in {"applied", "project"}
    }
    # Byte-equality between what was read and what landed, through a fresh store.
    reread = ProjectStore(tmp_path).get(project.id)
    assert [section.prompt for section in reread.sections] == [
        row["prompt"] for row in plan["sections"]
    ]
    assert not any("take 2" in section.prompt for section in reread.sections)
    assert comfy.prompts == []


def test_fill_section_looks_refuses_a_confirm_that_cannot_prove_its_plan(tmp_path: Path):
    """Absent, tampered, forged and stale — and none of them reads the treatment again.

    Regenerating on a confirm it cannot match is exactly the behaviour being removed, so the
    fallback is a refusal. Nothing is written on any of the four paths.
    """
    import json as json_module

    from music_video_producer.app import (
        PROJECT_CHANGED_REFUSAL,
        SECTION_LOOKS_NO_PLAN,
        SECTION_LOOKS_PLAN_MISMATCH,
    )

    director = SectionLookingDirector(
        looks=[("section_intro", "Intro", "The empty moonlit warehouse, wide and lonely.")]
    )
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(store, [("section_intro", "Intro", 0.0, 11.0)])

    plan = fill_looks(client, project.id).json()
    assert len(director.calls) == 1

    absent = fill_looks(client, project.id, confirm_apply=True)
    assert absent.status_code == 422
    assert absent.json()["detail"] == SECTION_LOOKS_NO_PLAN

    tampered = json_module.loads(json_module.dumps(plan))
    tampered["sections"][0]["prompt"] = "A look that was never in any report."
    swapped = fill_looks(client, project.id, confirm_apply=True, plan=tampered)
    assert swapped.status_code == 422
    assert swapped.json()["detail"] == SECTION_LOOKS_PLAN_MISMATCH

    forged = json_module.loads(json_module.dumps(plan))
    forged["plan_id"] = "0" * 64
    minted = fill_looks(client, project.id, confirm_apply=True, plan=forged)
    assert minted.status_code == 422
    assert minted.json()["detail"] == SECTION_LOOKS_PLAN_MISMATCH

    moved = store.get(project.id)
    moved.name = "Renamed while the report sat open"
    store.save(moved)
    stale = fill_looks(client, project.id, confirm_apply=True, plan=plan)
    assert stale.status_code == 409
    assert stale.json()["detail"] == PROJECT_CHANGED_REFUSAL

    assert [section.prompt for section in ProjectStore(tmp_path).get(project.id).sections] == [""]
    assert len(director.calls) == 1
    assert comfy.prompts == []


def test_fill_section_looks_refuses_a_plan_whose_section_moved_under_it(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
):
    """The confirm's row check, forced to fire.

    Unreachable while the revision check holds — a section cannot be renamed or written without
    the manifest being saved — so, `CLEAN_PROMPTS_WINDOWS_MOVED`'s rule, it is checked rather
    than argued and tested by standing in a digest that accepts whatever it is handed. The id
    and the label must still describe the same box, and the look being replaced must still be
    the one the report showed as `previous`.
    """
    from music_video_producer import app as app_module
    from music_video_producer.app import SECTION_LOOKS_PLAN_MISMATCH

    director = SectionLookingDirector(
        looks=[("section_intro", "Intro", "The empty moonlit warehouse, wide and lonely.")]
    )
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(store, [("section_intro", "Intro", 0.0, 11.0)])
    monkeypatch.setattr(
        app_module, "plan_fingerprint", lambda project, plan: plan.plan_id or "minted"
    )
    plan = fill_looks(client, project.id).json()

    mislabelled = {**plan, "sections": [{**plan["sections"][0], "label": "Chorus 2"}]}
    response = fill_looks(client, project.id, confirm_apply=True, plan=mislabelled)
    assert response.status_code == 422
    assert response.json()["detail"] == SECTION_LOOKS_PLAN_MISMATCH

    moved = {**plan, "sections": [{**plan["sections"][0], "previous": "Not what it held."}]}
    response = fill_looks(client, project.id, confirm_apply=True, plan=moved)
    assert response.status_code == 422
    assert response.json()["detail"] == SECTION_LOOKS_PLAN_MISMATCH

    assert store.get(project.id).sections[0].prompt == ""
    assert comfy.prompts == []


def test_fill_section_looks_takes_the_overwrite_consent_without_reading_again(
    tmp_path: Path,
):
    """The second consent is answered against the report, not by asking the model twice.

    The browser reports first, asks "also replace the looks you wrote yourself?", and confirms
    with the answer — so the report has to carry the proposed look for a written section (it
    does, on the row) and the confirm has to be able to act on it (it does, and `overwrite`
    is deliberately outside the plan's digest for exactly this). One model call, both halves.
    """
    from music_video_producer.app import SECTION_LOOK_SKIP_WRITTEN

    director = SectionLookingDirector(
        looks=[
            ("section_intro", "Intro", "A model look for the intro."),
            ("section_v1", "Verse", "A model look for the verse."),
        ]
    )
    client, store, comfy = make_client(tmp_path, director=director)
    project = sectioned_project(
        store,
        [("section_intro", "Intro", 0.0, 11.0), ("section_v1", "Verse", 11.0, 21.54)],
    )
    project.sections[0].prompt = "MY OWN INTRO LOOK, typed by hand."
    store.save(project)

    plan = fill_looks(client, project.id).json()
    assert plan["sections"][0]["reason"] == SECTION_LOOK_SKIP_WRITTEN
    assert plan["sections"][0]["prompt"] == "A model look for the intro."
    assert plan["filled"] == 1

    applied = fill_looks(
        client, project.id, confirm_apply=True, overwrite=True, plan=plan
    ).json()
    assert len(director.calls) == 1
    assert applied["filled"] == 2
    assert applied["sections"][0]["filled"] is True
    assert applied["sections"][0]["reason"] == ""
    assert applied["message"] == "2 filled, 0 left alone"
    reread = ProjectStore(tmp_path).get(project.id)
    assert [section.prompt for section in reread.sections] == [
        "A model look for the intro.",
        "A model look for the verse.",
    ]
    assert comfy.prompts == []


def test_populate_adopts_the_models_sections_when_none_are_marked(tmp_path: Path):
    """Populate fills the section layer too (the Director's design): the model's
    structure proposal is repaired and adopted when the Director has marked nothing,
    the shots then tile inside those sections, and marked sections are never replaced."""
    director = PlanningDirector(
        # Twelve, because a 60 s song's enforced count is 12; the section layer is what
        # this test is about and a short plan would never reach it.
        shots=[
            (0, 6, "Open wide."),
            *[(index * 5, 5, f"Beat {index}.") for index in range(1, 11)],
            (55, 5, "Chorus glamour."),
        ],
        sections=[
            ("Intro", 0, 8, ""),
            ("Verse", 8, 22, "at the standing mic"),
            ("Chorus", 30, 30, "on the canopy bed"),
        ],
    )
    client, store, _comfy = make_client(tmp_path, director=director)
    project = store.create(Project(name="Adopt"))
    project.song = Song(title="S", source="imported", path="m.mp3", duration=60.0)
    store.save(project)

    response = populate(client, project.id)
    assert response.status_code == 200, response.text
    saved = store.get(project.id)
    assert [section.label for section in saved.sections] == ["Intro", "Verse", "Chorus"]
    assert saved.sections[2].prompt == "on the canopy bed"
    # Shots tile inside sections: no shot straddles a section boundary.
    edges = {section.start for section in saved.sections} | {section.end for section in saved.sections}
    for shot in saved.shots:
        for edge in edges:
            assert not (shot.start < edge - 1e-6 < shot.start + shot.duration - 1e-6), (
                f"shot at {shot.start} straddles section edge {edge}"
            )

    # Marked sections survive a re-populate untouched.
    marked = store.get(project.id)
    marked.sections[0].prompt = "hand-edited"
    store.save(marked)
    assert populate(client, project.id).status_code == 200
    assert store.get(project.id).sections[0].prompt == "hand-edited"


def test_the_dp_pass_rides_the_expand_route_with_its_own_persona_and_input(tmp_path: Path):
    """focus=photography selects the DP persona over the identical machinery: the input is
    the camera-trimmed dp_input (sections inline, no citations, no lyrics), the system
    prompt is the DP job description, and the revised intents land through the same
    id-keyed guards — locked shots refused, story text replaced only where answered."""

    class RecordingDirector:
        def __init__(self):
            self.calls = []

        async def expand(self, *, expansion_input, system_prompt=None):
            self.calls.append({"input": expansion_input, "system": system_prompt})
            revised = type("ExpandedShot", (), {
                "shot_id": expansion_input["shots"][0]["shot_id"],
                "prompt": "Medium close-up, eye level, static shot: she holds the mic.",
            })()
            return type("ShotExpansion", (), {"message": "Composed.", "shots": [revised]})()

    from music_video_producer.dp_prompt import DP_SYSTEM_PROMPT

    director = RecordingDirector()
    client, store, _comfy = make_client(tmp_path, director=director)
    project = store.create(Project(name="DP"))
    project.song = Song(title="S", source="imported", path="m.mp3", duration=30.0)
    project.sections = [SongSection(label="Verse", start=0, duration=30, prompt="kinetic")]
    project.shots = [
        Shot(id="shot_a", start=0, duration=6, prompt="She walks to the mic."),
        Shot(id="shot_b", start=6, duration=6, prompt="Locked framing.", locked=True),
    ]
    store.save(project)

    response = client.post(f"/api/projects/{project.id}/director/expand?focus=photography")
    assert response.status_code == 200, response.text

    call = director.calls[0]
    assert call["system"] == DP_SYSTEM_PROMPT
    # The camera-trimmed input: sections inline on shots and as the plan's map; no
    # citations, no lyric sheet — the DP does not re-cast and does not need the words.
    assert call["input"]["shots"][0]["section"] == {"label": "Verse", "prompt": "kinetic"}
    assert call["input"]["sections"][0]["label"] == "Verse"
    assert "song" not in call["input"]
    assert "references" not in call["input"]["shots"][0]

    saved = store.get(project.id)
    assert saved.shots[0].prompt.startswith("Medium close-up")
    assert saved.shots[1].prompt == "Locked framing."  # the lock held

    # The story pass is untouched: no focus means the original persona and input.
    story = client.post(f"/api/projects/{project.id}/director/expand")
    assert story.status_code == 200
    assert director.calls[-1]["system"] is None
    assert "song" in director.calls[-1]["input"]


# --------------------------------------------------------------------------------------------
# Reference-slot bounds at the route. H3's media slots are anonymous, so `<Picture 3>` on a
# two-picture shot is not an error the sampler can report: it renders, plausibly, conditioned
# on a slot nothing fills. The refusal has to happen before the GPU pass or not at all.
# --------------------------------------------------------------------------------------------


def bounded_shot(client, store, project_id: str, *, pictures: int, **fields) -> str:
    """A ready `references` Shot citing `pictures` uploaded images, in citation order."""
    assets = [
        upload_asset(client, project_id, f"Reference {index}", "image", f"ref-{index}.png")
        for index in range(pictures)
    ]
    return reference_shot(
        store,
        project_id,
        mode="references",
        citations=[
            AssetCitation(asset_id=asset["id"], role="reference", order=index)
            for index, asset in enumerate(assets)
        ],
        **fields,
    )


def test_a_prompt_citing_a_picture_slot_the_shot_does_not_have_is_refused(tmp_path: Path):
    """Two pictures attached, `<Picture 3>` cited. Refused before ComfyUI, naming the slot."""
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Bounds"))
    shot_id = bounded_shot(
        client, store, project.id, pictures=2,
        h3_prompt=(
            "integrated_multimodal_description: [Shot 1] <Picture 1>, <Picture 2> and "
            "<Picture 3> stand in the warehouse.\n"
            "overall_soundscape: Warehouse air hums.\n"
            "non_diegetic_music: N/A"
        ),
    )

    response = submit_h3(client, project.id, shot_id)

    assert response.status_code == 422
    detail = response.json()["detail"]
    assert "<Picture 3> is cited" in detail
    assert "only 2 pictures are attached" in detail
    # Named as the timeline names it, and carrying the checker's own sentence rather than a
    # second wording of the rule that could drift from the one the retry loop feeds back.
    saved = store.get(project.id)
    assert detail.startswith(
        REFERENCE_BOUNDS_REFUSAL.split("{shot}")[0]
        + shot_label(saved, saved.shots[0])
    )
    assert detail.endswith(REFERENCE_BOUNDS_REFUSAL.rsplit("{problems}", 1)[1].strip())
    assert comfy.prompts == []


