def test_the_whole_project_put_re_expands_and_cannot_clear_the_recorded_map(tmp_path: Path):
    """The widest sibling write path there is: one body carries every field of every Shot *and*
    every Asset. It can move a citation, so it re-derives -- and a body that has never heard of
    `h3_prompt_map` must not clear the record on its way past.

    **This route could also rename an asset until 2026-08-22**, and that was the second
    re-derivation trigger this test used to demonstrate. It no longer can: `PUT
    .../assets/{id}/name` is the one door and this route re-adopts the stored name per asset id,
    because `name` is required and a stale tab therefore *reasserts* the old one rather than
    omitting it. Both halves are asserted below — the citation move still re-derives, and the
    rename in the same body is ignored.
    """

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    prose_shot = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=lead["id"], role="reference", order=0)],
    )
    document_shot = write_shot(
        store, project_id, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    for shot_id in (prose_shot, document_shot):
        expand_one(client, project_id, shot_id)
    recorded = held(store, project_id, document_shot).h3_prompt_map

    body = store.get(project_id).model_dump(mode="json")
    # A client written before the field existed: it simply omits it, on every shot.
    for shot in body["shots"]:
        shot.pop("h3_prompt_map", None)
    # The gesture this route really is: a citation moved off the lead and onto the bed.
    for shot in body["shots"]:
        if shot["id"] == prose_shot:
            shot["citations"] = [{"asset_id": bed["id"], "role": "reference", "order": 0}]
            shot["asset_ids"] = [bed["id"]]
    # And a rename in the very same body, which this route must now ignore.
    for asset in body["assets"]:
        if asset["id"] == lead["id"]:
            asset["name"] = "HarderFaster Krea multiview"
    assert client.put(f"/api/projects/{project_id}", json=body).status_code == 200

    saved = store.get(project_id)
    moved = next(shot for shot in saved.shots if shot.id == prose_shot)
    assert f"<Picture 1> is {bed['name']}" in moved.h3_prompt
    assert moved.h3_prompt == song_audio_prose(saved, moved)
    assert next(a for a in saved.assets if a.id == lead["id"]).name == lead["name"], (
        "an ordinary save renamed an asset"
    )
    kept = next(shot for shot in saved.shots if shot.id == document_shot)
    assert kept.h3_prompt_map == recorded, "an ordinary save cleared the recorded map"
    assert kept.h3_prompt == GOOD_EXPANSION
    assert len(director.calls) == 1, "the whole-project save asked no model of its own"
    assert comfy.prompts == []


def test_a_client_reasserting_the_pre_refresh_expansion_gets_it_re_derived(tmp_path: Path):
    """The reason the sweep is keyed on the text rather than on a diff of this request.

    The shots write deliberately does not adopt its own reply, so the browser goes on holding
    the `h3_prompt` it sent and reasserts it on its very next gesture -- a drag, a resize,
    anything. A pass keyed on "what changed in this request" would see no citation change there
    and let the stale text stand. Keyed on the text, the same pass simply re-derives it.
    """
    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)
    stale_client = shots_body(store, project_id)

    reattached = [dict(shot) for shot in stale_client]
    attach(reattached[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, reattached).status_code == 200
    refreshed = held(store, project_id, shot_id).h3_prompt
    assert lead["name"] in refreshed

    # The next gesture, sent from the browser's own copy: new citations, the *old* expansion.
    resize = [dict(shot) for shot in stale_client]
    attach(resize[0], bed["id"], lead["id"])
    resize[0]["duration"] = 6.5
    assert put_shots(client, project_id, resize).status_code == 200

    landed = held(store, project_id, shot_id)
    assert landed.duration == 6.5
    assert landed.h3_prompt == refreshed, "the reverted expansion was not re-derived"
    assert director.calls == []
    assert comfy.prompts == []


def test_a_shot_with_no_expansion_is_never_given_one(tmp_path: Path):
    """Empty `h3_prompt` is a real state, not a defect: a shot is plannable long before it is
    expanded, and the render path falls back to the intent exactly as it always did. Attaching
    an asset must not manufacture an expansion, and must not manufacture a map either."""
    client, store, comfy, director, project_id, _bed, lead = map_project(tmp_path)
    shot_id = write_shot(store, project_id, use_song_audio=True, mode="references")

    shots = shots_body(store, project_id)
    attach(shots[0], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200

    shot = held(store, project_id, shot_id)
    assert shot.h3_prompt == ""
    assert shot.h3_prompt_map == ""
    assert shot.prompt == "She turns toward camera."
    assert director.calls == []
    assert comfy.prompts == []
    # And it still submits, on the fallback map the submit route builds from the citations.
    arm(store, project_id)
    assert submit_h3(client, project_id, shot_id).status_code == 202
    assert lead["name"] in comfy.prompts[0]["mvp:condition"]["inputs"]["prompt"]


def test_an_expansion_written_before_the_map_was_recorded_is_not_called_stale(tmp_path: Path):
    """Old manifests load unchanged and render unchanged. `h3_prompt_map` defaults to `""`, and
    that means "not recorded" rather than "stale": nothing knows which map that prompt was built
    from, and refusing a render on a guess is worse than the render."""
    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    project = store.get(project_id)
    project.shots.append(
        Shot(
            id="shot_legacy", start=0, duration=5, status="ready",
            prompt="She turns toward camera.", mode="references", h3_prompt=GOOD_EXPANSION,
            citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
        )
    )
    store.save(project)
    assert held(store, project_id, "shot_legacy").h3_prompt_map == ""

    shots = shots_body(store, project_id)
    attach(shots[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200

    assert held(store, project_id, "shot_legacy").h3_prompt == GOOD_EXPANSION
    assert submit_h3(client, project_id, "shot_legacy").status_code == 202
    assert comfy.prompts[0]["mvp:condition"]["inputs"]["prompt"] == GOOD_EXPANSION
    assert director.calls == []


def test_no_refresh_path_ever_writes_the_directors_own_intent(tmp_path: Path):
    """`Shot.prompt` is never overwritten -- `apply_expansions`' rule, held across every path
    this change touched, per shot, in one sweep. The intent is what re-expansion works from, and
    the first expansion will not be the good one."""
    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    intents = {}
    ids = []
    for index, wiring in enumerate(
        (
            {"use_song_audio": True, "mode": "references"},
            {"mode": "references"},
            {"use_song_audio": True, "mode": "references", "locked": True},
        )
    ):
        shot_id = write_shot(
            store, project_id,
            citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
            **wiring,
        )
        ids.append(shot_id)
        intents[shot_id] = f"Intent {index}"
    project = store.get(project_id)
    for shot in project.shots:
        shot.prompt = intents[shot.id]
    store.save(project)
    for shot_id in ids:
        if not held(store, project_id, shot_id).locked:
            expand_one(client, project_id, shot_id)

    def intents_intact(where: str):
        for shot in store.get(project_id).shots:
            assert shot.prompt == intents[shot.id], f"{where} rewrote an intent"

    shots = shots_body(store, project_id)
    for shot in shots:
        attach(shot, bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200
    intents_intact("PUT /shots")

    body = store.get(project_id).model_dump(mode="json")
    assert client.put(f"/api/projects/{project_id}", json=body).status_code == 200
    intents_intact("PUT /projects/{id}")

    assert client.put(
        f"/api/projects/{project_id}/assets/{lead['id']}/consistency-prompt",
        json={"consistency_prompt": "a woman in a red leather jacket"},
    ).status_code == 200
    intents_intact("PUT /consistency-prompt")

    krea = upload_asset(client, project_id, "Krea multiview", "character", "krea.png")
    assert client.post(
        f"/api/projects/{project_id}/assets/{lead['id']}/replace-citations",
        json={"replacement_id": krea["id"], "confirm_apply": True},
    ).status_code == 200
    intents_intact("POST /replace-citations")
    # One model call in the whole test — the document shot's own expansion. Every refresh above
    # was free, and none of them added a call of its own.
    assert len(director.calls) == 1
    assert comfy.prompts == []


def test_the_recorded_map_is_the_sentence_the_fallback_builds(tmp_path: Path):
    """The stored record and the live map are one construction, `reference_map_sentence` -- two
    spellings of the same join would report every shot in the project as stale."""
    from music_video_producer.app import (
        reference_map_sentence,
        reference_map_tag_lines,
        reference_prompt,
        stale_reference_map,
    )

    client, store, comfy, director, project_id, bed, _lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    saved = store.get(project_id)
    shot = saved.shots[0]
    tags = reference_map_tag_lines(saved, shot)
    sentence = reference_map_sentence(tags)
    assert sentence == (
        "Reference map: <Picture 1> is Dusk Warehouse Bed; "
        "<Audio 1> is the master song for synchronization."
    )
    # The fallback the submit route builds still opens with exactly that, byte for byte.
    assert reference_prompt(shot, tags).startswith(sentence)
    assert not stale_reference_map(saved, shot), "an unexpanded shot is not stale"

    expand_one(client, project_id, shot_id)
    saved = store.get(project_id)
    assert saved.shots[0].h3_prompt_map == sentence
    assert not stale_reference_map(saved, saved.shots[0])
    assert director.calls == []
    assert comfy.prompts == []


# ------------------------------------------------------------------------------------------
# The five branches mutation testing found nothing was holding. Each of these was written
# because a mutation survived, and each names the mutation it kills.
# ------------------------------------------------------------------------------------------


def test_a_hand_edited_prose_survives_a_save_while_its_map_is_current(tmp_path: Path):
    """The staleness guard is not an optimisation, and this is what it protects.

    Dropping `if not stale_reference_map(...)` from the sweep survived every test, because
    re-deriving a *fresh* machine-written prose produces the identical string. What it does not
    survive is a Director's own edit: the sweep would then regenerate that text on every
    unrelated save — a resize, a drag — and the edit would vanish with nothing said.

    So the rule is stated at both ends. A hand edit whose reference map is still current stands,
    however many saves go past it; the companion test below is the other half, where the map has
    gone stale and the text is regenerated from the intent because the map is what conditions
    the render.
    """
    client, store, comfy, director, project_id, bed, _lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)

    machine = held(store, project_id, shot_id).h3_prompt
    edited = f"{machine} She never looks away from the lens."
    shots = shots_body(store, project_id)
    shots[0]["h3_prompt"] = edited
    assert put_shots(client, project_id, shots).status_code == 200
    assert held(store, project_id, shot_id).h3_prompt == edited

    # Two more ordinary saves that touch nothing about the references at all.
    for duration in (6.0, 6.5):
        shots = shots_body(store, project_id)
        shots[0]["duration"] = duration
        assert put_shots(client, project_id, shots).status_code == 200
        assert held(store, project_id, shot_id).h3_prompt == edited, "an unrelated save rewrote it"

    assert director.calls == []
    assert comfy.prompts == []


def test_a_hand_edited_prose_whose_map_has_gone_stale_is_regenerated(tmp_path: Path):
    """The other half of the rule above, said out loud because it discards a Director's words.

    A hand edit is preserved while its map is current and regenerated when it is not. The map is
    what conditions the render, so a prose whose map has gone stale is not text worth keeping —
    and nothing is lost that the Director cannot get back, because `Shot.prompt` is where their
    intent lives and the regeneration is built from it.
    """

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)

    shots = shots_body(store, project_id)
    shots[0]["h3_prompt"] = f"{held(store, project_id, shot_id).h3_prompt} Hand-written tail."
    assert put_shots(client, project_id, shots).status_code == 200

    shots = shots_body(store, project_id)
    attach(shots[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200

    saved = store.get(project_id)
    shot = next(item for item in saved.shots if item.id == shot_id)
    assert "Hand-written tail." not in shot.h3_prompt
    assert shot.h3_prompt == song_audio_prose(saved, shot)
    assert shot.prompt == "She turns toward camera.", "the intent it was rebuilt from is untouched"
    assert director.calls == []
    assert comfy.prompts == []


def test_a_shot_that_no_longer_rides_the_song_is_refused_rather_than_rebuilt_as_prose(
    tmp_path: Path,
):
    """`use_song_audio` is a condition on the *rebuild*, not only on the staleness check.

    Dropping it from the sweep survived, because the form of the stored text already selects the
    prose arm. But the deterministic recipe is only the right expansion for a song-audio
    references shot: `attempt_expansion` short-circuits for exactly that shape and sends every
    other shot to the specialist. Turning the song off makes this shot a document-mode shot, so
    rebuilding it as prose would cement a form the expansion route would never have written —
    and it would do so silently, on a save the Director made for another reason.
    """
    from music_video_producer.app import stale_reference_map

    client, store, comfy, director, project_id, bed, _lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)
    before = held(store, project_id, shot_id).h3_prompt
    assert "<Audio 1>" in before

    shots = shots_body(store, project_id)
    shots[0]["use_song_audio"] = False
    assert put_shots(client, project_id, shots).status_code == 200

    saved = store.get(project_id)
    after = next(item for item in saved.shots if item.id == shot_id)
    assert after.h3_prompt == before, "the prose recipe was applied to a shot it is not for"
    assert stale_reference_map(saved, after)
    # And it cannot reach a render. **The sharper refusal wins here, by design**: the stored prose
    # still names `<Audio 1>` and the shot no longer has an audio slot, so `check_reference_bounds`
    # answers first with the concrete tag to fix. The staleness gate sits behind it precisely so
    # that the more specific sentence is the one the Director reads.
    arm(store, project_id)
    refused = submit_h3(client, project_id, shot_id)
    assert refused.status_code == 422
    assert "cites a reference slot it does not have" in refused.json()["detail"]
    assert director.calls == []
    assert comfy.prompts == []


def test_a_shot_whose_mode_moved_off_references_is_refused_rather_than_rebuilt_as_prose(
    tmp_path: Path,
):
    """The mode is the second condition on the rebuild, and it is a real state to be in.

    The keyframe modes keep the document path — `attempt_expansion` says so, and their graphs
    differ — so a shot moved from `references` to `first_last` in the inspector must not have
    the prose recipe re-applied to the expansion it is still carrying. Changing a shot's mode is
    an ordinary edit, and it arrives on the same whole-shot write as everything else.
    """
    from music_video_producer.app import stale_reference_map

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, use_song_audio=True, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)
    before = held(store, project_id, shot_id).h3_prompt

    shots = shots_body(store, project_id)
    shots[0]["mode"] = "first_last"
    attach(shots[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200

    saved = store.get(project_id)
    after = next(item for item in saved.shots if item.id == shot_id)
    assert after.mode == "first_last"
    assert after.h3_prompt == before, "the prose recipe was applied to a keyframe-mode shot"
    # Stale, and therefore unable to reach a render — which is the point of not rebuilding it.
    assert stale_reference_map(saved, after)
    assert director.calls == []
    assert comfy.prompts == []


def test_writing_the_h3_box_by_hand_records_the_map_it_was_written_against(tmp_path: Path):
    """The branch of the generic-write guard that lets a Director fix a stale expansion themselves.

    `_adopt_expansion_maps` keeps the stored record when the body's `h3_prompt` is unchanged —
    that is what stops a client which has never heard of the field clearing it. When the body's
    `h3_prompt` *differs*, the inspector's box has been written by hand, and the text someone
    typed just now was typed against the plan as it stands now. Recording `""` there instead
    survived every test, and would have left a Director who had already corrected the prompt
    unable to render it and told to correct it again.
    """
    from music_video_producer.app import reference_map_sentence

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)
    shots = shots_body(store, project_id)
    attach(shots[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200
    arm(store, project_id)
    assert submit_h3(client, project_id, shot_id).status_code == 422

    # The Director corrects it themselves, in the inspector, naming both pictures.
    corrected = GOOD_EXPANSION.replace(
        "A grey wolf paces", "A grey wolf paces past <Picture 2> and"
    )
    shots = shots_body(store, project_id)
    shots[0]["h3_prompt"] = corrected
    assert put_shots(client, project_id, shots).status_code == 200

    fixed = held(store, project_id, shot_id)
    assert fixed.h3_prompt == corrected
    assert fixed.h3_prompt_map == reference_map_sentence(
        ["<Picture 1> is Dusk Warehouse Bed", "<Picture 2> is HarderFaster sheet"]
    )
    assert submit_h3(client, project_id, shot_id).status_code == 202
    assert comfy.prompts[0]["mvp:condition"]["inputs"]["prompt"] == corrected
    assert len(director.calls) == 1, "the hand correction asked no model"


def test_the_plan_wide_expansion_records_each_shots_map_too(tmp_path: Path):
    """The sibling of the single-shot expansion route, and the gap that is always this one.

    `expand_shot_prompt` was covered and `apply_expansions` — which the whole-plan sweep and the
    assistant's expansion tool both commit through — was not, so dropping its record survived.
    A document expansion written by the sweep would then have carried no map at all, and every
    citation change after it would have been undetectable: the refusal would simply never fire
    for a plan expanded the way a plan is actually expanded.
    """
    from music_video_producer.app import STALE_REFERENCE_MAP_REFUSAL, reference_map_sentence

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    response = client.post(f"/api/projects/{project_id}/shots/expand-prompts")
    assert response.status_code == 200, response.text
    assert len(director.calls) == 1

    expanded = held(store, project_id, shot_id)
    assert expanded.h3_prompt == GOOD_EXPANSION
    assert expanded.h3_prompt_map == reference_map_sentence(["<Picture 1> is Dusk Warehouse Bed"])

    shots = shots_body(store, project_id)
    attach(shots[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200
    arm(store, project_id)

    refused = submit_h3(client, project_id, shot_id)
    assert refused.status_code == 422
    assert refused.json()["detail"] == STALE_REFERENCE_MAP_REFUSAL.format(
        shot=shot_label(store.get(project_id), held(store, project_id, shot_id))
    )
    assert comfy.prompts == []


def test_the_pre_flight_blocks_exactly_the_shots_the_submit_route_refuses(tmp_path: Path):
    """The headline: the report and the route are driven against one project and must agree.

    The gap, in the Director's words on 2026-08-21: the batch pre-flight said "33 ready", they
    confirmed the GPU cost, the batch started, and *then* one shot was skipped by name. The refusal
    had existed since 2026-08-20 and `readiness_report` said nothing about it -- so the one moment a
    Director could have acted on it, before spending anything, passed in silence.

    Asserted as set equality between "what the report blocks" and "what the route turns away",
    rather than as two independent facts about one shot. A pre-flight that blocked *more* than the
    route refuses would be its own defect -- a gate over a legitimate state gets worked around --
    so both directions have to be wrong for this to pass wrongly.
    """
    from music_video_producer.app import STALE_REFERENCE_MAP_REFUSAL
    from music_video_producer.batch import (
        NOTE_KIND_STALE_MAP,
        SHOT_WITH_STALE_REFERENCE_MAP,
        readiness_report,
    )
    from music_video_producer.reference_map import STALE_REFERENCE_MAP_REMEDY

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    fresh_id = write_shot(
        store, project_id, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    stale_id = write_shot(
        store, project_id, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, fresh_id)
    expand_one(client, project_id, stale_id)

    # The gesture that makes one of them stale, at the route it actually arrives on: the browser
    # attaches an asset by writing the whole shot list back.
    shots = shots_body(store, project_id)
    attach(next(shot for shot in shots if shot["id"] == stale_id), bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200
    arm(store, project_id)

    report = readiness_report(store.get(project_id))
    # The pre-flight is pure: no model, and nothing on the wire to ComfyUI.
    assert comfy.prompts == []
    assert len(director.calls) == 2, "the report asked no model of its own"
    assert report.ready is False
    assert report.blocked_ids() == [stale_id]
    assert report.blocked_ids(kind=NOTE_KIND_STALE_MAP) == [stale_id]
    assert report.blocking[0].reason == SHOT_WITH_STALE_REFERENCE_MAP
    # Both shots have a prompt, and the count that says so still says so.
    assert (report.ready_count, report.shot_count) == (2, 2)

    verdicts = {
        shot_id: submit_h3(client, project_id, shot_id) for shot_id in (stale_id, fresh_id)
    }
    assert {shot_id: reply.status_code for shot_id, reply in verdicts.items()} == {
        stale_id: 422, fresh_id: 202
    }
    # The set the report blocks *is* the set the route refuses. Neither layer is stricter.
    assert {shot_id for shot_id, reply in verdicts.items() if reply.status_code == 422} == set(
        report.blocked_ids()
    )
    # And the two layers say one thing about it: the route's own sentence, and the report's, share
    # every clause that is about the problem rather than about which layer is speaking.
    assert verdicts[stale_id].json()["detail"] == STALE_REFERENCE_MAP_REFUSAL.format(
        shot=shot_label(store.get(project_id), held(store, project_id, stale_id))
    )
    assert STALE_REFERENCE_MAP_REMEDY in verdicts[stale_id].json()["detail"]
    assert STALE_REFERENCE_MAP_REMEDY in SHOT_WITH_STALE_REFERENCE_MAP
    # One render went out, for the one shot both layers called submittable.
    assert len(comfy.prompts) == 1


def test_a_readiness_report_over_a_stale_plan_leaves_the_manifest_untouched(tmp_path: Path):
    """AD-5 at the store, not only on the in-memory object: readiness is derived, never stored.

    Re-read through a **fresh** `ProjectStore` over the same data root, because the object the
    report was handed is the one a caller is holding -- a report that quietly repaired the map, or
    recorded its verdict, would be invisible to a comparison against that same object.
    """
    from music_video_producer.batch import readiness_report

    client, store, comfy, director, project_id, bed, lead = map_project(tmp_path)
    shot_id = write_shot(
        store, project_id, mode="references",
        citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
    )
    expand_one(client, project_id, shot_id)
    shots = shots_body(store, project_id)
    attach(shots[0], bed["id"], lead["id"])
    assert put_shots(client, project_id, shots).status_code == 200

    before = ProjectStore(tmp_path).get(project_id).model_dump(mode="json")
    report = readiness_report(ProjectStore(tmp_path).get(project_id))

    assert report.ready is False
    assert ProjectStore(tmp_path).get(project_id).model_dump(mode="json") == before
    assert comfy.prompts == []
    assert len(director.calls) == 1
    assert len(director.calls) == 1


def test_every_writer_of_an_expansion_records_the_map_it_was_written_against():
    """The sibling gap, closed structurally instead of one instance at a time.

    `expand_shot_prompt` recorded the map and `apply_expansions` did not, and nothing noticed
    because the tested route and the untested one are different functions doing the same job —
    the shape this repository keeps rediscovering. So the rule is asserted over the module rather
    than over the two writers anybody happens to know about: **any function that assigns
    `h3_prompt` must also assign `h3_prompt_map`.** A third writer added later fails here.

    Parsed rather than grepped, and attributed to the *innermost* enclosing function, because
    every route in this module is nested inside `create_app` and a scan that credited the outer
    function would pass on any file that recorded a map anywhere at all.
    """
    import ast

    source = Path("src/music_video_producer/app.py").read_text(encoding="utf-8")
    tree = ast.parse(source)
    enclosing: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            enclosing[child] = parent

    def innermost_function(node: ast.AST) -> str:
        while node in enclosing:
            node = enclosing[node]
            if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef):
                return node.name
        return "<module>"

    written: dict[str, set[str]] = {}
    for node in ast.walk(tree):
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if isinstance(target, ast.Attribute) and target.attr in (
                "h3_prompt", "h3_prompt_map"
            ):
                written.setdefault(innermost_function(node), set()).add(target.attr)

    expansion_writers = {name for name, fields in written.items() if "h3_prompt" in fields}
    # The scan has to find the writers it is asserting over, or it asserts nothing.
    assert expansion_writers >= {"apply_expansions", "refresh_reference_maps"}, expansion_writers
    for name in sorted(expansion_writers):
        assert "h3_prompt_map" in written[name], (
            f"{name} writes an expansion without recording the reference map it was written "
            "against, so a citation change under it would be undetectable"
        )


def test_neither_whole_shot_write_can_clear_the_recorded_map(tmp_path: Path):
    """Both siblings, from one list, because they have been the same hole at different times.

    `PUT /projects/{id}` and `PUT /projects/{id}/shots` each bind a whole client-supplied shot
    list, so a client written before `h3_prompt_map` existed omits it on every shot and one
    ordinary save would erase the record — silently retiring the refusal that keeps a stale map
    out of ComfyUI. Driven against both rather than one, so a fix that lands on the wider route
    and not the narrower one fails here.
    """
    def whole_project(client, store, project_id):
        body = store.get(project_id).model_dump(mode="json")
        for shot in body["shots"]:
            shot.pop("h3_prompt_map", None)
        return client.put(f"/api/projects/{project_id}", json=body)

    def shots_only(client, store, project_id):
        shots = shots_body(store, project_id)
        for shot in shots:
            shot.pop("h3_prompt_map", None)
        return put_shots(client, project_id, shots)

    for name, save in (("PUT /projects/{id}", whole_project), ("PUT /shots", shots_only)):
        client, store, comfy, director, project_id, bed, lead = map_project(tmp_path / name[4:9])
        shot_id = write_shot(
            store, project_id, mode="references",
            citations=[AssetCitation(asset_id=bed["id"], role="reference", order=0)],
        )
        expand_one(client, project_id, shot_id)
        recorded = held(store, project_id, shot_id).h3_prompt_map
        assert recorded, name

        assert save(client, store, project_id).status_code == 200, name
        assert held(store, project_id, shot_id).h3_prompt_map == recorded, (
            f"{name} cleared the recorded map from a body that merely omitted it"
        )
        assert len(director.calls) == 1, f"{name} asked a model of its own"

        # And the record still does its job: a citation moved afterwards is still refused.
        shots = shots_body(store, project_id)
        attach(shots[0], bed["id"], lead["id"])
        assert put_shots(client, project_id, shots).status_code == 200
        arm(store, project_id)
        assert submit_h3(client, project_id, shot_id).status_code == 422, name
        assert comfy.prompts == [], name


# ---------------------------------------------------------------------------------------------
# Who sings the song, and which character is which singer (pass 1).
#
# Two new fields, both defaulted, both with exactly one writer. The tests below are the
# `consistency_prompt`/`default_setting_id` sibling-write suite applied to them, plus the
# validation the Director named and the byte-identity pin on their live project.
# ---------------------------------------------------------------------------------------------


def cast_project(store, name: str = "Cast", *, characters: int = 2) -> Project:
    """A song plus `characters` character assets and one prop, none of them slotted."""
    project = store.create(Project(name=name))
    project.song = Song(title="Harder", source="imported", path="media/h.mp3", duration=60.0)
    project.assets = [
        Asset(id=f"asset_char{index}", name=f"Singer {index}", kind="character",
              path=f"media/c{index}.png")
        for index in range(1, characters + 1)
    ] + [Asset(id="asset_mic", name="Vintage Chrome Mic", kind="prop", path="media/mic.png")]
    store.save(project)
    return project


def set_vocal_type(client, project_id: str, vocal_type: str):
    return client.put(
        f"/api/projects/{project_id}/song/vocal-type", json={"vocal_type": vocal_type}
    )


def set_slot(client, project_id: str, asset_id: str, slot: int):
    return client.put(
        f"/api/projects/{project_id}/assets/{asset_id}/character-slot",
        json={"character_slot": slot},
    )


def test_every_vocal_type_offers_exactly_the_line_options_its_cast_needs():
    """The Director's decision: "a simple dropdown at each line with selections depending on what
    the user selected for the song type". A solo type offers none, and that is the whole point —
    a dropdown whose answer never varies is noise on every line of the sheet."""
    offered = {
        value: [option.label for option in line_tag_options(value)]
        for value in VOCAL_TYPE_SPECS
    }

    assert offered == {
        # Nothing declared, no sung line, one voice, one voice, and a mass voice: no cast to
        # attribute a line to, so no dropdown is drawn at all.
        "unstated": [],
        "instrumental": [],
        "female": [],
        "male": [],
        "choir": [],
        "duet": ["Untagged", "Char 1", "Char 2", "Both"],
        "ensemble": ["Untagged", "Char 1", "Char 2", "Char 3", "All"],
    }
    # The marks are H3's own speaker notation, which `h3_prompt._SPEAKER` already parses — the
    # spelling is reused rather than invented, so the tag is understood downstream.
    assert [option.notation for option in line_tag_options("duet")] == [
        "", "(S1)", "(S2)", "(S1, S2)"
    ]
    assert line_tag_options("ensemble")[-1].notation == "(S1, S2, S3)"
    # No dropdown can offer a slot no asset is allowed to hold.
    for spec in VOCAL_TYPE_SPECS.values():
        for option in spec.line_tags:
            assert all(1 <= slot <= CHARACTER_SLOT_LIMIT for slot in option.slots)


def test_the_vocal_type_is_set_by_one_route_and_nothing_else(tmp_path: Path):
    """The write path, and every sibling that must not become a second one.

    `Asset.consistency_prompt`'s rule and `Project.default_setting_id`'s, applied to a field with
    the same shape: a defaulted value that every client written before it existed simply omits.
    The generic full-project `PUT` is the route that has now been this hole six times, so it
    re-adopts the stored value — and it must fail in BOTH directions, blanking and inventing.
    """
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)

    # Defaulted, and the default asserts nothing rather than asserting a cast.
    assert store.get(project.id).song.vocal_type == "unstated"
    assert set_vocal_type(client, project.id, "duet").status_code == 200
    assert store.get(project.id).song.vocal_type == "duet"

    # An ordinary save from a client that has never heard of the field must not clear it.
    body = client.get(f"/api/projects/{project.id}").json()
    body["song"].pop("vocal_type")
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    assert store.get(project.id).song.vocal_type == "duet"

    # And a body that INVENTS one must not declare a cast the Director never declared.
    body = client.get(f"/api/projects/{project.id}").json()
    body["song"]["vocal_type"] = "choir"
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    assert store.get(project.id).song.vocal_type == "duet", "an ordinary save re-declared the cast"
    # Both saves above returned 200 rather than the song-replacement refusal, which is the other
    # half of the guard: the adoption happens AHEAD of `project.song != current.song`, so a body
    # differing only in this field compares equal and an ordinary save from an old client is not
    # told it is replacing the song.

    # Re-declaring "unstated" is how a declaration is taken back, and it is not a no-op.
    assert set_vocal_type(client, project.id, "unstated").status_code == 200
    assert store.get(project.id).song.vocal_type == "unstated"
    # An unknown value is refused by the schema rather than stored.
    assert set_vocal_type(client, project.id, "quartet").status_code == 422
    # And a body that omits the field entirely is refused too: the omitted value would be
    # "unstated", so a silent default here would be the same un-declaration in a smaller key.
    assert client.put(
        f"/api/projects/{project.id}/song/vocal-type", json={}
    ).status_code == 422


def test_a_confirmed_song_replacement_does_not_carry_the_old_cast_across(tmp_path: Path):
    """`_detach_song_recovery_slots`' argument, applied to the declaration beside them: a vocal
    type describes the track it sits on. Carried across a replacement it would say the new song
    is a duet on the strength of the old one's declaration — which is exactly the fabricated
    value the one-writer rule exists to prevent, arriving by a route that writes nothing."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)
    assert set_vocal_type(client, project.id, "duet").status_code == 200

    body = client.get(f"/api/projects/{project.id}").json()
    body["song"] = {
        "title": "A Different Track", "source": "imported", "path": "media/other.mp3",
        "duration": 121.0, "lyrics": "", "caption": "",
    }
    replaced = client.put(
        f"/api/projects/{project.id}?confirm_song_replacement=true", json=body
    )
    assert replaced.status_code == 200, replaced.text
    saved = store.get(project.id)
    assert saved.song.title == "A Different Track"
    assert saved.song.vocal_type == "unstated", "the new song inherited the old song's cast"


def test_declaring_a_vocal_type_touches_no_shot_and_no_lyric(tmp_path: Path):
    """A declaration about the song, read by the next plan. `replace_default_setting`'s rule: a
    sweep over work the Director already has is the silent bulk edit this codebase forbids — and
    since the per-line marks live in the lyric sheet, "touches no lyric" is also what stops the
    route that declares the cast from being a second route that can invent a line's singer."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)
    project.song.lyrics = "[Verse]\nOne line\nTwo line\n"
    project.shots = [Shot(id="shot_one", start=0, duration=5, prompt="A wide shot.",
                          singing="singing")]
    store.save(project)

    assert set_vocal_type(client, project.id, "instrumental").status_code == 200

    saved = store.get(project.id)
    assert saved.song.lyrics == "[Verse]\nOne line\nTwo line\n"
    # Instrumental does NOT sweep the singing mark. Nothing infers a singing state, and a
    # declaration about the song is not a measurement of a window.
    assert saved.shots[0].singing == "singing"
    assert saved.shots[0].prompt == "A wide shot."


def test_a_character_slot_is_set_by_one_route_and_nothing_else(tmp_path: Path):
    """`consistency_prompt`'s sibling-write suite, for a defaulted `int` instead of a defaulted
    `str`. Both directions: an ordinary save can neither un-slot the cast nor invent one."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)

    assert all(asset.character_slot == 0 for asset in store.get(project.id).assets)
    assert set_slot(client, project.id, "asset_char1", 1).status_code == 200
    assert set_slot(client, project.id, "asset_char2", 2).status_code == 200
    assert {slot: asset.id for slot, asset in
            character_slot_assets(store.get(project.id)).items()} == {
        1: "asset_char1", 2: "asset_char2"
    }

    # A client that has never heard of the field omits it on every asset; one ordinary save
    # would otherwise un-slot the whole cast at once and leave every `(S1)` resolving to nothing.
    body = client.get(f"/api/projects/{project.id}").json()
    for asset in body["assets"]:
        asset.pop("character_slot")
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    assert [asset.character_slot for asset in store.get(project.id).assets] == [1, 2, 0]

    # And a body that invents one must not slot an asset the Director never slotted.
    body = client.get(f"/api/projects/{project.id}").json()
    for asset in body["assets"]:
        asset["character_slot"] = 3 if asset["id"] == "asset_mic" else 0
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    assert [asset.character_slot for asset in store.get(project.id).assets] == [1, 2, 0]

    # An asset the stored project does not hold gets 0 rather than whatever it carried: a slot
    # that arrived on this route was not set by the Director on the route that sets slots.
    body = client.get(f"/api/projects/{project.id}").json()
    body["assets"].append({
        "id": "asset_smuggled", "name": "Uninvited", "kind": "character",
        "path": "media/x.png", "character_slot": 3,
    })
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    smuggled = next(a for a in store.get(project.id).assets if a.id == "asset_smuggled")
    assert smuggled.character_slot == 0, "an ordinary save slotted an asset it also introduced"

    # Zero clears it, which is what "not one of the singers" means.
    assert set_slot(client, project.id, "asset_char1", 0).status_code == 200
    held = character_slot_assets(store.get(project.id))
    assert {slot: asset.id for slot, asset in held.items()} == {2: "asset_char2"}


def test_a_promoted_identity_sheet_does_not_inherit_its_sources_slot(tmp_path: Path):
    """The opposite call to the appearance anchor, for the opposite reason — asserted on the
    **promotion route itself**, because that is where the decision is made and it is made by
    omission.

    An anchor describes the subject and the sheet is the picture shots actually cite, so the
    sheet inherits it. A slot is an *identity*, and a sheet holding its source's slot would put
    two assets in one slot — the state `replace_character_slot` refuses by name, because a tagged
    line pointing at two references renders by accident, and the promotion route does not go
    through that refusal. Nothing is lost: a citation of the slotted source resolves to the sheet
    through `prefer_identity_sheets` anyway, so the slot names the subject and the substitution
    names the picture.
    """
    from music_video_producer.models import identity_sheet_ids

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Promotion"))
    lucy = upload_asset(client, project.id, "Lucy Vane", "character", "lucy.png")
    assert set_slot(client, project.id, lucy["id"], 1).status_code == 200

    assert client.post(
        f"/api/projects/{project.id}/assets/{lucy['id']}/multiview",
        json={"prompt": "character sheet", "seed": 0},
    ).status_code == 202

    saved = store.get(project.id)
    sheet = saved.assets[-1]
    assert sheet.source == "krea-multiview" and sheet.parent_id == lucy["id"]
    assert sheet.character_slot == 0, "the promoted sheet took its source's slot"
    # One asset in slot 1, still, and it is the subject rather than the sheet of it.
    assert {slot: asset.id for slot, asset in character_slot_assets(saved).items()} == {
        1: lucy["id"]
    }
    # And the substitution still points every citation of the slotted source at the sheet, which
    # is why nothing is lost by leaving the sheet unslotted.
    assert identity_sheet_ids(saved) == {}, "the sheet has no file yet, so nothing substitutes"


def test_the_character_slot_route_refuses_what_it_cannot_resolve(tmp_path: Path):
    """Three refusals, each leaving the asset exactly as it was: a slot on something that cannot
    sing, a slot two characters would share, and a number no dropdown can name."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)

    assert set_slot(client, project.id, "asset_gone", 1).status_code == 404

    prop = set_slot(client, project.id, "asset_mic", 1)
    assert prop.status_code == 422
    assert "character slot names one of the song's singers" in prop.json()["detail"]

    assert set_slot(client, project.id, "asset_char1", 1).status_code == 200
    taken = set_slot(client, project.id, "asset_char2", 1)
    assert taken.status_code == 422
    # Named, because "take it off them first" is the action and a refusal that does not say
    # whose slot it is cannot be acted on.
    assert "Singer 1" in taken.json()["detail"]
    # An asset re-asserting its own slot is not a collision.
    assert set_slot(client, project.id, "asset_char1", 1).status_code == 200

    # Past the bound, refused by the schema before the route runs.
    assert set_slot(client, project.id, "asset_char2", CHARACTER_SLOT_LIMIT + 1).status_code == 422
    assert set_slot(client, project.id, "asset_char2", -1).status_code == 422
    assert [asset.character_slot for asset in store.get(project.id).assets] == [1, 0, 0]


def test_a_hand_edited_manifest_cannot_smuggle_in_a_singer(tmp_path: Path):
    """`character_slot_assets` re-validates on every read, because the route is not the only way
    a number reaches the manifest. Nothing in this application can create either state below —
    the route refuses a non-character and refuses a contested slot — so both are what a
    hand-edited `project.json` produces, and both resolve to the honest answer rather than to a
    fabricated singer."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)
    saved = store.get(project.id)
    # A prop wearing a slot number. A slot names a singer, and a prop cannot sing, so `(S1)`
    # must not resolve to it — otherwise a duet would read as fully cast on a microphone.
    saved.assets[2].character_slot = 1
    store.save(saved)
    assert character_slot_assets(store.get(project.id)) == {}
    assert set_vocal_type(client, project.id, "duet").status_code == 200
    assert len(vocal_cast_problems(store.get(project.id))) == 1

    # Two characters in one slot. Resolved to the FIRST in manifest order, which is append
    # order, and never to the last: a tie-break that moved when an asset was appended would make
    # every tagged line in the sheet silently change who it points at.
    saved = store.get(project.id)
    saved.assets[2].character_slot = 0
    saved.assets[0].character_slot = 1
    saved.assets[1].character_slot = 1
    store.save(saved)
    resolved = character_slot_assets(store.get(project.id))
    assert {slot: asset.id for slot, asset in resolved.items()} == {1: "asset_char1"}


def test_populate_flags_a_duet_with_one_character_slotted(tmp_path: Path):
    """The Director's own example, at the moment they named: "flagged if the user labeled the
    song as a duet but they only have one character asset if the user clicks Populate Timeline".

    Flagged, never refused — the plan still lands, because the slots are set in another tab and
    sending the Director away from the button they pressed costs them the plan.
    """
    director = PlanningDirector(shots=[(index * 5, 5, f"Shot {index}.") for index in range(12)])
    client, store, _comfy = make_client(tmp_path, director=director)
    project = cast_project(store)
    assert set_vocal_type(client, project.id, "duet").status_code == 200
    assert set_slot(client, project.id, "asset_char1", 1).status_code == 200

    flagged = populate(client, project.id)
    assert flagged.status_code == 200
    body = flagged.json()
    assert len(body["cast_notices"]) == 1
    notice = body["cast_notices"][0]
    assert "Duet declared" in notice and "1 of the 2" in notice and "S2" in notice
    # The plan landed anyway. A flag is not a refusal.
    assert body["created"] == len(store.get(project.id).shots) > 0

    # Slot the second singer and the same click is silent.
    assert set_slot(client, project.id, "asset_char2", 2).status_code == 200
    assert populate(client, project.id).json()["cast_notices"] == []


def test_a_project_that_declared_nothing_is_never_flagged(tmp_path: Path):
    """Every project that existed before this feature. `unstated` needs no slots, and neither
    does a solo or a choir: a type with no per-line marks has no `(S1)` to resolve, so there is
    nothing a slot would be needed for."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store, characters=0)

    for value in ("unstated", "female", "male", "choir"):
        assert set_vocal_type(client, project.id, value).status_code == 200
        assert vocal_cast_problems(store.get(project.id)) == []

    # And a duet with nothing slotted is flagged, which is what makes the silence above a
    # decision rather than a check that never fires.
    assert set_vocal_type(client, project.id, "duet").status_code == 200
    assert len(vocal_cast_problems(store.get(project.id))) == 1


def test_instrumental_is_coherent_end_to_end(tmp_path: Path):
    """Declaring Instrumental is a real case, not an empty one.

    Four things have to line up: no per-line dropdown (there is no sung line to attribute), no
    character slot needed, the recorded consequence said once where it matters, and the singing
    guard untouched — a window is sung or not because of what Whisper measured, never because of
    a label.
    """
    director = PlanningDirector(shots=[(index * 5, 5, f"Shot {index}.") for index in range(12)])
    client, store, _comfy = make_client(tmp_path, director=director)
    project = cast_project(store, characters=0)
    assert set_vocal_type(client, project.id, "instrumental").status_code == 200

    # No cast to choose from at any line, and no slot to fill.
    assert line_tag_options("instrumental") == ()
    assert VOCAL_TYPE_SPECS["instrumental"].slots == ()

    # The consequence, said once, and it is the roadmap's own recorded note.
    assert vocal_cast_problems(store.get(project.id)) == [INSTRUMENTAL_NOTE]
    assert "lean" not in INSTRUMENTAL_NOTE  # the roadmap's wording, restated rather than quoted
    assert "treatment carries the whole story" in INSTRUMENTAL_NOTE

    report = populate(client, project.id)
    assert report.status_code == 200
    assert report.json()["cast_notices"] == [INSTRUMENTAL_NOTE]

    # The vocal-band guard is untouched and still the only thing that decides a sung window.
    # This project has NO measured spans, so nothing is downgraded on evidence nobody has — the
    # declaration did not become a measurement.
    saved = store.get(project.id)
    assert saved.song.vocal_spans == []
    assert {shot.singing for shot in saved.shots} == {"not_singing"}, (
        "the model's own performance declaration decides, exactly as it did before"
    )


def test_the_vocal_fields_reach_no_model_in_pass_one(tmp_path: Path):
    """Both fields are withheld from every Director context dump, and no tool schema exposes
    either. Pass 1's rule: nothing has been designed for a model to DO with them yet, and a bare
    key shipped into every prompt is a prompt regression bought with nothing."""
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)
    assert set_vocal_type(client, project.id, "duet").status_code == 200
    assert set_slot(client, project.id, "asset_char1", 1).status_code == 200

    dumped = store.get(project.id).model_dump(mode="json", exclude=DIRECTOR_CONTEXT_EXCLUDE)
    assert "vocal_type" not in dumped["song"]
    assert all("character_slot" not in asset for asset in dumped["assets"])
    # Everything that was in the dump before is still in it: classifying the Asset fields is a
    # guard against the NEXT field, not a removal of any existing one.
    assert {"id", "name", "kind", "path", "source", "prompt", "consistency_prompt"} <= set(
        dumped["assets"][0]
    )
    # And no model-facing schema mentions either field — the recorded rule for a mechanical one,
    # after a local model twice omitted booleans it claimed to have set.
    from music_video_producer.director import (
        AssetProposal,
        FillShotsArguments,
        director_result_schema,
    )

    exposed = json.dumps([
        director_result_schema(require=("shots",)),
        FillShotsArguments.model_json_schema(),
        AssetProposal.model_json_schema(),
    ])
    assert "vocal_type" not in exposed and "character_slot" not in exposed


def test_a_manifest_without_the_vocal_fields_loads_and_round_trips(tmp_path: Path):
    """Old manifests load unchanged. Written by hand without either key, read through a fresh
    `ProjectStore`, and saved back — the two fields arrive at their defaults, which mean *not
    stated* and *unslotted*, and nothing else about the manifest moves."""
    store = ProjectStore(tmp_path)
    project = store.create(Project(name="Legacy"))
    raw = json.loads((store.project_dir(project.id) / "project.json").read_text(encoding="utf-8"))
    raw["song"] = {
        "title": "Harder", "source": "imported", "path": "media/h.mp3", "duration": 60.0,
        "lyrics": "[Verse]\nOne line\n", "caption": "",
    }
    raw["assets"] = [{"id": "asset_a", "name": "Singer", "kind": "character", "path": "a.png"}]
    (store.project_dir(project.id) / "project.json").write_text(
        json.dumps(raw), encoding="utf-8"
    )

    loaded = ProjectStore(tmp_path).get(project.id)
    assert loaded.song.vocal_type == "unstated"
    assert loaded.assets[0].character_slot == 0
    assert vocal_cast_problems(loaded) == []
    assert character_slot_assets(loaded) == {}

    ProjectStore(tmp_path).save(loaded)
    again = ProjectStore(tmp_path).get(project.id)
    assert again.song.vocal_type == "unstated"
    assert again.assets[0].character_slot == 0
    assert again.song.lyrics == "[Verse]\nOne line\n"


def test_tagging_a_sheet_travels_on_the_lyric_route_and_survives_an_edit(tmp_path: Path):
    """The storage decision, end to end over HTTP.

    The dropdown's write is a lyric-sheet edit, so it lands on `PUT /song/context` — the route
    that already exists for the sheet — and there is no second field to save, to guard, or to
    let drift. Editing the sheet afterwards moves every tag with its own words, because they are
    the same characters.
    """
    client, store, _comfy = make_client(tmp_path)
    project = cast_project(store)
    project.song.lyrics = "[Verse]\nAlpha line\nBravo line\n"
    store.save(project)
    assert set_vocal_type(client, project.id, "duet").status_code == 200

    # What the dropdown produces, computed by the same function the browser calls.
    tagged = tag_lyric_line(tag_lyric_line(store.get(project.id).song.lyrics, 1, (1,)), 2, (1, 2))
    assert client.put(
        f"/api/projects/{project.id}/song/context", json={"lyrics": tagged, "caption": ""}
    ).status_code == 200
    stored = store.get(project.id).song.lyrics
    assert {line.text: line.slots for line in lyric_line_tags(stored) if line.taggable} == {
        "Alpha line": (1,), "Bravo line": (1, 2)
    }

    # The Director now edits the sheet by hand, inserting a block above and deleting a line.
    edited = stored.replace("[Verse]\n", "[Intro]\nZulu line\n[Verse]\n").replace(
        "(S1) Alpha line\n", ""
    )
    assert client.put(
        f"/api/projects/{project.id}/song/context", json={"lyrics": edited, "caption": ""}
    ).status_code == 200
    assert {line.text: line.slots for line in
            lyric_line_tags(store.get(project.id).song.lyrics) if line.taggable} == {
        "Zulu line": (), "Bravo line": (1, 2)
    }, "a tag drifted off its words when the sheet was edited"



# ----------------------------------------------------------------------------------------------
# Render timing at the routes (2026-08-21).
#
# `RenderJob.updated_at` was set by its default factory and no settle path ever wrote it again,
# so every settled job in the Director's live manifest carried `updated_at == created_at` to the
# microsecond and this application had never recorded what a render costs. The one render-cost
# figure the codebase acted on -- a 221-frame window at "2.2 HOURS" -- was a code comment citing
# itself, with no primary record anywhere; when it was finally challenged it proved wrong by
# roughly 3.4x, and correcting it meant reading mtimes off ComfyUI's output tree by hand.
#
# These tests walk each settle path through its real route, because the property that matters is
# not that a helper works: it is that no way of ending a job leaves it unmeasured.
# ----------------------------------------------------------------------------------------------


def timing_of(store: ProjectStore, project_id: str, job_id: str) -> RenderJob:
    return next(job for job in store.get(project_id).jobs if job.id == job_id)


def test_a_completed_render_records_comfyuis_own_execution_time(tmp_path: Path):
    """The measurement preferred wherever it exists: `execution_start` to `execution_success`
    out of `/history`, which is the render with the queue wait already excluded."""
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Timed"))
    project.shots = [
        Shot(id="shot_t", start=0, duration=5, prompt="A singer turns", mode="text", status="ready")
    ]
    store.save(project)
    job_id = submit_h3(client, project.id, "shot_t").json()["id"]

    async def timed_history(prompt_id):
        return type(
            "History",
            (),
            {
                "prompt_id": prompt_id,
                "status": "complete",
                "outputs": [
                    {
                        "subfolder": f"music-video-producer/{project.id}/shots",
                        "filename": "shot_t-h3_00001.mp4",
                    }
                ],
                "error": "",
                "elapsed_seconds": 378.0,
            },
        )()

    comfy.history = timed_history
    assert client.get(f"/api/projects/{project.id}/jobs/{job_id}").status_code == 200

    settled = timing_of(store, project.id, job_id)
    assert settled.status == "complete"
    assert settled.render_seconds == 378.0
    assert settled.render_seconds_source == "comfy"
    assert settled.updated_at > settled.created_at
    # And the line the Director reads is a render time, with the frames beside it.
    assert render_timing_summary(settled) == "rendered in 6m18s, 141 frames"


def test_every_h3_submission_records_the_frames_its_graph_was_built_for(tmp_path: Path):
    """A duration with no frame count beside it is uninterpretable -- 6m18s is unremarkable at
    141 frames and impossible at 277 -- and the count cannot be recovered later, because the
    window is edited after the render. So it is written at the one moment it is true."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Frames"))
    project.shots = [
        Shot(id="shot_a", start=0, duration=5.0, prompt="Wide", mode="text", status="ready"),
        Shot(id="shot_b", start=6, duration=8.75, prompt="Hold", mode="text", status="ready"),
    ]
    store.save(project)

    first = submit_h3(client, project.id, "shot_a").json()["id"]
    second = submit_h3(client, project.id, "shot_b").json()["id"]

    # `over_render_frames` on each window: the same number all three H3 branches build for.
    assert timing_of(store, project.id, first).render_frames == over_render_frames(5.0)
    assert timing_of(store, project.id, second).render_frames == over_render_frames(8.75)
    assert timing_of(store, project.id, first).render_frames == 141
    assert timing_of(store, project.id, second).render_frames == 226

    # The window then moves, as windows do. The recorded count describes the render that
    # happened, not the window as it stands now -- which is the whole reason it is persisted.
    moved = store.get(project.id)
    moved.shots[1].duration = 4.0
    store.save(moved)
    assert timing_of(store, project.id, second).render_frames == 226


def test_cancelling_a_job_stamps_it_and_never_calls_the_result_a_render_time(tmp_path: Path):
    """A cancel is a settle. What it can honestly record is how long the record stood open --
    some unknown part of which was rendering -- so the surfaced line says exactly that."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Cancel timing"))
    project.shots = [Shot(id="shot_c", start=0, duration=4, prompt="Wide", status="queued")]
    project.jobs = [
        RenderJob(id="job_c", kind="h3", target_id="shot_c", status="queued", prompt_id="p-c")
    ]
    project.jobs[0].created_at = project.jobs[0].created_at - timedelta(seconds=900)
    store.save(project)

    assert client.delete(f"/api/projects/{project.id}/jobs/job_c").status_code == 200

    settled = timing_of(store, project.id, "job_c")
    assert settled.status == "cancelled"
    assert settled.render_seconds == pytest.approx(900, abs=10)
    assert settled.render_seconds_source == "record"
    assert settled.updated_at > settled.created_at
    line = render_timing_summary(settled)
    assert "not render time" in line and "rendered" not in line


def test_a_submission_comfyui_refused_settles_a_stamped_record(tmp_path: Path):
    """The record-first ordering's own settle path. Nothing rendered, so nothing may read as a
    render -- but the record is still closed, and a closed record carries when it closed."""
    client, store, comfy = make_client(tmp_path)
    project = h3_ready_project(store, "Refused submission")
    comfy.submit_error = True

    assert generate_h3(client, project).status_code == 502

    settled = store.get(project.id).jobs[0]
    assert settled.status == "error"
    assert settled.error == JOB_NEVER_SUBMITTED
    assert settled.updated_at > settled.created_at
    assert settled.render_seconds_source == "record"


def test_a_prompt_that_died_with_the_queue_settles_a_stamped_record(tmp_path: Path):
    """The `missing_ticks` death. There is no ComfyUI measurement to prefer here by
    definition -- the branch is reached *because* ComfyUI has no record of the prompt."""
    client, store, comfy = make_client(tmp_path)
    project_id, job = flux_job(client, store, comfy, "Lost with the queue")

    async def unknown_history(prompt_id):
        return type(
            "History",
            (),
            {"prompt_id": prompt_id, "status": "queued", "outputs": [], "error": "", "known": False},
        )()

    comfy.history = unknown_history
    for _ in range(MISSING_TICKS_LIMIT):
        assert client.get(f"/api/projects/{project_id}/render-status").status_code == 200

    settled = timing_of(store, project_id, job["id"])
    assert settled.status == "error"
    assert settled.error == JOB_LOST_WITH_QUEUE
    assert settled.updated_at > settled.created_at
    assert settled.render_seconds_source == "record"


def test_a_superseded_record_is_stamped_when_the_newer_render_takes_its_target(tmp_path: Path):
    client, store, _comfy = make_client(tmp_path)
    project = h3_ready_project(store, "Superseded timing")
    assert generate_h3(client, project).status_code == 202
    # The status walk-back a whole-manifest write can produce, which is the state supersession
    # exists for: the shot reads `ready` again while its first job is still open.
    stale = store.get(project.id)
    stale.shots[0].status = "ready"
    stale.jobs[0].created_at = stale.jobs[0].created_at - timedelta(seconds=300)
    store.save(stale)

    assert generate_h3(client, store.get(project.id)).status_code == 202

    older = store.get(project.id).jobs[0]
    assert older.status == "cancelled"
    assert older.superseded_by
    assert older.updated_at > older.created_at
    assert older.render_seconds == pytest.approx(300, abs=10)
    assert older.render_seconds_source == "record"


def test_a_job_record_that_predates_the_instrumentation_round_trips_unchanged(tmp_path: Path):
    """Old manifests load unchanged, and -- the half that matters -- a settled job written
    before 2026-08-21 is never retroactively given a duration it was never measured for."""
    store = ProjectStore(tmp_path)
    project = store.create(Project(name="Old manifest"))
    manifest = store.manifest_path(project.id)
    payload = json.loads(manifest.read_text(encoding="utf-8"))
    payload["jobs"] = [
        {
            "id": "job_ancient",
            "kind": "h3",
            "status": "complete",
            "prompt_id": "p-old",
            "target_id": "shot_old",
            "created_at": "2026-08-19T01:00:00+00:00",
            "updated_at": "2026-08-19T01:00:00+00:00",
        }
    ]
    manifest.write_text(json.dumps(payload, indent=2), encoding="utf-8")

    loaded = store.get(project.id)

    assert loaded.jobs[0].render_seconds == 0.0
    assert loaded.jobs[0].render_seconds_source == ""
    assert loaded.jobs[0].render_frames == 0
    assert loaded.jobs[0].updated_at == loaded.jobs[0].created_at
    assert render_timing_summary(loaded.jobs[0]) == ""
    # Saving it back adds the three keys and changes nothing else about the record.
    store.save(loaded)
    again = json.loads(manifest.read_text(encoding="utf-8"))["jobs"][0]
    assert again["render_seconds"] == 0.0
    assert again["render_seconds_source"] == ""
    assert again["render_frames"] == 0
    assert again["created_at"] == again["updated_at"] == "2026-08-19T01:00:00Z"


def test_an_ordinary_full_project_put_cannot_erase_a_recorded_render_timing(tmp_path: Path):
    """**The eighth time this hole has been found in this route.** Every timing field is
    defaulted, so a client written before they existed omits all three and they arrive as
    `0.0`/`""`/`0` -- and one ordinary save would blank every render cost in the project at
    once, which is the exact loss the instrumentation exists to prevent. A body that *invents*
    a duration is refused the same way: nothing but a settle may write a measurement.
    """
    client, store, comfy = make_client(tmp_path)
    project_id, _shot_id, job_id = rendered_shot(client, store, comfy, "Guarded timing")
    measured = timing_of(store, project_id, job_id)
    measured.render_seconds = 378.0
    measured.render_seconds_source = "comfy"
    measured.render_frames = 141
    stored = store.save(store.get(project_id).model_copy(update={"jobs": [measured]}))

    body = json.loads(stored.model_dump_json())
    # Exactly what a client written before these fields existed sends: the keys are simply
    # absent. Pydantic fills them from the defaults, which is where the erasure came from.
    for key in ("render_seconds", "render_seconds_source", "render_frames"):
        body["jobs"][0].pop(key)
    saved = client.put(f"/api/projects/{project_id}", json=body)

    assert saved.status_code == 200, saved.text
    kept = timing_of(store, project_id, job_id)
    assert (kept.render_seconds, kept.render_seconds_source, kept.render_frames) == (
        378.0,
        "comfy",
        141,
    )

    # And a body that claims its own numbers is ignored rather than believed.
    forged = json.loads(store.get(project_id).model_dump_json())
    forged["jobs"][0]["render_seconds"] = 7920.0
    forged["jobs"][0]["render_seconds_source"] = "comfy"
    forged["jobs"][0]["render_frames"] = 221
    forged["jobs"][0]["updated_at"] = "2030-01-01T00:00:00Z"
    assert client.put(f"/api/projects/{project_id}", json=forged).status_code == 200

    unmoved = timing_of(store, project_id, job_id)
    assert unmoved.render_seconds == 378.0
    assert unmoved.render_frames == 141
    assert unmoved.updated_at.year != 2030


def test_a_full_project_put_cannot_erase_a_job_record_by_leaving_it_out(tmp_path: Path):
    """The guard protected fields and left whole records open.

    Its loop read `project.jobs` -- the *body* -- so a job the body simply omits was invisible to
    it, and `Project.jobs` is defaulted. A `PUT` carrying nothing but `id`, `name` and
    `updated_at` therefore answered 200 and erased every job record in the project, timings
    included: the exact loss this instrumentation exists to prevent, arriving through the exact
    route that has caused it seven times before, and reachable by a body three keys long.

    No route in this application removes a job record. They are appended by the submission paths
    and settled in place, so the stored list is the authority and a body may only add to it.
    """
    client, store, comfy = make_client(tmp_path)
    project_id, _shot_id, job_id = rendered_shot(client, store, comfy, "Erasable")
    measured = timing_of(store, project_id, job_id)
    measured.render_seconds = 378.0
    measured.render_seconds_source = "comfy"
    measured.render_frames = 141
    stored = store.save(store.get(project_id).model_copy(update={"jobs": [measured]}))

    saved = client.put(
        f"/api/projects/{project_id}",
        json={
            "id": project_id,
            "name": stored.name,
            "updated_at": stored.updated_at.isoformat().replace("+00:00", "Z"),
        },
    )

    assert saved.status_code == 200, saved.text
    kept = timing_of(store, project_id, job_id)
    assert (kept.render_seconds, kept.render_seconds_source, kept.render_frames) == (
        378.0, "comfy", 141,
    )
    # The whole record, not only its measurement: the reply the browser adopts holds it too, so
    # the queue panel does not go empty on the save that was supposed to change a name.
    assert [job["id"] for job in saved.json()["jobs"]] == [job_id]


def test_a_job_the_store_never_saw_arrives_with_no_measurement_however_the_body_dresses_it(
    tmp_path: Path,
):
    """The sibling branch, and the worse one. A job the store does not hold used to keep its
    *client-supplied* timing -- there was nothing measured to protect, which is true of the
    record and false of the field. So a body could invent

        {"id": "job_forged", "render_seconds": 7920.0, "render_seconds_source": "comfy",
         "render_frames": 221}

    and the queue panel drew `2h12m · 221f`, with no `≤`, as a recorded measurement. That is the
    fabricated "221 frames = 2.2 hours" figure this whole change spent four sites retiring,
    re-injectable through the generic write. The precedents force the default instead --
    `stored_anchors.get(id, "")`, `stored_slots.get(id, 0)` -- and so does this now.
    """
    client, store, comfy = make_client(tmp_path)
    project_id, _shot_id, job_id = rendered_shot(client, store, comfy, "Forgeable")
    body = json.loads(store.get(project_id).model_dump_json())
    body["jobs"].append({
        "id": "job_forged",
        "kind": "h3",
        "status": "complete",
        "prompt_id": "pr-forged",
        "target_id": "shot_take",
        "render_seconds": 7920.0,
        "render_seconds_source": "comfy",
        "render_frames": 221,
        # And a look for an export nobody ran, on the same argument: `RenderJob.look` joined
        # this guard on 2026-08-25, and a record nobody composed carries no composition.
        "look": {
            "effects": ['shot_a=lut_look:{"interp":"tetrahedral","lut":"never-chosen"}'],
            "bindings": ["forged"],
            "transitions": ["forged"],
        },
        "created_at": "2026-08-22T01:00:00Z",
        "updated_at": "2026-08-22T03:12:00Z",
    })

    saved = client.put(f"/api/projects/{project_id}", json=body)

    assert saved.status_code == 200, saved.text
    forged = next(job for job in store.get(project_id).jobs if job.id == "job_forged")
    assert (forged.render_seconds, forged.render_seconds_source, forged.render_frames) == (
        0.0, "", 0,
    )
    assert (forged.look.effects, forged.look.bindings, forged.look.transitions) == ([], [], [])
    # `updated_at` equal to `created_at` is this record's documented way of saying "never
    # settled", which is the honest thing to say about a job nothing here ever measured.
    assert forged.updated_at == forged.created_at
    assert render_timing_summary(forged) == ""
    # The record itself still lands, and behind the one the store already held: the queue panel
    # reads this list as chronological, so submission order is preserved rather than body order.
    assert [job.id for job in store.get(project_id).jobs] == [job_id, "job_forged"]


# ---------------------------------------------------------------------------------------------
# Renaming an asset (2026-08-22).
#
# The Director's chosen fix for the name leak: 9-10 prompts per populate roll carried the literal
# internal label `HarderFaster · multiview`, and the ruling was to rename the asset rather than
# hide its name from the model — "the HarderFaster image is a picture of a Woman named Lucy".
#
# `consistency_prompt`'s sibling-write suite applied to `Asset.name`, plus the two things a
# rename has to be honest about: what it cannot break (citations) and what it does not touch
# (prose already written).
# ---------------------------------------------------------------------------------------------


def rename_asset(client, project_id: str, asset_id: str, name):
    return client.put(
        f"/api/projects/{project_id}/assets/{asset_id}/name", json={"name": name}
    )


def leaky_project(store) -> Project:
    """A character asset, its promoted multiview sheet, and shots whose prose spells the label."""
    project = store.create(Project(name="Harder Faster"))
    project.assets = [
        Asset(id="asset_source", name="HarderFaster", kind="character", path="media/l.png"),
        Asset(
            id="asset_sheet",
            name="HarderFaster · multiview",
            kind="character",
            source="krea-multiview",
            parent_id="asset_source",
            path="media/l-mv.png",
        ),
    ]
    project.shots = [
        Shot(
            id="shot_leak",
            start=0,
            duration=5,
            prompt="HarderFaster · multiview screams into the polished metal stand.",
            mode="references",
            citations=[AssetCitation(asset_id="asset_sheet", role="reference", order=0)],
        ),
        Shot(id="shot_clean", start=5, duration=5, prompt="A wide shot of the empty floor."),
    ]
    store.save(project)
    return project


def test_renaming_an_asset_replaces_the_whole_display_name(tmp_path: Path):
    """The ` · multiview` suffix is a derivation, not a decoration to be preserved.

    `generate_multiview` appends it when it mints the child; a rename that edited around it would
    leave the Director unable to remove the very label they are renaming to get rid of, which is
    the whole ask. The name that lands is exactly what was sent, trimmed.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)

    response = rename_asset(client, project.id, "asset_sheet", "  Lucy  ")
    assert response.status_code == 200, response.text
    body = response.json()
    assert body["name"] == "Lucy" and body["previous"] == "HarderFaster · multiview"
    saved = store.get(project.id)
    assert [asset.name for asset in saved.assets] == ["HarderFaster", "Lucy"]
    # Nothing else on the asset moved — the write is onto the stored Asset, so `path`, `source`
    # and `parent_id` cannot be defaulted away by an edit that was only ever about one string.
    sheet = saved.assets[1]
    assert (sheet.kind, sheet.source, sheet.parent_id, sheet.path) == (
        "character", "krea-multiview", "asset_source", "media/l-mv.png"
    )
    assert comfy.prompts == []


def test_a_rename_cannot_break_a_citation_and_does_not_rewrite_prose(tmp_path: Path):
    """The two halves the response has to say out loud.

    Citations resolve by id, so no shot can lose its reference to a rename. Prose already written
    keeps the old spelling, because those are words a person or a model wrote and no route edits
    them on a rename's behalf — and a Director not told that will read the first prompt they open
    as evidence the rename failed.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)

    body = rename_asset(client, project.id, "asset_sheet", "Lucy").json()
    saved = store.get(project.id)

    assert [
        (citation.asset_id, citation.role) for citation in saved.shots[0].citations
    ] == [("asset_sheet", "reference")]
    assert saved.shots[0].asset_ids == ["asset_sheet"]
    assert saved.shots[0].prompt.startswith("HarderFaster · multiview screams")
    assert body["prompts"] == 1
    assert "still spell HarderFaster · multiview" in body["message"]
    assert "no shot lost its reference" in body["message"]
    assert comfy.prompts == []


def test_a_rename_says_that_it_did_not_reach_the_children_derived_from_the_asset(
    tmp_path: Path,
):
    """The consequence the response enumerated three of and missed the fourth.

    `generate_multiview` composes the child's name once, at the moment it mints it, and stores
    the string — so renaming the parent leaves the child spelling the old name. The measured
    prose leak was a *child*, and the Director's fix worked only because they renamed the child
    directly; the same gesture on the parent would have looked like it worked and not have.

    Reported rather than propagated: a child's name is editorial the moment it exists, this
    route treats a display name as the Director's to set, and edits chain — so a propagating
    rename would walk an unbounded tree overwriting names somebody may have chosen. The count
    is what makes "rename the child too" an instruction rather than a guess.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)

    body = rename_asset(client, project.id, "asset_source", "Lucy").json()

    # The child is untouched on disk, which is the behaviour — the sentence is the fix.
    saved = store.get(project.id)
    assert [asset.name for asset in saved.assets] == ["Lucy", "HarderFaster · multiview"]
    assert body["children"] == 1 and body["children_stale"] == 1
    assert "1 derived asset(s) keep their own names" in body["message"]
    assert "1 still spell HarderFaster." in body["message"]
    assert "rename each child on this same route" in body["message"]

    # Renaming the child itself has nothing below it, so the sentence is absent rather than
    # printed with a zero — a rename of a leaf must not read like it left work behind.
    child = rename_asset(client, project.id, "asset_sheet", "Lucy sheet").json()
    assert child["children"] == 0 and child["children_stale"] == 0
    assert "derived asset(s)" not in child["message"]
    assert comfy.prompts == []


def test_a_rename_under_the_scan_floor_says_the_prose_fallback_stopped_matching(
    tmp_path: Path,
):
    """`NAME_SCAN_MIN_LENGTH` is a silent cliff a rename can walk a name over.

    `assets_for_proposal` cites what a shot declared (by id or exact name, exact at any length)
    and then, as a fallback, whether the shot's prose contains the display name. That fallback
    is a plain substring test, so it is fenced below four characters. Renaming to `Ora` ends the
    prose half for this picture and nothing breaks — citations resolve by id — which is exactly
    why nobody would notice.
    """
    from music_video_producer.models import NAME_SCAN_MIN_LENGTH

    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)

    body = rename_asset(client, project.id, "asset_source", "Ora").json()

    assert body["scannable"] is False
    assert body["prose_matches"] == 0
    assert f"under the {NAME_SCAN_MIN_LENGTH}-character floor" in body["message"]
    assert "Ora is 3 character(s)" in body["message"]
    # The half that must be said in the same breath, or the sentence reads as a broken rename.
    assert "match by id or exact name, at any length" in body["message"]

    # A name at the floor says nothing at all: the ordinary case is silent.
    quiet = rename_asset(client, project.id, "asset_source", "Orav").json()
    assert quiet["scannable"] is True
    assert "character floor" not in quiet["message"]
    assert comfy.prompts == []


def test_a_rename_onto_an_ordinary_word_counts_the_prose_it_would_start_matching(
    tmp_path: Path,
):
    """The other direction over the same fence, and the one with no floor to catch it.

    `Rain` is four characters, so the scan trusts it — and it is inside "grain" and "training".
    Counted against this plan's own prose rather than a dictionary: evidence from the material
    at hand. Shots that already cite the asset are excluded, because those cite it *declared*
    and the prose fallback never runs for them.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)

    # `shot_clean` reads "A wide shot of the empty floor." and cites nothing.
    body = rename_asset(client, project.id, "asset_source", "Wide").json()
    assert body["scannable"] is True
    assert body["prose_matches"] == 1
    assert "1 shot prompt(s) in this plan already contain Wide" in body["message"]
    assert "plain substring test" in body["message"]

    # `shot_leak` reads "... into the polished metal stand." *and* cites the sheet, so a sheet
    # renamed to `Stand` over-matches nothing: the declared citation already owns that shot.
    quiet = rename_asset(client, project.id, "asset_sheet", "Stand").json()
    assert quiet["scannable"] is True
    assert quiet["prose_matches"] == 0
    assert "already contain" not in quiet["message"]
    assert comfy.prompts == []


def test_an_asset_is_renamed_by_one_route_and_nothing_else(tmp_path: Path):
    """`consistency_prompt`'s sibling-write suite, for the field that is **not** defaulted.

    A different hazard from the anchor's and worse in one direction: `name` is required, so no
    client omits it — every client sends back whatever name it was holding, and a browser tab
    left open across a rename reasserts the old one on its next ordinary save. That is a silent
    undo of a decision the Director made on the route that makes it, and the generic full-project
    `PUT` has been this hole seven times for other fields.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)
    assert rename_asset(client, project.id, "asset_sheet", "Lucy").status_code == 200

    # The stale-tab save: a body still carrying the old name must not put it back.
    body = client.get(f"/api/projects/{project.id}").json()
    for asset in body["assets"]:
        if asset["id"] == "asset_sheet":
            asset["name"] = "HarderFaster · multiview"
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    assert store.get(project.id).assets[1].name == "Lucy", "an ordinary save undid the rename"

    # And in the other direction: an ordinary save cannot rename an asset either.
    body = client.get(f"/api/projects/{project.id}").json()
    body["assets"][0]["name"] = "Somebody Else"
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    assert store.get(project.id).assets[0].name == "HarderFaster"

    # An asset the stored project does not hold keeps the body's name, and that is where this
    # parts from the anchor's `.get(id, "")` rule: there is no stored name to adopt, and blanking
    # it would produce a library row nobody can read.
    body = client.get(f"/api/projects/{project.id}").json()
    body["assets"].append(
        {"id": "asset_new", "name": "Newcomer", "kind": "prop", "path": "media/n.png"}
    )
    assert client.put(f"/api/projects/{project.id}", json=body).status_code == 200
    introduced = next(a for a in store.get(project.id).assets if a.id == "asset_new")
    assert introduced.name == "Newcomer"
    assert comfy.prompts == []


def test_the_rename_routes_refusals_match_its_siblings(tmp_path: Path):
    """404, empty and too-long — each before anything is assigned, so a refused rename leaves the
    asset exactly as it was. `replace_consistency_prompt`'s and `replace_character_slot`'s shape,
    with the one deliberate difference: a name cannot be cleared."""
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)

    missing = rename_asset(client, project.id, "asset_nope", "Lucy")
    assert missing.status_code == 404 and missing.json()["detail"] == "Asset not found"

    for blank in ("", "   "):
        empty = rename_asset(client, project.id, "asset_sheet", blank)
        assert empty.status_code == 422
        assert empty.json()["detail"] == ASSET_NAME_EMPTY

    long = rename_asset(client, project.id, "asset_sheet", "L" * (ASSET_NAME_LIMIT + 1))
    assert long.status_code == 422
    assert long.json()["detail"] == ASSET_NAME_TOO_LONG.format(
        name="HarderFaster · multiview", length=ASSET_NAME_LIMIT + 1, limit=ASSET_NAME_LIMIT
    )
    # Measured after trimming, exactly as the anchor's bound is.
    assert rename_asset(
        client, project.id, "asset_sheet", "  " + "L" * ASSET_NAME_LIMIT + "  "
    ).status_code == 200

    # A body with no `name` at all is refused by the schema, `SongVocalTypeRequest`'s rule: the
    # omitted value would be `""`, and `""` is not a name a caller could have meant.
    assert client.put(
        f"/api/projects/{project.id}/assets/asset_sheet/name", json={}
    ).status_code == 422

    # Nothing survived any of the refusals except the one 200.
    assert store.get(project.id).assets[1].name == "L" * ASSET_NAME_LIMIT
    assert store.get(project.id).assets[0].name == "HarderFaster"
    assert comfy.prompts == []


def test_a_rename_re_derives_the_reference_maps_the_name_is_written_into(tmp_path: Path):
    """`replace_consistency_prompt`'s line and its argument: the name is **in** the map.

    `timeline.anchored_label` composes it into every tag line, so a rename changes what every
    citing shot's map says about this picture. Free to re-derive for the deterministic song-audio
    prose shots, recorded as stale for the rest — and the count is reported, because "8 maps were
    rewritten" is a thing the Director is entitled to know a rename did.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)
    project.song = Song(title="Harder", source="imported", path="media/h.mp3", duration=60.0)
    shot = project.shots[0]
    shot.use_song_audio = True
    shot.h3_prompt = song_audio_prose(project, shot)
    shot.h3_prompt_map = reference_map_sentence(reference_map_tag_lines(project, shot))
    store.save(project)
    assert "HarderFaster · multiview" in store.get(project.id).shots[0].h3_prompt_map

    body = rename_asset(client, project.id, "asset_sheet", "Lucy").json()
    refreshed = store.get(project.id).shots[0]
    assert "Lucy" in refreshed.h3_prompt_map
    assert "· multiview" not in refreshed.h3_prompt_map
    assert body["maps"] == 1 and "reference map(s) were re-derived" in body["message"]
    assert comfy.prompts == []


def test_every_write_path_for_an_assets_name_is_enumerated():
    """The enumeration the sibling-write rule asks for, grepped rather than argued.

    `Asset.name` has five *creation* sites and exactly one *edit* site. The failure this pins is
    the one this repository keeps meeting from the other end: a second writer added later by
    someone who did not read the route's docstring, or the generic `PUT` quietly becoming one
    again. Creation is listed by its own construction (`Asset(`), so a sixth creation route also
    fails here and has to be named deliberately.
    """
    source = Path("src/music_video_producer/app.py").read_text(encoding="utf-8")

    # Exactly two assignments of the attribute anywhere: the rename route's own write, and the
    # generic full-project PUT re-adopting the stored value so it can never write one. A third is
    # a second door, which is the failure this pins.
    assert source.count("asset.name = ") == 2
    assert source.count("asset.name = name\n") == 1
    assert source.count("asset.name = stored_names.get(asset.id, asset.name)") == 1
    assert source.count("stored_names = {asset.id: asset.name for asset in current.assets}") == 1

    # The creation sites, named. Two of them derive a child's name from its source's, which is
    # why a rename has to replace the whole string rather than edit around a suffix.
    assert source.count("Asset(") == 5
    assert source.count('name=f"{source.name} · multiview"') == 1
    assert source.count('name=f"{source.name} · edit"') == 1
    assert source.count("name=name.strip() or target.stem") == 1  # upload
    assert source.count("name=request.name,") == 1  # generate/flux
    assert source.count("name=proposal.name,") == 1  # assets/fill

    # No model can reach the field: it is not on any tool schema, and the only routes that write
    # it are the five creations and the one rename above.
    assert '"name"' not in Path(
        "src/music_video_producer/director.py"
    ).read_text(encoding="utf-8").split("def _tool_schemas")[-1].split("def ")[0]


def test_a_manifest_written_before_the_rename_route_loads_unchanged(tmp_path: Path):
    """No field was added, so nothing on disk changes shape and no old manifest needs migrating.

    Pinned rather than argued: the rename writes an existing required field, and a project saved
    before the route existed reads back with the names it had, byte for byte.
    """
    client, store, comfy = make_client(tmp_path)
    project = leaky_project(store)
    before = (tmp_path / "projects" / project.id / "project.json").read_text(encoding="utf-8")

    reloaded = client.get(f"/api/projects/{project.id}").json()
    assert [asset["name"] for asset in reloaded["assets"]] == [
        "HarderFaster", "HarderFaster · multiview"
    ]
    assert set(json.loads(before)["assets"][0]) <= set(Asset.model_fields)
    # And the round trip through the route leaves every other asset alone.
    assert rename_asset(client, project.id, "asset_sheet", "Lucy").status_code == 200
    after = json.loads(
        (tmp_path / "projects" / project.id / "project.json").read_text(encoding="utf-8")
    )
    assert set(after) == set(json.loads(before))
    assert after["assets"][0] == json.loads(before)["assets"][0]
    assert comfy.prompts == []


def _fields_the_settle_path_writes() -> set[str]:
    """Every attribute `batch.stamp_job_settled` assigns onto the job it settles, from source.

    Read off the *writer* rather than off the shape of a field's name. Every settle path in this
    application funnels through that one function -- which is the reason it exists as a function
    -- so what it stamps is, by construction, what this application measures.
    """
    tree = ast.parse(
        Path("src/music_video_producer/batch.py").read_text(encoding="utf-8")
    )
    settle = next(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.FunctionDef) and node.name == "stamp_job_settled"
    )
    return {
        target.attr
        for node in ast.walk(settle)
        if isinstance(node, ast.Assign)
        for target in node.targets
        if isinstance(target, ast.Attribute)
        and isinstance(target.value, ast.Name)
        and target.value.id == "job"
    }


def test_every_field_a_settle_path_measures_is_covered_by_the_routes_guard():
    """The drift this pins: a field this application measures and `JOB_RECORDED_FIELDS` does not
    name is silently writable by any client, which is how this route has been the hole seven
    times before.

    Structural, because the version that came before it was not: it derived "measured" as
    `name.startswith("render_") or name == "updated_at"`, which a future `gpu_seconds` or
    `timing_source` satisfies while being wide open -- the same name-shaped hole one level up
    from the one it was written to close. This reads the settle path's own assignments instead,
    so a field the application starts measuring and the guard does not adopt fails here.
    """
    written = _fields_the_settle_path_writes()

    # The harness reads the real function rather than an empty set that would pass vacuously.
    assert {"render_seconds", "render_seconds_source", "updated_at"} <= written
    assert written <= set(JOB_RECORDED_FIELDS)
    # Three fields no settle path writes, each recorded at the single moment it is true, and all
    # for the same reason: what they describe is edited or re-chosen afterwards, so re-deriving
    # any of them later describes a render that never happened. `render_frames` — `Shot.duration`
    # moves under an edge drag. `sampling_bundle` — `Project.sampling_profile` is a standing
    # choice the Director changes between renders, which is exactly why a project's takes became
    # a mixture. `look` — written by the assemble route when it creates the job record, from the
    # composition it is about to run, and `Shot.effects` is edited the moment the export is over.
    # They are named in the guard for the same reason as the rest, and the test below proves the
    # naming has teeth rather than reciting it.
    assert set(JOB_RECORDED_FIELDS) - written == {
        "render_frames",
        "sampling_bundle",
        "look",
    }


def test_the_guard_has_teeth_for_every_field_it_names(tmp_path: Path):
    """The list, executed. Every field in `JOB_RECORDED_FIELDS` is forged in a whole-project body
    and every one of them must come back unmoved -- so the tuple is a set of enforced refusals
    rather than a set of names a test recites back to itself."""
    client, store, comfy = make_client(tmp_path)
    project_id, _shot_id, job_id = rendered_shot(client, store, comfy, "Teeth")

    for name in JOB_RECORDED_FIELDS:
        before = timing_of(store, project_id, job_id)
        held = getattr(before, name)
        forged = {
            "render_seconds": 7920.0,
            "render_seconds_source": "comfy",
            "render_frames": 221,
            # The forgery this field makes possible, and the reason it is guarded in both
            # directions: a body claiming a four-step turbo render for a job that sampled twenty
            # is provenance for a render nobody performed, dressed as the fix for exactly that.
            "sampling_bundle": {
                "name": "turbo", "steps": 4, "sampler": "euler", "scheduler": "beta",
                "lora": "forged.safetensors", "lora_strength": 0.7,
            },
            # A look for an export nobody graded, which is the other direction this field fails
            # in: `Shot.effects` is already server-owned on this route, so an unguarded `look`
            # would be the way to claim a grade the manifest itself refuses to hold.
            "look": {
                "effects": ["shot_a=lut_look:{\"interp\":\"tetrahedral\",\"lut\":\"forged\"}"],
                "bindings": [],
                "transitions": [],
            },
            "updated_at": "2030-01-01T00:00:00Z",
        }[name]
        body = json.loads(store.get(project_id).model_dump_json())
        body["jobs"][0][name] = forged
        assert body["jobs"][0][name] != json.loads(before.model_dump_json())[name], name

        assert client.put(f"/api/projects/{project_id}", json=body).status_code == 200, name

        assert getattr(timing_of(store, project_id, job_id), name) == held, name



def _routes_whose_body_can_carry_a_job(app) -> dict[str, str]:
    """Every route whose request body can reach a `RenderJob`, and the field path that gets there.

    Read off the live routing table and pydantic's own field annotations rather than off source
    text, so a route added tomorrow with a job-bearing body appears here by existing.
    """
    from fastapi.routing import APIRoute
    from pydantic import BaseModel

    def trail(annotation, seen, so_far):
        for candidate in (annotation, *get_args(annotation)):
            if candidate is RenderJob:
                return so_far
            if (
                isinstance(candidate, type)
                and issubclass(candidate, BaseModel)
                and candidate not in seen
            ):
                seen.add(candidate)
                for name, field in candidate.model_fields.items():
                    found = trail(field.annotation, seen, [*so_far, f"{candidate.__name__}.{name}"])
                    if found:
                        return found
        return None

    found = {}
    for route in app.routes:
        if not isinstance(route, APIRoute) or route.body_field is None:
            continue
        path = trail(route.body_field.field_info.annotation, set(), [])
        if path is not None:
            found[f"{min(route.methods)} {route.path}"] = " -> ".join(path)
    return found


def test_every_route_a_job_record_can_arrive_on_is_enumerated(tmp_path: Path):
    """The twelfth instance of the `replace_project` guard hole was a spec that named one of the
    two routes a `Shot` can arrive on, and the implementer had to find the other. So the routes a
    **job** can arrive on are enumerated here rather than assumed, from the routing table itself.

    There are six, not one, and the shape of the sixth is worth stating: five of them are
    report-then-confirm routes whose request body *is* the response model they echo, and that
    response model carries the saved `Project` — jobs and all. `PLAN_DIGEST_EXCLUDE` leaves
    `project` out of the plan digest, so a client can put anything it likes in there and the
    fingerprint still matches. None of those five ever reads it: each writes onto the project it
    read from the store and saves that. `test_a_job_record_forged_inside_a_confirmed_plan_is_
    never_written` is that claim executed rather than argued.

    The one route that does bind a client's job records is the generic whole-project `PUT`, and
    `_adopt_job_measurements` is what stands in front of it.

    A new entry here is not a failure to suppress. It is a route that has to answer the question
    this list exists to ask: can a client's job record reach the store through it?
    """
    client, _store, _comfy = make_client(tmp_path)

    assert _routes_whose_body_can_carry_a_job(client.app) == {
        "PUT /api/projects/{project_id}": "Project.jobs",
        "POST /api/projects/{project_id}/sections/fill-looks":
            "SectionLooksRequest.plan -> SectionLooksResponse.project -> Project.jobs",
        "POST /api/projects/{project_id}/timeline/lay-out":
            "LayOutRequest.plan -> LayOutResponse.project -> Project.jobs",
        "POST /api/projects/{project_id}/timeline/line-up":
            "LineUpRequest.plan -> LayOutResponse.project -> Project.jobs",
        "POST /api/projects/{project_id}/timeline/fill-in":
            "FillInRequest.plan -> LineUpResponse.project -> Project.jobs",
        "POST /api/projects/{project_id}/timeline/clean-prompts":
            "CleanPromptsRequest.plan -> CleanPromptsResponse.project -> Project.jobs",
    }


def test_a_job_record_forged_inside_a_confirmed_plan_is_never_written(tmp_path: Path):
    """The five plan-echo routes, proved inert rather than argued inert.

    A confirm's body is the report it echoes, and that report model carries a whole `Project`.
    `PLAN_DIGEST_EXCLUDE` leaves `project` out of the digest deliberately — it is one of the two
    fields a confirm is *allowed* to differ on — so a forged project inside a plan does not break
    the fingerprint and reaches the route intact. The question is whether anything reads it.

    Driven through `sections/fill-looks`, whose confirm asks no model at all: the plan is built by
    hand with the route's own `plan_fingerprint`, a forged job record with a forged `look` and a
    forged render cost is planted inside `plan.project`, and the confirm is sent. It must do the
    work it was asked to do — the section look really is written, which is what makes this a test
    of a route that writes rather than of a refusal — and the job record must be untouched.
    """
    from music_video_producer.app import SectionLooksResponse, plan_fingerprint
    from music_video_producer.models import ExportLook, SongSection

    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Plan echo"))
    project.sections = [SongSection(id="sec_1", label="Chorus", start=0.0, duration=8.0)]
    project.jobs = [
        RenderJob(
            id="job_export",
            kind="post",
            status="complete",
            target_id="assembly",
            look=ExportLook(effects=['shot_a=punch_in:{"zoom":1.25}']),
            render_seconds=12.5,
            render_seconds_source="record",
        )
    ]
    project = store.save(project)

    plan = {
        "applied": False,
        "filled": 1,
        "skipped": 0,
        "sections": [
            {
                "section_id": "sec_1",
                "label": "Chorus",
                "start": 0.0,
                "filled": True,
                "prompt": "Sodium amber, hard backlight.",
                "previous": "",
                "reason": "",
            }
        ],
        "message": "1 filled, 0 left alone",
        "stray": 0,
        "updated_at": project.updated_at.isoformat().replace("+00:00", "Z"),
    }
    plan["plan_id"] = plan_fingerprint(
        project, SectionLooksResponse.model_validate({**plan, "plan_id": ""})
    )
    # The forgery, in the one field the digest does not cover.
    forged = json.loads(project.model_dump_json())
    forged["jobs"][0]["look"] = {
        "effects": ['shot_z=lut_look:{"interp":"tetrahedral","lut":"never-chosen"}'],
        "bindings": ["forged"],
        "transitions": ["forged"],
    }
    forged["jobs"][0]["render_seconds"] = 7920.0
    plan["project"] = forged

    applied = client.post(
        f"/api/projects/{project.id}/sections/fill-looks",
        json={"confirm_apply": True, "plan": plan},
    )

    assert applied.status_code == 200, applied.text
    saved = store.get(project.id)
    # The route did its job, so this is a test of a write and not of a refusal.
    assert applied.json()["applied"] is True
    assert saved.sections[0].prompt == "Sodium amber, hard backlight."
    # And the job record it was handed went nowhere.
    assert saved.jobs[0].look.effects == ['shot_a=punch_in:{"zoom":1.25}']
    assert saved.jobs[0].look.bindings == [] and saved.jobs[0].look.transitions == []
    assert saved.jobs[0].render_seconds == 12.5
    assert comfy.prompts == []


# ----------------------------------------------------------------------------------------------
# Cancel every open render (the Director's report, 2026-08-23). The per-job `×` works; twenty-six
# of it is a chore, and the chore is what sent them to ComfyUI's own UI to clear the queue.
# ----------------------------------------------------------------------------------------------


def cancellable_project(store, *, jobs, shots=()):
    """A project with an open queue, for the whole-queue cancel."""
    project = store.create(Project(name="Cancel all"))
    project.shots = list(shots)
    project.jobs = list(jobs)
    return store.save(project)


def test_cancelling_the_whole_queue_refuses_until_the_count_has_been_shown(tmp_path: Path):
    """The confirmation is server-enforced and it names the count, because that count is the
    whole of what makes the gesture judgeable: twenty-six renders stopped is not undoable, and a
    client that never showed the number must not be able to spend the decision by omission.

    409 rather than 422, matching `delete_project`: the request is well formed and the state is
    real, and what is missing is consent to something destructive.
    """
    client, store, comfy = make_client(tmp_path)
    project = cancellable_project(store, jobs=[
        RenderJob(id="job_1", kind="h3", target_id="shot_a", status="queued", prompt_id="p1"),
        RenderJob(id="job_2", kind="h3", target_id="shot_b", status="running", prompt_id="p2"),
        RenderJob(id="job_3", kind="h3", target_id="shot_c", status="complete", prompt_id="p3"),
    ])

    refused = client.delete(f"/api/projects/{project.id}/jobs")

    assert refused.status_code == 409
    detail = refused.json()["detail"]
    # The two open ones, not the settled one, and the number is in the sentence the Director reads.
    assert "2 open render(s)" in detail
    assert "not just the newest batch" in detail
    assert "confirm_cancel=true" in detail
    # And nothing was touched: no ComfyUI call, no record moved.
    assert comfy.cancelled == []
    assert [job.status for job in store.get(project.id).jobs] == ["queued", "running", "complete"]


def test_cancelling_the_whole_queue_settles_every_open_job_and_releases_their_shots(
    tmp_path: Path,
):
    """One click for the whole queue, and every job settled by `cancel_job` itself.

    The scope is every open ComfyUI render in the project rather than one batch, which is what
    makes it a replacement for the trip to ComfyUI: `job_lone` belongs to no batch at all and
    would be unreachable from a batch-scoped cancel, and `job_ltx` is a different kind entirely.
    A settled job is left exactly as it was, and so is the local export -- `reconcilable_jobs`
    skips an empty `prompt_id`, and nothing here could stop a running ffmpeg anyway.
    """
    client, store, comfy = make_client(tmp_path)
    project = cancellable_project(
        store,
        shots=[
            Shot(id="shot_a", start=0, duration=4, prompt="Wide", status="queued"),
            Shot(id="shot_b", start=4, duration=4, prompt="Crane", status="running",
                 latest_output="takes/kept.mp4"),
            Shot(id="shot_c", start=8, duration=4, prompt="Push", status="complete",
                 latest_output="takes/done.mp4"),
        ],
        jobs=[
            RenderJob(id="job_batch", kind="h3", batch_id="batch_1", target_id="shot_a",
                      status="queued", prompt_id="p1"),
            RenderJob(id="job_retake", kind="h3", batch_id="batch_1", target_id="shot_b",
                      status="running", prompt_id="p2"),
            RenderJob(id="job_done", kind="h3", batch_id="batch_1", target_id="shot_c",
                      status="complete", prompt_id="p3"),
            RenderJob(id="job_lone", kind="music", target_id="song", status="queued",
                      prompt_id="p4"),
            RenderJob(id="job_export", kind="post", target_id="", status="running",
                      prompt_id=""),
        ],
    )

    report = client.delete(f"/api/projects/{project.id}/jobs?confirm_cancel=true")

    assert report.status_code == 200, report.text
    body = report.json()
    assert [entry["job_id"] for entry in body["cancelled"]] == ["job_batch", "job_retake", "job_lone"]
    assert body["skipped"] == []
    # Under the names the queue panel already draws: a shot job by its shot label, everything
    # else by its kind and record id, because an asset or song id appears nowhere in the UI.
    assert [entry["label"] for entry in body["cancelled"]] == [
        "SHOT 01 (shot_a)", "SHOT 02 (shot_b)", "music job job_lone",
    ]
    # Each one dequeued on ComfyUI, in queue order, through the per-job route's own call.
    assert comfy.cancelled == ["p1", "p2", "p4"]

    saved = {job.id: job for job in store.get(project.id).jobs}
    assert saved["job_batch"].status == "cancelled"
    assert saved["job_retake"].status == "cancelled"
    assert saved["job_lone"].status == "cancelled"
    # One wording for one act, and it is `cancel_job`'s: this route writes no note of its own.
    # Pinned twice on purpose -- identity to the named constant proves the route did not invent a
    # second sentence, and the content pin is what makes the identity mean anything, since a
    # comparison against the constant the value came from can only ever pass.
    assert saved["job_batch"].error == CANCEL_JOB_NOTE
    assert "Cancelled by the Director before it finished." in saved["job_batch"].error
    assert "goes back to ready" in saved["job_batch"].error
    # Settled therefore stamped, by the per-job route's own `stamp_job_settled`.
    assert saved["job_batch"].render_seconds_source
    # The settled job and the local export are untouched.
    assert saved["job_done"].status == "complete"
    assert saved["job_export"].status == "running"

    shots = {shot.id: shot for shot in store.get(project.id).shots}
    # No take, so released back to ready: the next batch picks it up and the inspector offers
    # `Back to draft` rather than a flag over a take that does not exist.
    assert shots["shot_a"].status == "ready"
    # A take it already held, so settled as `error` and the take is still there.
    assert shots["shot_b"].status == "error"
    assert shots["shot_b"].latest_output == "takes/kept.mp4"
    # Never in flight, never touched.
    assert shots["shot_c"].status == "complete"


def test_cancelling_the_whole_queue_reports_a_job_that_settled_mid_loop_by_name(
    tmp_path: Path, monkeypatch
):
    """The race this route has to answer for: a poll tick settles a job between the click and
    the loop reaching it.

    The set is chosen once, from the read that produced the count the Director confirmed, but
    every iteration re-reads the manifest inside `cancel_job` -- so the settled one is found
    terminal there and refused with that route's own sentence. It lands in `skipped` by name and
    stops nothing else, which is `generate_batch`'s per-shot rule in the other direction.

    Injected **between iterations** -- immediately after the first cancellation's save and before
    the next one's read -- because that is where the window actually is. It is deliberately not
    injected inside a single `cancel_job`, which reads the whole manifest, awaits ComfyUI and then
    saves the whole manifest back: a write landing inside *that* span is lost to the save, which
    is a pre-existing hazard of the per-job route and not something this loop introduces or can
    fix from the outside.
    """
    client, store, comfy = make_client(tmp_path)
    project = cancellable_project(
        store,
        shots=[
            Shot(id="shot_a", start=0, duration=4, prompt="Wide", status="queued"),
            Shot(id="shot_b", start=4, duration=4, prompt="Crane", status="queued"),
            Shot(id="shot_c", start=8, duration=4, prompt="Push", status="queued"),
        ],
        jobs=[
            RenderJob(id="job_1", kind="h3", target_id="shot_a", status="queued", prompt_id="p1"),
            RenderJob(id="job_2", kind="h3", target_id="shot_b", status="queued", prompt_id="p2"),
            RenderJob(id="job_3", kind="h3", target_id="shot_c", status="queued", prompt_id="p3"),
        ],
    )

    settled_by_the_poll = []
    write = store.save

    def save_then_let_the_poll_land(saving):
        stored = write(saving)
        if settled_by_the_poll:
            return stored
        settled_by_the_poll.append("job_2")
        mid_flight = store.get(project.id)
        for job in mid_flight.jobs:
            if job.id == "job_2":
                job.status = "complete"
                job.output_files = ["takes/landed.mp4"]
        for shot in mid_flight.shots:
            if shot.id == "shot_b":
                shot.status = "complete"
                shot.latest_output = "takes/landed.mp4"
        write(mid_flight)
        return stored

    monkeypatch.setattr(store, "save", save_then_let_the_poll_land)

    report = client.delete(f"/api/projects/{project.id}/jobs?confirm_cancel=true")

    assert report.status_code == 200, report.text
    body = report.json()
    # The two that were still open were stopped; the one that finished in the meantime was not.
    assert [entry["job_id"] for entry in body["cancelled"]] == ["job_1", "job_3"]
    assert [entry["job_id"] for entry in body["skipped"]] == ["job_2"]
    assert body["skipped"][0]["label"] == "SHOT 02 (shot_b)"
    assert body["skipped"][0]["reason"] == CANCEL_JOB_SETTLED.format(status="complete")
    # And by content, so the identity above is not a constant compared with itself.
    assert "already complete" in body["skipped"][0]["reason"]
    assert "nothing running to cancel" in body["skipped"][0]["reason"]
    # Never re-cancelled on ComfyUI, and its take is untouched.
    assert comfy.cancelled == ["p1", "p3"]
    saved = store.get(project.id)
    landed = {job.id: job for job in saved.jobs}["job_2"]
    assert landed.status == "complete"
    assert landed.output_files == ["takes/landed.mp4"]
    shots = {shot.id: shot for shot in saved.shots}
    assert shots["shot_b"].status == "complete"
    assert shots["shot_b"].latest_output == "takes/landed.mp4"
    # And the two that were cancelled had produced nothing, so both are available again.
    assert shots["shot_a"].status == "ready"
    assert shots["shot_c"].status == "ready"


def test_cancelling_the_whole_queue_with_nothing_open_says_so_rather_than_asking(
    tmp_path: Path,
):
    """Empty is checked before the confirmation, deliberately: a click on a project with nothing
    running should be told that, not asked to confirm stopping zero renders. A dialog naming `0`
    is a dialog that teaches a Director to click through dialogs.

    A settled job and a local export are both "nothing open" here, for the two different reasons
    `reconcilable_jobs` already distinguishes.
    """
    client, store, comfy = make_client(tmp_path)
    project = cancellable_project(store, jobs=[
        RenderJob(id="job_done", kind="h3", target_id="shot_a", status="complete", prompt_id="p1"),
        RenderJob(id="job_export", kind="post", target_id="", status="running", prompt_id=""),
    ])

    for query in ("", "?confirm_cancel=true"):
        empty = client.delete(f"/api/projects/{project.id}/jobs{query}")
        assert empty.status_code == 422, query
        assert empty.json()["detail"] == CANCEL_ALL_NONE_OPEN, query
        # By content as well as by identity: the line above compares the route's answer with the
        # constant it was built from, which on its own can only pass.
        assert "nothing to cancel" in empty.json()["detail"], query
        assert "only a queued or running one can be stopped" in empty.json()["detail"], query
    assert comfy.cancelled == []


def test_the_whole_queue_cancel_is_the_per_job_route_and_not_a_second_settle_path():
    """Structural: this route writes no `status`, no `error` and no stamp of its own.

    Two spellings of one cancellation rule is the recurring defect this delegation exists to
    avoid, and it is invisible in behaviour until the two drift -- so it is asserted about the
    source. The only writes the route makes are its two report lists.
    """
    source = inspect.getsource(create_app)
    body = source.split("async def cancel_open_jobs", 1)[1].split("\n    @app.", 1)[0]
    assert "await cancel_job(project_id, job_id)" in body
    for spelling in (
        'job.status = "cancelled"',
        "job.error =",
        "stamp_job_settled",
        "shot.status =",
        "comfy.cancel",
        "store.save",
    ):
        assert spelling not in body, spelling


# ---------------------------------------------------------------------------
# Story 8.1 — the Song Envelope
#
# One measurement, taken when the song is stored, written beside the project rather than into
# the manifest, and believed only while a content fingerprint still matches the audio in front
# of it. Every row of the story's I/O matrix has a test below.
# ---------------------------------------------------------------------------


# The metronome this section measures is `test_audio.click_wav_bytes`, imported at the top of
# this file rather than spelled a second time here -- see the note on that import. `wav_bytes`
# above is still the silent one: silence is a legitimate measurement and therefore useless for
# telling "measured" from "not measured", which is why this section reaches for a track with
# beats in it.


def import_measured_song(client, project_id: str, *, bpm: float = 120.0, name: str = "beat.wav"):
    response = client.post(
        f"/api/projects/{project_id}/songs/upload",
        data={"title": "Measured", "duration": "4.0"},
        files={"file": (name, click_wav_bytes(bpm=bpm), "audio/wav")},
    )
    assert response.status_code == 200, response.text
    return response


@pytest.mark.parametrize(
    "damage",
    [
        pytest.param({"onsets": None}, id="a-null-array"),
        pytest.param({"beats": None}, id="the-other-null-array"),
        pytest.param({"onsets": "0.5"}, id="a-string-where-a-list-belongs"),
        pytest.param({"onsets": [None]}, id="a-null-inside-the-array"),
        pytest.param({"band_average": [[0.1]]}, id="nested-lists"),
    ],
)
def test_a_sidecar_the_reader_accepts_but_cannot_be_drawn_is_still_a_200(tmp_path: Path, damage):
    """A hand-edited sidecar makes the drawing short. It does not make the route an error.

    `read_song_envelope` checks that a key is *present*, never what is under it, and the currency
    verdict checks only `band_count`, `analysis_rate` and the length of `bands`. So a value a
    Director typed into the manifest reaches the wire intact. Declaring a response shape made that
    a `ResponseValidationError` — a 500 on a route whose own docstring says absence is a 200 and
    that none of these may become an error.

    The browser makes it worse rather than better: one read carries both halves now, and its catch
    is silent by design, so a 500 here loses the **gap** targets too -- and those never came from
    the envelope at all. The one-read consolidation is only safe if the envelope half failing
    cannot take the transcription half with it.
    """
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Damaged sidecar"))
    import_measured_song(client, project.id)

    sidecar = tmp_path / "projects" / project.id / "media" / "analysis" / "song-envelope.json"
    healthy = json.loads(sidecar.read_text(encoding="utf-8"))
    served_before = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert served_before["analysed"] is True, served_before

    sidecar.write_text(json.dumps({**healthy, **damage}), encoding="utf-8")
    response = client.get(f"/api/projects/{project.id}/timeline/snap-targets")

    assert response.status_code == 200, (
        "a sidecar the reader accepted became an error on the wire", response.text[:200]
    )
    body = response.json()
    # The half that has nothing to do with the envelope must survive it.
    assert body["gaps"] == served_before["gaps"]
    assert body["measured"] == served_before["measured"]
    # And the damaged key is simply absent, rather than served as zeros that look measured.
    damaged = set(damage)
    served = body["envelope"] or {}
    assert damaged.isdisjoint(served), (damaged, sorted(served))
    for intact in set(served_before["envelope"]) - damaged:
        assert served[intact] == served_before["envelope"][intact], intact


def test_importing_a_song_measures_it_into_a_sidecar_and_records_only_a_pointer(tmp_path: Path):
    """The first matrix row, and the shape of the whole story.

    The Song is stored, the envelope is written beside the project's media, and the *manifest*
    gains a pointer and nothing else. Asserted through a fresh `ProjectStore`, because the claim
    is about what survived to disk rather than about what one response object happened to hold.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Measured"))
    import_measured_song(client, project.id, bpm=120)

    saved = ProjectStore(tmp_path).get(project.id)
    analysis = saved.song.analysis
    assert analysis.path == "media/analysis/song-envelope.json"
    assert analysis.analysis_rate == 30.0
    assert analysis.band_count == 8
    assert analysis.bpm == pytest.approx(120, rel=0.05)
    assert analysis.song_fingerprint

    # The fingerprint is the one the shared function computes over the song's own bytes — not an
    # mtime, not a hash of the record, and not something only this route knows how to make.
    audio = store.project_dir(project.id) / saved.song.path
    assert analysis.song_fingerprint == song_fingerprint(audio)
    assert analysis.song_fingerprint.startswith(f"{audio.stat().st_size}-")

    # And the measurement itself is a file, carrying everything the story asks for.
    envelope = json.loads(
        (store.project_dir(project.id) / analysis.path).read_text(encoding="utf-8")
    )
    for key in ("rms", "peak", "flux", "bands", "band_average", "onsets", "beats", "bpm"):
        assert key in envelope, key
    assert len(envelope["bands"]) == envelope["band_count"] == 8
    assert len(envelope["band_average"]) == 8
    assert envelope["analysis_rate"] == 30.0


def test_the_drag_snap_targets_route_serves_both_halves_and_neither_is_required(tmp_path: Path):
    """Story 8.3's route: every second a dragged Shot edge may land on, computed by `timeline.py`
    so the drag and the batch "Snap cuts" button cannot hold two opinions about where a cut goes.

    Grown since, and `envelope` is the growth: the marks the waveform draws ride the same read, so
    the band and the drag cannot describe different states. Its own tests are below; what this one
    holds is that adding it did not move any of the six keys that were already here.

    **Absence of either half is a 200 carrying the half that exists.** Beats come from the
    analysis and gap targets from the transcription, and the two are independent: a song nobody
    transcribed keeps its beats, a song nobody analysed keeps its gap targets, and a project with
    no song at all answers two empty lists rather than an error. None of them may become a status
    code, because this is an assist on a gesture that has to keep working exactly as it does today
    whenever a measurement is missing.

    `measured` and `analysed` are reported rather than left to be inferred from an empty list:
    `vocal_gaps` distinguishes *unmeasured* from *measured and voiced throughout*, and this
    codebase never flattens the two together.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Targets"))

    # No song at all: two empty lists, a 200, and nothing that reads as a failure.
    bare = client.get(f"/api/projects/{project.id}/timeline/snap-targets")
    assert bare.status_code == 200, bare.text
    assert bare.json() == {
        "gaps": [], "beats": [], "measured": False, "analysed": False, "start": 0.0, "end": 0.0,
        # Absent, and absent as `null` rather than as an empty object: a measurement that found
        # nothing is a different sentence from a song nobody has measured, and this key answers
        # the second the same way `analysed` does, from the same expression.
        "envelope": None,
    }

    # Analysed but never transcribed: the beats are served, the gap half is honestly empty.
    import_measured_song(client, project.id, bpm=120)
    analysed = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert analysed["analysed"] is True
    assert analysed["beats"], "an analysed song served no beat targets"
    assert analysed["measured"] is False and analysed["gaps"] == []

    # The beats are the envelope's own, passed through rather than re-derived or thinned.
    saved = ProjectStore(tmp_path).get(project.id)
    envelope = json.loads(
        (store.project_dir(project.id) / saved.song.analysis.path).read_text(encoding="utf-8")
    )
    assert analysed["beats"] == envelope["beats"]
    # ...and the drawing half is there beside them, from the same read.
    assert analysed["envelope"]["beats"] == envelope["beats"]
    assert analysed["envelope"]["onsets"] == envelope["onsets"]

    # Now transcribed as well: the gap targets appear beside the beats, and are exactly the
    # seconds `timeline.py`'s own rule can move a boundary to.
    saved.song.lyric_words = [("la", 0.5, 1.0), ("la", 2.5, 3.0)]
    saved.song.vocal_spans = [(0.5, 1.0), (2.5, 3.0)]
    store.save(saved)
    both = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert both["measured"] is True
    assert both["beats"] == analysed["beats"]
    assert both["gaps"] == drag_snap_targets(saved.song).gaps
    assert both["gaps"], "a transcribed song served no gap targets"

    # And the only 404 is the project itself not existing -- absence is never one.
    assert client.get("/api/projects/project_missing/timeline/snap-targets").status_code == 404


def test_a_replaced_song_stops_serving_the_beats_it_was_measured_from(tmp_path: Path):
    """The read-time validity rule, carried into the drag.

    Nothing stores "this envelope is stale"; every read compares the song's current bytes against
    the fingerprint the measurement was taken from, and a mismatch means *absent*. A magnet still
    pulling a cut onto the beats of a track that has been replaced is the one state this feature
    must not be able to reach, and it is closed by the same rule `song/envelope` uses rather than
    by a second one written here.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Replaced"))
    import_measured_song(client, project.id, bpm=120)
    assert client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()["beats"]

    saved = ProjectStore(tmp_path).get(project.id)
    audio = store.project_dir(project.id) / saved.song.path
    audio.write_bytes(click_wav_bytes(bpm=90))

    after = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert after["analysed"] is False and after["beats"] == []
    # ...and the route still answers 200, so the drag simply has fewer targets rather than the
    # client having an error to draw.
    assert client.get(f"/api/projects/{project.id}/timeline/snap-targets").status_code == 200


def test_the_analysed_flag_never_disagrees_with_the_beats_it_describes(tmp_path: Path):
    """`analysed` exists so a reader of the wire can tell "no measurement" from "measured, and
    this song has no detectable beat". A flag true beside an empty list for the *wrong* reason
    answers neither question, so it is computed from the same expression the beats are rather than
    from a second check that can drift away from it.

    Three states, and every one of them driven through the real route:

    * a measurement with beats in it -- analysed, and the beats are the envelope's own;
    * a measurement of a song with no detectable beat -- **analysed**, with an empty list, which
      is the case the flag exists for. `audio.py` answers `0.0, []` for flat silence, so this is
      not hypothetical;
    * a sidecar that is not an envelope -- absent, and therefore not analysed and no beats.

    The fourth shape the flag used to be able to reach -- `analysed: true` with beats missing
    because the envelope was not a mapping -- is unreachable from here on purpose:
    `store.read_song_envelope` refuses anything that is not shaped like an envelope, so the route
    is never handed a half-read one. That is checked below rather than assumed.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Flagged"))
    import_measured_song(client, project.id, bpm=120)

    honest = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert honest["analysed"] is True and honest["beats"]

    saved = ProjectStore(tmp_path).get(project.id)
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    kept = json.loads(sidecar.read_text(encoding="utf-8"))

    # A song with no detectable beat is measured, not unmeasured. This is the row the flag exists
    # to distinguish and the one an empty list alone cannot say.
    sidecar.write_text(json.dumps({**kept, "beats": []}), encoding="utf-8")
    flat = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert flat["analysed"] is True, "a real measurement of a beatless song read as never taken"
    assert flat["beats"] == []

    # An envelope missing a key `audio.extract_envelope` promises is not an envelope, and the
    # sidecar reader refuses it before this route sees it -- so `analysed` cannot be true with the
    # beats key simply gone.
    without = {key: value for key, value in kept.items() if key != "beats"}
    sidecar.write_text(json.dumps(without), encoding="utf-8")
    partial = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert partial["analysed"] is False and partial["beats"] == []

    # And JSON that is not an object at all is absent, never "analysed with nothing in it".
    sidecar.write_text("[1, 2, 3]", encoding="utf-8")
    broken = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert broken["analysed"] is False and broken["beats"] == []
    # The gap half is independent of all of this: no transcription, so no gap targets either way.
    assert broken["measured"] is False
    # The flag and the list are read from one expression, so neither can be true of a state the
    # other is not. Read rather than driven, because the shape it forbids is now unreachable.
    route = Path("src/music_video_producer/app.py").read_text(encoding="utf-8").split(
        'def read_timeline_snap_targets(', 1
    )[1].split("\n    @app.", 1)[0]
    assert "envelope = served if isinstance(served, dict) else None" in route
    assert '"analysed": envelope is not None' in route


def test_the_timeline_read_carries_the_marks_without_the_per_frame_series(tmp_path: Path):
    """One read for one measurement: what the band draws rides with what the drag lands on.

    **The reason this is one route and not two.** Two client reads of one measurement is a drift
    mechanism, and it drifted three ways in Epic 8, every one of them executed in
    `epic-8-retro-2026-08-24.md`: a byte change under an unchanged manifest record was invisible to
    both client keys (S4); one read refused while the other succeeded showed no marks while the cut
    still snapped (S5); and a single project load hashed the master twice and parsed the same
    sidecar twice to use 2% of it (S3). Served from one computation, `analysed`, `beats` and
    `envelope` cannot describe different states, because there is nothing for them to disagree
    about.

    **What is trimmed and why.** Measured on a real 202 s master: the sidecar is 469,472 bytes, of
    which `bands`, `rms`, `peak` and `flux` are 460,264 — 98.0%, and not one byte of it is read by
    the browser. What rides here is what is consumed plus what AD-26's band selector will need, and
    the rule is asserted from `SERVED_ENVELOPE_KEYS` rather than from a hand-list, so a key added
    there without a consumer fails this rather than quietly growing the payload back.

    **`GET /song/envelope` is unchanged and is checked here as the other side of that**: it still
    serves the whole thing, per-frame series included, to anyone who wants it.
    """
    from music_video_producer.app import SERVED_ENVELOPE_KEYS
    from music_video_producer.audio import ENVELOPE_REQUIRED_KEYS

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Trimmed"))
    import_measured_song(client, project.id, bpm=120)

    served = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    saved = ProjectStore(tmp_path).get(project.id)
    whole = json.loads(
        (store.project_dir(project.id) / saved.song.analysis.path).read_text(encoding="utf-8")
    )

    # Exactly the projection, and every value is the sidecar's own rather than a re-derivation.
    assert set(served["envelope"]) == set(SERVED_ENVELOPE_KEYS)
    for key in SERVED_ENVELOPE_KEYS:
        assert served["envelope"][key] == whole[key], key
    # The two the next epic needs are fixed-size, which is the whole argument for carrying them.
    assert len(served["envelope"]["band_average"]) == whole["band_count"]

    # The per-frame series are on disk and are not on this wire. Named from the required key set
    # rather than typed out, so a series added to `audio.py` is caught here too.
    series = set(ENVELOPE_REQUIRED_KEYS) - set(SERVED_ENVELOPE_KEYS)
    assert {"bands", "rms", "peak", "flux"} <= series
    for key in series:
        assert key not in served["envelope"], key

    # And the full-measurement endpoint is exactly as it was: every key, series included.
    full = client.get(f"/api/projects/{project.id}/song/envelope").json()
    assert full["present"] is True and full["reason"] == ""
    assert set(full["envelope"]) == set(ENVELOPE_REQUIRED_KEYS)
    assert full["envelope"] == whole

    # A measurement the read path refuses takes both halves with it, together. A replaced song is
    # the reachable way to that state and is the one S4 was demonstrated with.
    (store.project_dir(project.id) / saved.song.path).write_bytes(click_wav_bytes(bpm=90))
    stale = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert stale["analysed"] is False and stale["beats"] == [] and stale["envelope"] is None
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is False

    # ...and the halves are still independent, which is the point of merging the *read* rather
    # than the two measurements. A song that has been transcribed and not analysed keeps its gap
    # targets and has no marks to draw, and each says so as itself rather than one being inferred
    # from the other's emptiness.
    saved = ProjectStore(tmp_path).get(project.id)
    saved.song.lyric_words = [("la", 0.5, 1.0), ("la", 2.5, 3.0)]
    saved.song.vocal_spans = [(0.5, 1.0), (2.5, 3.0)]
    store.save(saved)
    half = client.get(f"/api/projects/{project.id}/timeline/snap-targets").json()
    assert half["measured"] is True and half["gaps"], half
    assert half["analysed"] is False and half["beats"] == [] and half["envelope"] is None


def test_the_snap_targets_shape_is_declared_and_drops_nothing(tmp_path: Path):
    """`GET /timeline/snap-targets` answers a declared model, and the model is the whole answer.

    **A `response_model` on a route that already has consumers is a filter.** FastAPI serialises
    the handler's dict *through* the model, so a field the model omits vanishes from the wire with
    no error and no log — and two e2e scripts plus the browser read this route. That is the entire
    risk of retrospective item A13, which asked for the declaration because this was the only
    `/timeline/` route without one, beside seven siblings that all have one.

    So the shape is held from both ends rather than described. The model's fields are compared
    against the keys of the handler's own `return` dict, read out of `app.py`'s parse tree, and
    the served body is compared **byte for byte** with the JSON that dict serialised to before the
    model existed. A field added to one side and not the other fails here rather than in a
    browser.

    `GET /song/envelope` is deliberately left undeclared and is checked here as the other side of
    that: its docstring argues the omission — it serves `audio.py`'s own recorded arrays — and
    A13 did not overturn it.
    """
    from music_video_producer.app import (
        SERVED_ENVELOPE_KEYS,
        SnapTargetsEnvelope,
        SnapTargetsResponse,
        served_measurement,
    )

    # The handler's `return {...}` keys, read off the source rather than off a response: a route
    # that stopped setting a field would otherwise look identical to a model that dropped it.
    tree = ast.parse(Path("src/music_video_producer/app.py").read_text(encoding="utf-8"))
    handler = next(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.FunctionDef) and node.name == "read_timeline_snap_targets"
    )
    returned = next(
        node.value
        for node in ast.walk(handler)
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Dict)
    )
    keys = {key.value for key in returned.keys}
    assert keys == set(SnapTargetsResponse.model_fields), (
        "the declared shape and the handler's answer disagree, so a field is being dropped or "
        f"invented on the wire: {sorted(keys ^ set(SnapTargetsResponse.model_fields))}"
    )
    # The nested half is `served_measurement`'s projection, and the two lists must not drift: a
    # key added to `SERVED_ENVELOPE_KEYS` without a field here would be filtered straight off.
    assert set(SnapTargetsEnvelope.model_fields) == set(SERVED_ENVELOPE_KEYS)

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Declared"))

    # Every field, in every state the route can answer in. Asserted as the *whole* key set rather
    # than as "the ones I care about", because dropping is silent and the empty states are where a
    # default would hide it.
    def body(label: str) -> dict:
        response = client.get(f"/api/projects/{project.id}/timeline/snap-targets")
        assert response.status_code == 200, response.text
        payload = response.json()
        assert set(payload) == set(SnapTargetsResponse.model_fields), (label, sorted(payload))
        return payload

    songless = body("no song at all")
    assert songless == {"gaps": [], "beats": [], "measured": False, "analysed": False,
                        "start": 0.0, "end": 0.0, "envelope": None}

    import_measured_song(client, project.id, bpm=120)
    analysed = body("measured and analysed")
    assert analysed["analysed"] is True and analysed["beats"] and analysed["envelope"]

    # Byte-identical to what the bare dict serialised to. Rebuilt from the same two functions the
    # handler calls, over the same stored project, and compared against the raw response — not
    # against `.json()`, which would forgive `0` becoming `0.0`.
    saved = ProjectStore(tmp_path).get(project.id)
    whole = json.loads(
        (store.project_dir(project.id) / saved.song.analysis.path).read_text(encoding="utf-8")
    )
    targets = drag_snap_targets(saved.song, beats=whole["beats"])
    expected = {
        "gaps": targets.gaps,
        "beats": targets.beats,
        "measured": targets.measured,
        "analysed": True,
        "start": targets.start,
        "end": targets.end,
        "envelope": served_measurement(whole),
    }
    raw = client.get(f"/api/projects/{project.id}/timeline/snap-targets").content
    assert raw == json.dumps(
        expected, ensure_ascii=False, allow_nan=False, indent=None, separators=(",", ":")
    ).encode("utf-8"), raw

    # Transcribed and not analysed: the gap half alone, and every field still present.
    saved.song.lyric_words = [("la", 0.5, 1.0), ("la", 2.5, 3.0)]
    saved.song.vocal_spans = [(0.5, 1.0), (2.5, 3.0)]
    store.save(saved)
    (store.project_dir(project.id) / saved.song.path).write_bytes(click_wav_bytes(bpm=90))
    half = body("transcribed, and the analysis no longer describes the file")
    assert half["measured"] is True and half["gaps"]
    assert half["analysed"] is False and half["beats"] == [] and half["envelope"] is None

    # A key `served_measurement` did not carry stays absent rather than becoming `[]`. Unreachable
    # through the route — `store.read_song_envelope` refuses a sidecar missing a required key — so
    # it is asserted where it lives, on the model and the flag the route is served with. Without
    # `response_model_exclude_unset` this is `[]`, which reads as a measurement that found no
    # onsets rather than one that was never taken.
    short = SnapTargetsResponse.model_validate(
        {"gaps": [], "beats": [1.0], "measured": False, "analysed": True, "start": 0.0,
         "end": 4.0, "envelope": {"beats": [1.0]}}
    )
    assert short.model_dump(exclude_unset=True)["envelope"] == {"beats": [1.0]}
    assert set(short.model_dump()["envelope"]) == set(SERVED_ENVELOPE_KEYS)

    # And the point of declaring it at all: the fields are now discoverable, which is what the
    # seven siblings have and this route did not.
    schema = client.get("/openapi.json").json()
    reference = schema["paths"]["/api/projects/{project_id}/timeline/snap-targets"]["get"][
        "responses"]["200"]["content"]["application/json"]["schema"]["$ref"]
    declared = schema["components"]["schemas"][reference.rsplit("/", 1)[1]]
    assert set(declared["properties"]) == set(SnapTargetsResponse.model_fields)

    # `GET /song/envelope` is unchanged and still undeclared, for the reason its docstring gives.
    envelope_route = schema["paths"]["/api/projects/{project_id}/song/envelope"]["get"][
        "responses"]["200"]["content"]["application/json"]["schema"]
    assert "$ref" not in envelope_route, envelope_route


def test_the_envelope_is_served_by_its_own_endpoint_and_never_by_a_project_response(
    tmp_path: Path,
):
    """Its own read-only endpoint, and the manifest stays small.

    The size argument is the whole reason for the sidecar: a manifest rides a two-second poll, so
    an envelope embedded in a Project response would multiply every poll by the length of the
    song. Both halves are asserted — the endpoint serves the arrays, and no Project response or
    stored manifest contains them.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Served"))
    import_measured_song(client, project.id)

    served = client.get(f"/api/projects/{project.id}/song/envelope")
    assert served.status_code == 200
    payload = served.json()
    assert payload["present"] is True
    assert payload["reason"] == ""
    assert len(payload["envelope"]["rms"]) == payload["envelope"]["analysis_frames"]

    # No Project response embeds it, and neither does the manifest on disk.
    read = client.get(f"/api/projects/{project.id}").json()
    assert read["song"]["analysis"]["path"] == "media/analysis/song-envelope.json"
    assert "rms" not in json.dumps(read)
    manifest = (store.project_dir(project.id) / "project.json").read_text(encoding="utf-8")
    assert "rms" not in manifest


def test_an_envelope_does_not_materially_change_the_size_of_the_manifest(tmp_path: Path):
    """The measurement that decided the sidecar, asserted as a bound.

    A three-minute envelope is hundreds of kilobytes against a whole manifest of 110–190 KB. The
    pointer that replaces it is five small fields, so the manifest may grow by a line or two and
    nothing more — this is the test that fails the day somebody "simplifies" the sidecar away.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Sized"))
    manifest = store.project_dir(project.id) / "project.json"

    plain = client.post(
        f"/api/projects/{project.id}/songs/upload",
        data={"title": "Plain", "duration": "4.0"},
        files={"file": ("plain.wav", wav_bytes(4.0), "audio/wav")},
    )
    assert plain.status_code == 200, plain.text
    before = manifest.stat().st_size

    import_measured_song(client, project.id)
    after = manifest.stat().st_size
    envelope = (
        store.project_dir(project.id) / "media/analysis/song-envelope.json"
    ).stat().st_size

    assert after - before < 400, "the manifest grew by more than a pointer"
    assert envelope > 10 * (after - before), "the envelope is not what is being kept out"


def test_a_song_whose_bytes_changed_reports_its_analysis_absent_and_writes_no_flag(
    tmp_path: Path,
):
    """Validity is derived at read time. Nothing marks an envelope stale, ever.

    The song's bytes are replaced under the same path, which is the general case of "the audio
    this was measured from is not the audio that is here now" — and the one this has to survive,
    because no route that touches a song file knows this feature exists. The stored fingerprint
    no longer describes it, so the analysis is **absent**: not degraded, not served with a
    warning, and above all not repaired by the read.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Changed"))
    import_measured_song(client, project.id, bpm=120)

    saved = ProjectStore(tmp_path).get(project.id)
    recorded = saved.song.analysis
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True

    sidecar = store.project_dir(project.id) / recorded.path
    envelope_before = sidecar.read_bytes()
    audio = store.project_dir(project.id) / saved.song.path
    audio.write_bytes(click_wav_bytes(bpm=100))

    report = client.get(f"/api/projects/{project.id}/song/envelope").json()
    assert report == {"present": False, "reason": SONG_ENVELOPE_SONG_CHANGED}
    assert "envelope" not in report

    # Nothing was rewritten and nothing was marked. The record is a pointer, four settings and a
    # fingerprint — there is no field a "stale" flag could even be written into.
    after = ProjectStore(tmp_path).get(project.id)
    assert after.song.analysis == recorded
    assert sidecar.read_bytes() == envelope_before
    assert set(json.loads(after.model_dump_json())["song"]["analysis"]) == {
        "path",
        "analysis_rate",
        "band_count",
        "bpm",
        "song_fingerprint",
    }


def test_a_project_with_no_song_reports_the_analysis_absent(tmp_path: Path):
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Songless"))
    report = client.get(f"/api/projects/{project.id}/song/envelope")
    assert report.status_code == 200, "absence is not an error state"
    assert report.json() == {"present": False, "reason": SONG_ENVELOPE_WITHOUT_SONG}


def test_a_deleted_sidecar_reports_absent_rather_than_a_partial_envelope(tmp_path: Path):
    """A pointer at a file that is gone. The answer is absent — never a zeroed or half envelope,
    which is the failure mode this story names explicitly."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Deleted"))
    import_measured_song(client, project.id)

    saved = ProjectStore(tmp_path).get(project.id)
    (store.project_dir(project.id) / saved.song.analysis.path).unlink()

    assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
        "present": False,
        "reason": SONG_ENVELOPE_FILE_UNREADABLE,
    }


def test_a_corrupt_sidecar_is_not_treated_as_data(tmp_path: Path):
    """Unparseable JSON at the pointer: reported absent, and the unreadable bytes are never handed
    to a consumer as a measurement. A half-read envelope is how zeros get downstream."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Corrupt"))
    import_measured_song(client, project.id)

    saved = ProjectStore(tmp_path).get(project.id)
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    sidecar.write_text('{"rms": [0.1, 0.2', encoding="utf-8")
    assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
        "present": False,
        "reason": SONG_ENVELOPE_FILE_UNREADABLE,
    }

    # And well-formed JSON that is not an object is refused for the same reason.
    sidecar.write_text("[1, 2, 3]", encoding="utf-8")
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is False


def test_an_import_still_succeeds_when_ffmpeg_is_missing(tmp_path: Path, monkeypatch):
    """The Song is the import's job; the measurement is a bonus it must never be able to refuse.

    ffmpeg absent, so nothing can be decoded. The upload answers 200, the Song is stored whole, no
    envelope is written, no record is planted, and the reason is named rather than becoming a 500
    the Director cannot act on.
    """
    from music_video_producer import app as app_module
    from music_video_producer.audio import FfmpegMissing

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="No ffmpeg"))

    def missing(*_args, **_kwargs):
        raise FfmpegMissing("ffmpeg was not found on PATH")

    monkeypatch.setattr(app_module, "analyze_song", missing)
    import_measured_song(client, project.id)

    saved = ProjectStore(tmp_path).get(project.id)
    assert saved.song.title == "Measured"
    assert saved.song.duration == 4.0
    assert saved.song.path.endswith("beat.wav")
    assert saved.song.analysis == models.SongAnalysis(), "a failure planted a record"
    assert not (store.project_dir(project.id) / "media" / "analysis").exists()

    # Read back on a machine where ffmpeg *is* installed and the file *is* decodable — which is
    # exactly this machine, since only the decode call was stubbed out. So the endpoint says the
    # plain thing, and that is the point: the reason is a fact about now, not a record of the
    # failed attempt. The machine-is-missing-ffmpeg reading has its own test below.
    assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
        "present": False,
        "reason": SONG_ENVELOPE_NOT_TAKEN,
    }
    # The reasons are named strings carrying their own remedy, not bare exception text.
    assert "ffmpeg" in SONG_ANALYSIS_FFMPEG_MISSING
    assert "{reason}" in SONG_ANALYSIS_DECODE_FAILED


def test_an_undecodable_file_leaves_the_song_intact_and_names_why(tmp_path: Path):
    """The same contract on the other failure: ffmpeg runs, and the file is not audio.

    The import still succeeds and the Song is stored whole. What the endpoint says about it is the
    specific reason rather than the generic one — worked out at read time by probing the file that
    is there now, not read back from a note somebody wrote when the import happened.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Not audio"))

    response = client.post(
        f"/api/projects/{project.id}/songs/upload",
        data={"title": "Broken", "duration": "3.0"},
        files={"file": ("broken.wav", b"this is not a wave file", "audio/wav")},
    )
    assert response.status_code == 200, response.text

    saved = ProjectStore(tmp_path).get(project.id)
    assert saved.song.title == "Broken"
    assert saved.song.analysis == models.SongAnalysis()
    assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
        "present": False,
        "reason": SONG_ENVELOPE_UNDECODABLE,
    }


def test_the_absence_reasons_split_into_read_and_write():
    """How many absence reasons there are, derived from `app.py` instead of retyped.

    **This test exists because the number was stated three times and was wrong all three.** A
    dispatch said "six", and the six propagated into `song_envelope_report`'s docstring -- which
    then hand-listed five bullets and the envelope, omitting `SONG_ENVELOPE_RECORD_DISAGREES`,
    which the same function returns seventy lines lower -- into a `deferred-work.md` entry, and
    into a test docstring that said twelve of a set that is not the one a read can reach. Retro
    finding S10, action item A11.

    So the split is *derived*: the declared constants from the module's own namespace, and the
    read-reachable ones from the three functions a read actually passes through, by walking the
    parse tree for the names they mention. A reason added tomorrow lands in one half or the other
    and the partition below still holds; what it cannot do is quietly make a stated count wrong,
    because the counts stated in prose are asserted against these.

    Names are read from `ast.Name` nodes, so a constant *mentioned in a docstring* -- which
    `song_envelope_report`'s now does, for all twelve -- is not mistaken for one the code returns.
    """
    from music_video_producer import app as app_module

    prefixes = ("SONG_ENVELOPE_", "SONG_ANALYSIS_")
    declared = {
        name
        for name, value in vars(app_module).items()
        if isinstance(value, str) and name.startswith(prefixes)
    }
    tree = ast.parse(Path("src/music_video_producer/app.py").read_text(encoding="utf-8"))
    bodies = {
        node.name: node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    def mentioned(function: str) -> set[str]:
        assert function in bodies, f"{function} was renamed, so this test proves nothing"
        return {
            node.id
            for node in ast.walk(bodies[function])
            if isinstance(node, ast.Name) and node.id.startswith(prefixes)
        }

    # The three functions a `present: false` passes through: the route's own report, the verdict
    # it delegates the middle to, and the never-measured branch's own reason.
    read_reachable = (
        mentioned("song_envelope_report")
        | mentioned("song_measurement_verdict")
        | mentioned("analysis_absence_reason")
    )
    write_only = declared - read_reachable

    # The measured truth, and the shape of it rather than only the size: every declared reason is
    # in exactly one half, so a thirteenth cannot go uncounted by being in neither.
    assert read_reachable <= declared, sorted(read_reachable - declared)
    assert read_reachable | write_only == declared
    assert not (read_reachable & write_only)
    assert len(declared) == 12, sorted(declared)
    assert read_reachable == {
        "SONG_ENVELOPE_WITHOUT_SONG",
        "SONG_ENVELOPE_AUDIO_PENDING",
        "SONG_ANALYSIS_MEDIA_MISSING",
        "SONG_ANALYSIS_FFMPEG_MISSING",
        "SONG_ENVELOPE_UNDECODABLE",
        "SONG_ENVELOPE_NOT_TAKEN",
        "SONG_ENVELOPE_SONG_CHANGED",
        "SONG_ENVELOPE_FILE_UNREADABLE",
        "SONG_ENVELOPE_RECORD_DISAGREES",
    }, sorted(read_reachable)
    # The write half's three: reported by the analysis path, logged, and never on a read's wire.
    assert write_only == {
        "SONG_ANALYSIS_WITHOUT_SONG",
        "SONG_ANALYSIS_DECODE_FAILED",
        "SONG_ANALYSIS_WRITE_FAILED",
    }, sorted(write_only)

    # And every read-reachable sentence really is one a read can answer with -- named in the
    # docstring that lists them, so the list and the branches cannot drift apart again. The
    # count is spelled from the derived length rather than typed, which is the whole point.
    spelled = {9: "nine", 12: "twelve", 3: "three"}
    report = bodies["song_envelope_report"]
    docstring = ast.get_docstring(report) or ""
    assert f"{spelled[len(read_reachable)]} sentences and the envelope" in docstring, docstring
    for name in read_reachable:
        assert f"`{name}`" in docstring, f"{name} is returned by a read and named in no docstring"
    for name in write_only:
        assert f"`{name}`" in docstring, f"{name} is not named as the write half's"


def test_a_manifest_without_the_analysis_field_loads_and_round_trips(tmp_path: Path):
    """Every `project.json` written before this story loads unchanged.

    Hand-written without the key, read through a fresh `ProjectStore`, saved back: the record
    arrives at its default, which means *no analysis*, and nothing else about the manifest moves.
    """
    store = ProjectStore(tmp_path)
    project = store.create(Project(name="Legacy envelope"))
    manifest = store.project_dir(project.id) / "project.json"
    raw = json.loads(manifest.read_text(encoding="utf-8"))
    raw["song"] = {
        "title": "Older",
        "source": "imported",
        "path": "media/o.mp3",
        "duration": 90.0,
        "lyrics": "[Verse]\nWords\n",
        "caption": "",
        "vocal_type": "duet",
    }
    manifest.write_text(json.dumps(raw), encoding="utf-8")

    loaded = ProjectStore(tmp_path).get(project.id)
    assert loaded.song.analysis == models.SongAnalysis()
    assert loaded.song.analysis.path == "" and loaded.song.analysis.bpm == 0
    assert loaded.song.vocal_type == "duet"

    ProjectStore(tmp_path).save(loaded)
    again = ProjectStore(tmp_path).get(project.id)
    assert again.song.analysis == models.SongAnalysis()
    assert again.song.lyrics == "[Verse]\nWords\n"


def test_the_analysis_pointer_is_server_owned_on_the_generic_project_put(tmp_path: Path):
    """The seventh field to meet this route's recurring guard hole, guarded the same way.

    Both directions, because both are real. A client written before the field existed *omits* it,
    so an ordinary save arrives carrying a default record and would discard the pointer to a
    measurement that is still on disk and still current. A client that *invents* one names a
    sidecar path this application then reads, with a fingerprint that would make a stale envelope
    pass the one check built to catch it.

    Both saves must also answer 200 rather than the song-replacement refusal: the adoption happens
    ahead of `project.song != current.song`, so a body differing only here compares equal.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Owned"))
    import_measured_song(client, project.id)
    stored = ProjectStore(tmp_path).get(project.id).song.analysis
    assert stored.path and stored.song_fingerprint

    # Omitted entirely — the shape every pre-existing client sends.
    body = client.get(f"/api/projects/{project.id}").json()
    body["song"].pop("analysis")
    omitted = client.put(f"/api/projects/{project.id}", json=body)
    assert omitted.status_code == 200, omitted.text
    assert ProjectStore(tmp_path).get(project.id).song.analysis == stored

    # Forged — a body inventing a record, pointed at a file of its own choosing.
    body = client.get(f"/api/projects/{project.id}").json()
    body["song"]["analysis"] = {
        "path": "media/analysis/forged.json",
        "analysis_rate": 999.0,
        "band_count": 3,
        "bpm": 200.0,
        "song_fingerprint": "0-forged",
    }
    forged = client.put(f"/api/projects/{project.id}", json=body)
    assert forged.status_code == 200, forged.text
    assert ProjectStore(tmp_path).get(project.id).song.analysis == stored, "a save planted a record"

    # And the envelope still reads as the one that was actually measured.
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True


def test_a_confirmed_song_replacement_detaches_the_analysis_with_the_rest(tmp_path: Path):
    """`_detach_song_recovery_slots`' argument, applied to the measurement.

    An envelope describes the audio it was taken from. Carried across a confirmed replacement it
    would hand the old track's beats to the new one behind a pointer that looks perfectly healthy.
    The fingerprint would catch it on the next read; writing a record already known to be wrong
    and leaning on a downstream check is not how this codebase detaches derived state.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Detached"))
    import_measured_song(client, project.id)
    assert ProjectStore(tmp_path).get(project.id).song.analysis.path

    body = client.get(f"/api/projects/{project.id}").json()
    body["song"] = {
        "title": "A Different Track",
        "source": "imported",
        "path": "media/other.mp3",
        "duration": 121.0,
        "lyrics": "",
        "caption": "",
    }
    replaced = client.put(f"/api/projects/{project.id}?confirm_song_replacement=true", json=body)
    assert replaced.status_code == 200, replaced.text

    saved = ProjectStore(tmp_path).get(project.id)
    assert saved.song.title == "A Different Track"
    assert saved.song.analysis == models.SongAnalysis(), "the new song kept the old measurement"


def test_the_analysis_entry_point_is_callable_and_skippable_from_outside_a_route(tmp_path: Path):
    """Treatment Story 16.2's requirement, met here rather than promised.

    That story folds this analysis and the lyric-structure pass under one trigger *without*
    merging the computations, so this half has to be callable from somewhere that is not the
    import route — and skipped when it is already current, since the common case there is that
    the song was measured on import. A skip returns the same empty reason a fresh measurement
    does, because "already done" is a success and must never read as a failure to run.
    """
    store = ProjectStore(tmp_path)
    project = store.create(Project(name="Callable"))
    audio = store.media_dir(project.id) / "songs" / "000-beat.wav"
    audio.parent.mkdir(parents=True, exist_ok=True)
    audio.write_bytes(click_wav_bytes(bpm=120))
    project.song = models.Song(
        title="Callable",
        source="imported",
        path=audio.relative_to(store.project_dir(project.id)).as_posix(),
        duration=4.0,
    )

    assert analyze_project_song(store, project.id, project, audio) == ""
    first = project.song.analysis
    assert first.bpm == pytest.approx(120, rel=0.05)
    sidecar = store.project_dir(project.id) / first.path
    written = sidecar.read_bytes()
    sidecar.write_bytes(written + b"\n")  # a marker only a re-measure would erase

    # Called again over unchanged bytes: skipped, reported as success, and nothing rewritten.
    assert analyze_project_song(store, project.id, project, audio) == ""
    assert project.song.analysis == first
    assert sidecar.read_bytes() == written + b"\n"

    # `force` is the caller that wants it retaken anyway — at a changed rate, and the record says
    # so, which is the whole reason the rate is a field rather than a constant.
    assert analyze_project_song(store, project.id, project, audio, force=True) == ""
    assert sidecar.read_bytes() == written

    # And a record whose sidecar has gone re-measures rather than reporting itself current.
    sidecar.unlink()
    assert analyze_project_song(store, project.id, project, audio) == ""
    assert sidecar.exists()

    # A song-less project is a named reason, never a raise and never an envelope of zeros.
    project.song = None
    assert analyze_project_song(store, project.id, project, audio) == SONG_ANALYSIS_WITHOUT_SONG


def test_the_shot_list_write_path_carries_no_song_to_adopt():
    """The narrower sibling, checked rather than assumed.

    `PUT .../shots` is the route this codebase's guard holes keep turning up on, and it re-invokes
    `_adopt_expansion_maps` for exactly that reason. It needs no song-level adoption because its
    body cannot carry a Song at all — asserted about the request model, so the day someone widens
    it, this test is what says a new adoption is owed.
    """
    from music_video_producer import app as app_module

    assert set(app_module.ShotListRequest.model_fields) == {"shots", "updated_at"}


# ---------------------------------------------------------------------------
# Story 8.1, Director rulings — a generated song is measured too, and the reason
# an envelope is missing is worked out at read time rather than remembered.
# ---------------------------------------------------------------------------


def generated_song_take(store, project_id: str, filename: str = "take.wav", bpm: float = 120.0):
    """Put real audio where a completed music render would have left it.

    A generated Song's audio does not live under the project at all — it is written by ComfyUI
    into its own output tree, and `resolve_song_path` resolves it against `comfy_root/output`.
    Writing a genuine click track there is what makes the analysis in these tests a real
    measurement rather than a stubbed one.
    """
    subfolder = f"music-video-producer/{project_id}/songs"
    target = store.data_root / "comfy" / "output" / Path(subfolder) / filename
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(click_wav_bytes(bpm=bpm))
    return subfolder, filename, target


def test_a_generated_song_is_analysed_when_its_render_lands(tmp_path: Path):
    """The other half of "imported **or** generated", on the per-job refresh route.

    A generated Song is created with no audio at all: the record is written when ComfyUI accepts
    the graph, and the file appears minutes later when the render lands. `apply_job_history` is
    the one writer that fills the path in, so that is where "the Song was stored" happens here —
    and until this hook existed, a Director who generated their song never got an envelope.
    """
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Generated"))
    job = client.post(
        f"/api/projects/{project.id}/generate/music",
        json={"title": "Machine made", "caption": "industrial synth rock", "duration": 4},
    ).json()
    subfolder, filename, audio = generated_song_take(store, project.id, bpm=120)
    comfy.history = completed_history_for([{"subfolder": subfolder, "filename": filename}])

    refreshed = client.get(f"/api/projects/{project.id}/jobs/{job['id']}")
    assert refreshed.status_code == 200, refreshed.text

    saved = ProjectStore(tmp_path).get(project.id)
    assert saved.song.source == "generated"
    assert saved.song.path == f"{subfolder}/{filename}"
    # Measured, and measured from the file ComfyUI actually wrote — the fingerprint is taken over
    # the take in the output tree, not over anything under the project.
    assert saved.song.analysis.path == "media/analysis/song-envelope.json"
    assert saved.song.analysis.bpm == pytest.approx(120, rel=0.05)
    assert saved.song.analysis.song_fingerprint == song_fingerprint(audio)
    assert saved.song.analysis.band_count == 8

    served = client.get(f"/api/projects/{project.id}/song/envelope").json()
    assert served["present"] is True
    assert len(served["envelope"]["bands"]) == 8


def test_the_poll_analyses_a_generated_song_when_its_audio_lands(tmp_path: Path):
    """The same hook on the route the browser actually drives.

    `read_job` is the manual refresh and the smoke scripts' path; `/render-status` is the
    two-second poll the interface runs while a render is open, and it is the one that will in
    practice see a music job finish. Both call `apply_job_history`, so both need the hook — a
    generated song analysed on only one of them is a coin toss.
    """
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Polled generation"))
    client.post(
        f"/api/projects/{project.id}/generate/music",
        json={"title": "Polled", "caption": "colder synth rock", "duration": 4},
    )
    subfolder, filename, _audio = generated_song_take(store, project.id, bpm=100)
    comfy.history = completed_history_for([{"subfolder": subfolder, "filename": filename}])

    report = client.get(f"/api/projects/{project.id}/render-status")
    assert report.status_code == 200, report.text
    assert report.json()["jobs"][0]["status"] == "complete"

    saved = ProjectStore(tmp_path).get(project.id)
    assert saved.song.path == f"{subfolder}/{filename}"
    assert saved.song.analysis.bpm == pytest.approx(100, rel=0.05)
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True


def test_an_ordinary_poll_tick_neither_analyses_nor_hashes_the_song(tmp_path: Path):
    """The Director's constraint on the hook, asserted rather than described.

    The trigger is an **in-memory path comparison**, and it has to be, because the alternative —
    letting the analysis decide for itself by fingerprint — puts a SHA-256 of a multi-megabyte
    audio file on a two-second loop, forever, to answer "no" every single time.

    So: a tick that genuinely changes the project (a Flux render settles, an Asset adopts its
    landed file) while the Song's path is untouched must not reach the analysis and must not read
    a single byte of the song. Both spies stay at zero.
    """
    from music_video_producer import app as app_module

    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Quiet tick"))
    import_measured_song(client, project.id)
    job = client.post(
        f"/api/projects/{project.id}/generate/flux",
        json={
            "name": "Lead singer",
            "kind": "character",
            "prompt": "portrait",
            "width": 1024,
            "height": 1024,
            "steps": 4,
            "guidance": 4,
            "seed": 1,
        },
    ).json()
    assert job["prompt_id"]

    # Installed after the import, so the import's own honest measurement is not counted.
    calls = {"analyze": 0, "fingerprint": 0}
    real_fingerprint = app_module.song_fingerprint

    def counted_analyze(*args, **kwargs):
        calls["analyze"] += 1
        raise AssertionError("an unchanged song path reached the analysis")

    def counted_fingerprint(path):
        calls["fingerprint"] += 1
        return real_fingerprint(path)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "analyze_song", counted_analyze)
    monkeypatch.setattr(app_module, "song_fingerprint", counted_fingerprint)
    try:
        comfy.history = completed_history_for(
            [
                {
                    "subfolder": f"music-video-producer/{project.id}/assets",
                    "filename": "Lead singer_00001_.png",
                }
            ]
        )
        report = client.get(f"/api/projects/{project.id}/render-status")
        assert report.status_code == 200, report.text
        # The tick really did change the project — otherwise this proves nothing at all.
        assert report.json()["assets"][0]["path"].endswith("Lead singer_00001_.png")
        assert ProjectStore(tmp_path).get(project.id).assets[0].path
    finally:
        monkeypatch.undo()

    assert calls["analyze"] == 0, "the poll re-analysed a song whose path never moved"
    assert calls["fingerprint"] == 0, "the poll hashed the song file on an ordinary tick"


def test_a_landed_song_is_analysed_once_and_not_again_on_later_ticks(tmp_path: Path):
    """Landing is a one-time event, and the tick after it must be as cheap as the tick before.

    The first tick sees the path change and measures. Every tick after it sees the same path and
    does nothing — which is the property that makes hooking the poll affordable at all.
    """
    from music_video_producer import app as app_module

    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Once only"))
    client.post(
        f"/api/projects/{project.id}/generate/music",
        json={"title": "Once", "caption": "industrial synth rock", "duration": 4},
    )
    subfolder, filename, _audio = generated_song_take(store, project.id, bpm=120)
    comfy.history = completed_history_for([{"subfolder": subfolder, "filename": filename}])

    calls = {"analyze": 0}
    real_analyze = app_module.analyze_song

    def counted(source, **kwargs):
        calls["analyze"] += 1
        return real_analyze(source, **kwargs)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "analyze_song", counted)
    try:
        assert client.get(f"/api/projects/{project.id}/render-status").status_code == 200
        assert calls["analyze"] == 1, "the landing did not trigger a measurement"
        for _ in range(3):
            assert client.get(f"/api/projects/{project.id}/render-status").status_code == 200
        assert calls["analyze"] == 1, "a later tick re-measured a song that had not changed"
    finally:
        monkeypatch.undo()

    assert ProjectStore(tmp_path).get(project.id).song.analysis.bpm == pytest.approx(120, rel=0.05)


def test_a_song_whose_audio_is_not_on_disk_says_so(tmp_path: Path):
    """A record pointing at audio that is not there — a generated Song still rendering, or a file
    deleted by hand. Named as a missing file rather than as "not analysed yet", because the two
    have different remedies and only one of them is waiting."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="No audio"))
    project.song = models.Song(
        title="Pending", source="imported", path="media/songs/000-never-written.wav", duration=4.0
    )
    store.save(project)

    assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
        "present": False,
        "reason": SONG_ANALYSIS_MEDIA_MISSING,
    }

    # A generated Song whose render has not landed yet has no path at all, and that is a
    # *different* state with a different remedy: nothing is lost and nothing needs doing. Telling
    # a Director their audio "was not found on disk" while it is still rendering would send them
    # looking for a file that was never supposed to exist yet.
    project.song = models.Song(title="Queued", source="generated", path="", duration=4.0)
    store.save(project)
    assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
        "present": False,
        "reason": SONG_ENVELOPE_AUDIO_PENDING,
    }
    assert SONG_ENVELOPE_AUDIO_PENDING != SONG_ANALYSIS_MEDIA_MISSING


def test_the_absence_reason_is_recomputed_from_this_machine_and_never_stored(tmp_path: Path):
    """AD-21 and standing law 5, applied to a failure rather than to a validity verdict.

    The obvious implementation is a `reason` field on `SongAnalysis`, written when an analysis
    fails. It is the same mistake as a `valid` flag one step further from the truth: a stored
    string describes an attempt that happened once, on a machine that may since have had ffmpeg
    installed, over a file that may since have been replaced. It can only get more wrong, and
    nothing would ever clear it.

    So this asserts the property directly. One project, one manifest, **byte-identical throughout**
    — and two different answers, decided only by whether ffmpeg is on PATH at the moment of the
    read. A stored reason cannot do that.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Recomputed"))
    client.post(
        f"/api/projects/{project.id}/songs/upload",
        data={"title": "Fine", "duration": "4.0"},
        files={"file": ("fine.wav", click_wav_bytes(bpm=120), "audio/wav")},
    )
    # Clear the record so the endpoint has to explain an absence rather than serve an envelope.
    saved = ProjectStore(tmp_path).get(project.id)
    saved.song.analysis = models.SongAnalysis()
    ProjectStore(tmp_path).save(saved)
    manifest = store.project_dir(project.id) / "project.json"
    before = manifest.read_bytes()

    endpoint = f"/api/projects/{project.id}/song/envelope"
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_NOT_TAKEN

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module.shutil, "which", lambda _name: None)
    try:
        assert client.get(endpoint).json() == {
            "present": False,
            "reason": SONG_ANALYSIS_FFMPEG_MISSING,
        }
    finally:
        monkeypatch.undo()

    # Put ffmpeg back and the answer goes back with it. Nothing was written to reach either one.
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_NOT_TAKEN
    assert manifest.read_bytes() == before, "a read-only endpoint wrote the manifest"

    # The record has nowhere to keep a reason even if somebody wanted to.
    assert set(models.SongAnalysis.model_fields) == {
        "path",
        "analysis_rate",
        "band_count",
        "bpm",
        "song_fingerprint",
    }


def test_every_absence_the_endpoint_reports_names_its_own_cause(tmp_path: Path):
    """The six answers, end to end, each distinguishable from the other five.

    A single `present: false` with one sentence for every cause would be the easy version and the
    useless one: "no analysis" sends a Director looking for a button when the real answer is that
    ffmpeg is not installed, or that the file they imported is not audio, or that the song they
    replaced this morning is why. Distinct causes, distinct sentences.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Six answers"))
    endpoint = f"/api/projects/{project.id}/song/envelope"

    # 1. No Song at all.
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_WITHOUT_SONG

    # 2. A Song whose audio is not on disk.
    project.song = models.Song(title="Gone", source="imported", path="media/songs/gone.wav")
    store.save(project)
    assert client.get(endpoint).json()["reason"] == SONG_ANALYSIS_MEDIA_MISSING

    # 3. A file ffmpeg will not decode.
    client.post(
        f"/api/projects/{project.id}/songs/upload?confirm_song_replacement=true",
        data={"title": "Broken", "duration": "3.0", "confirm_song_replacement": "true"},
        files={"file": ("broken.wav", b"this is not a wave file", "audio/wav")},
    )
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_UNDECODABLE

    # 4. ffmpeg absent from this machine.
    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module.shutil, "which", lambda _name: None)
    try:
        assert client.get(endpoint).json()["reason"] == SONG_ANALYSIS_FFMPEG_MISSING
    finally:
        monkeypatch.undo()

    # 5. A real, measured song — the one answer that is not an absence.
    replaced = client.post(
        f"/api/projects/{project.id}/songs/upload?confirm_song_replacement=true",
        data={"title": "Real", "duration": "4.0", "confirm_song_replacement": "true"},
        files={"file": ("real.wav", click_wav_bytes(bpm=120), "audio/wav")},
    )
    assert replaced.status_code == 200, replaced.text
    assert client.get(endpoint).json()["present"] is True

    # 6. The song's bytes change underneath it.
    saved = ProjectStore(tmp_path).get(project.id)
    audio = store.project_dir(project.id) / saved.song.path
    audio.write_bytes(click_wav_bytes(bpm=90))
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_SONG_CHANGED

    # 7. The sidecar goes missing.
    audio.write_bytes(click_wav_bytes(bpm=120))
    assert client.get(endpoint).json()["present"] is True
    (store.project_dir(project.id) / saved.song.analysis.path).unlink()
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_FILE_UNREADABLE

    # Every sentence above is distinct — a reason that duplicates another is a reason that does
    # not tell the Director which of the two happened.
    reasons = {
        SONG_ENVELOPE_WITHOUT_SONG,
        SONG_ANALYSIS_MEDIA_MISSING,
        SONG_ENVELOPE_UNDECODABLE,
        SONG_ANALYSIS_FFMPEG_MISSING,
        SONG_ENVELOPE_SONG_CHANGED,
        SONG_ENVELOPE_FILE_UNREADABLE,
        SONG_ENVELOPE_NOT_TAKEN,
    }
    assert len(reasons) == 7


def test_the_envelope_endpoint_computes_nothing_and_persists_nothing(tmp_path: Path):
    """Read-only in the strong sense, asserted where it is easiest to break.

    The endpoint now works out *why* an envelope is missing, which puts it one short step from
    helpfully producing one. It must not: offering the fix is an interface decision with its own
    route and its own confirmation. So a project with a perfectly analysable song and no record
    answers "not analysed yet" as many times as it is asked, and neither the manifest nor the
    media directory moves.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Read only"))
    client.post(
        f"/api/projects/{project.id}/songs/upload",
        data={"title": "Analysable", "duration": "4.0"},
        files={"file": ("fine.wav", click_wav_bytes(bpm=120), "audio/wav")},
    )
    saved = ProjectStore(tmp_path).get(project.id)
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    sidecar.unlink()
    saved.song.analysis = models.SongAnalysis()
    ProjectStore(tmp_path).save(saved)

    manifest = store.project_dir(project.id) / "project.json"
    before = manifest.read_bytes()

    calls = {"analyze": 0}

    def counted(*args, **kwargs):
        calls["analyze"] += 1
        raise AssertionError("the read-only endpoint computed an envelope")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "analyze_song", counted)
    try:
        for _ in range(3):
            assert client.get(f"/api/projects/{project.id}/song/envelope").json() == {
                "present": False,
                "reason": SONG_ENVELOPE_NOT_TAKEN,
            }
    finally:
        monkeypatch.undo()

    assert calls["analyze"] == 0
    assert manifest.read_bytes() == before
    assert not sidecar.exists()


# ---------------------------------------------------------------------------
# Story 8.1, review findings: the failure paths nobody had exercised, and the
# two gates that keep a read cheap and a measurement honest.
# ---------------------------------------------------------------------------


def test_an_import_survives_a_sidecar_that_cannot_be_written(tmp_path: Path):
    """The disk fills up during the one write this feature makes.

    `SONG_ANALYSIS_WRITE_FAILED` existed, was formatted with a reason, and was reached by no test
    at all - so "the import still succeeds" was an argument about a branch nobody had run. The
    Song must be stored whole, the record must stay defaulted rather than pointing at a file that
    was never written, and the route must answer 200.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Full disk"))

    def no_space(*_args, **_kwargs):
        raise OSError(28, "No space left on device")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module.ProjectStore, "write_song_envelope", no_space)
    try:
        import_measured_song(client, project.id)
    finally:
        monkeypatch.undo()

    saved = ProjectStore(tmp_path).get(project.id)
    assert saved.song.title == "Measured"
    assert saved.song.duration == 4.0
    assert saved.song.path.endswith("beat.wav")
    assert saved.song.analysis == models.SongAnalysis(), "a record was left pointing at nothing"
    assert "{reason}" in SONG_ANALYSIS_WRITE_FAILED


def test_no_analysis_failure_can_ever_take_the_import_down_with_it(tmp_path: Path):
    """The measurement is a bonus and may never cost the Director their upload.

    The catch used to name two exception classes, and what it let through was worse than what it
    caught: a `MemoryError` on a long track, or an `OSError` reading the file out from under a
    decode, escaped into `upload_song`, which then raised before `store.save` - answering 500 with
    the audio on disk and no Song in the manifest at all. Enumerating every exception numpy and
    ffmpeg can raise is not a strategy, so nothing escapes.
    """
    from music_video_producer import app as app_module

    for failure in (MemoryError("out of memory"), OSError(5, "I/O error"), RuntimeError()):
        client, store, _comfy = make_client(tmp_path / str(id(failure)))
        project = store.create(Project(name="Escapes"))

        def raising(*_args, _failure=failure, **_kwargs):
            raise _failure

        monkeypatch = pytest.MonkeyPatch()
        monkeypatch.setattr(app_module, "analyze_song", raising)
        try:
            response = client.post(
                f"/api/projects/{project.id}/songs/upload",
                data={"title": "Kept", "duration": "4.0"},
                files={"file": ("beat.wav", click_wav_bytes(bpm=120), "audio/wav")},
            )
        finally:
            monkeypatch.undo()

        assert response.status_code == 200, f"{type(failure).__name__} took the import down"
        saved = ProjectStore(tmp_path / str(id(failure))).get(project.id)
        assert saved.song is not None, "the upload was lost"
        assert saved.song.title == "Kept"
        assert saved.song.analysis == models.SongAnalysis()


def test_the_read_time_probe_has_no_opinion_when_it_could_not_run(tmp_path: Path):
    """The third answer, and the reason the helper is tri-state at all.

    `False` is ffprobe having read the file and refused it - a verdict about the file. `None` is
    ffprobe not being on this machine, or timing out, or failing to decode its own stderr: no
    verdict, and telling a Director "your file is not audio" on the strength of a tool that never
    ran is exactly the fabricated statement this codebase refuses. Both existing reason tests let
    the real ffprobe run, so only True and False were ever observed.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="No opinion"))
    client.post(
        f"/api/projects/{project.id}/songs/upload",
        data={"title": "Fine", "duration": "4.0"},
        files={"file": ("fine.wav", click_wav_bytes(bpm=120), "audio/wav")},
    )
    saved = ProjectStore(tmp_path).get(project.id)
    saved.song.analysis = models.SongAnalysis()
    ProjectStore(tmp_path).save(saved)
    endpoint = f"/api/projects/{project.id}/song/envelope"

    silenced = [
        FileNotFoundError(2, "No such file or directory", "ffprobe"),
        subprocess.TimeoutExpired("ffprobe", 15),
        UnicodeDecodeError("utf-8", b"\xff", 0, 1, "invalid start byte"),
        PermissionError(13, "Permission denied"),
    ]
    for failure in silenced:
        def raising(*_args, _failure=failure, **_kwargs):
            raise _failure

        monkeypatch = pytest.MonkeyPatch()
        monkeypatch.setattr(app_module.subprocess, "run", raising)
        try:
            answer = client.get(endpoint).json()
        finally:
            monkeypatch.undo()
        assert answer["reason"] == SONG_ENVELOPE_NOT_TAKEN, type(failure).__name__
        assert answer["reason"] != SONG_ENVELOPE_UNDECODABLE

    # And the tri-state's other two answers still work, so this is not a blanket silencer.
    assert app_module._audio_stream_present(
        store.project_dir(project.id) / saved.song.path
    ) is True


def test_the_envelope_read_does_not_hash_a_song_whose_length_already_disagrees(tmp_path: Path):
    """The cost the render-status gate was written to avoid, on the route that pays it.

    A fingerprint carries the byte count it was taken over precisely so this question can be asked
    of a file without reading it. A song that was replaced is almost never the same length as the
    one before it, so the cheap half answers the common case and the SHA-256 runs only when the
    lengths agree.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Cheap read"))
    import_measured_song(client, project.id)
    saved = ProjectStore(tmp_path).get(project.id)
    audio = store.project_dir(project.id) / saved.song.path

    calls = {"hash": 0}
    real = app_module.song_fingerprint

    def counted(path):
        calls["hash"] += 1
        return real(path)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "song_fingerprint", counted)
    try:
        # Same bytes: the sizes agree, so the digest has to settle it and is paid once.
        assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True
        assert calls["hash"] == 1

        # A different length is a definitive "not the same bytes" and needs no hash at all.
        audio.write_bytes(click_wav_bytes(bpm=120, seconds=6.0))
        answer = client.get(f"/api/projects/{project.id}/song/envelope").json()
    finally:
        monkeypatch.undo()

    assert answer["reason"] == SONG_ENVELOPE_SONG_CHANGED
    assert calls["hash"] == 1, "a song of an obviously different length was hashed anyway"


def test_a_song_rewritten_at_the_same_path_is_measured_again(tmp_path: Path):
    """A path that did not change is not proof the audio did not.

    A re-render landing on the same output filename rewrites the bytes underneath an unchanged
    `Song.path`. The path comparison alone would never fire again, leaving a stale envelope that
    nothing in this story can retake - so the landing gate has a second arm: a `stat` against the
    byte count the stored fingerprint was taken over. Still not a hash, and still only reached on
    a tick where something actually settled.
    """
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Same name"))
    job = client.post(
        f"/api/projects/{project.id}/generate/music",
        json={"title": "Take one", "caption": "industrial synth rock", "duration": 4},
    ).json()
    subfolder, filename, audio = generated_song_take(store, project.id, bpm=120)
    comfy.history = completed_history_for([{"subfolder": subfolder, "filename": filename}])
    assert client.get(f"/api/projects/{project.id}/jobs/{job['id']}").status_code == 200
    first = ProjectStore(tmp_path).get(project.id).song.analysis
    assert first.bpm == pytest.approx(120, rel=0.05)

    # A second take at the same filename: different music, different length, same path.
    audio.write_bytes(click_wav_bytes(bpm=90, seconds=6.0))
    second_job = client.post(
        f"/api/projects/{project.id}/generate/music",
        json={"title": "Take two", "caption": "colder synth rock", "duration": 6},
    ).json()
    # The new Song record carries the previous take's path and its previous fingerprint, which is
    # the state the path comparison cannot see through.
    staged = ProjectStore(tmp_path).get(project.id)
    staged.song.path = f"{subfolder}/{filename}"
    staged.song.analysis = first
    ProjectStore(tmp_path).save(staged)
    comfy.history = completed_history_for([{"subfolder": subfolder, "filename": filename}])

    assert client.get(f"/api/projects/{project.id}/jobs/{second_job['id']}").status_code == 200
    again = ProjectStore(tmp_path).get(project.id).song.analysis
    assert again.bpm == pytest.approx(90, rel=0.05), "the rewritten take kept the old measurement"
    assert again.song_fingerprint != first.song_fingerprint
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True


def test_an_envelope_that_disagrees_with_its_record_is_not_served(tmp_path: Path):
    """A consumer reads `band_count` off the *record* and then indexes `bands` in the *file*.

    They are written in the same breath and cannot disagree by any path this application takes -
    but the manifest is hand-editable, and "they cannot differ" is an argument rather than a
    guarantee. A disagreement is an out-of-range read on a screen rather than an error anybody
    sees, so it is checked, and the answer is absent with its own sentence.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Disagreement"))
    import_measured_song(client, project.id)
    endpoint = f"/api/projects/{project.id}/song/envelope"
    assert client.get(endpoint).json()["present"] is True

    for field, value in (("band_count", 3), ("analysis_rate", 60.0)):
        saved = ProjectStore(tmp_path).get(project.id)
        setattr(saved.song.analysis, field, value)
        ProjectStore(tmp_path).save(saved)
        answer = client.get(endpoint).json()
        assert answer == {"present": False, "reason": SONG_ENVELOPE_RECORD_DISAGREES}, field

        saved = ProjectStore(tmp_path).get(project.id)
        setattr(saved.song.analysis, field, {"band_count": 8, "analysis_rate": 30.0}[field])
        ProjectStore(tmp_path).save(saved)
    assert client.get(endpoint).json()["present"] is True

    # And the case the two scalar comparisons cannot see: the record and the envelope's own
    # `band_count` agree with each other, and the `bands` array is shorter than both of them.
    # That is the actual out-of-range read - a panel asking for band 7 of a list with three rows -
    # and neither number in the header would have given it away.
    saved = ProjectStore(tmp_path).get(project.id)
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    envelope = json.loads(sidecar.read_text(encoding="utf-8"))
    assert envelope["band_count"] == saved.song.analysis.band_count == 8
    envelope["bands"] = envelope["bands"][:3]
    sidecar.write_text(json.dumps(envelope), encoding="utf-8")
    assert client.get(endpoint).json() == {
        "present": False,
        "reason": SONG_ENVELOPE_RECORD_DISAGREES,
    }


def measured_project_for_currency(root: Path):
    """A project with real audio and a current measurement, and the two files that describe it.

    Its own data root, so each state below starts from the same clean "current" and one state
    cannot leave a mutated sidecar behind for the next.
    """
    root.mkdir(parents=True, exist_ok=True)
    client, store, _comfy = make_client(root)
    project = store.create(Project(name="Currency"))
    import_measured_song(client, project.id)
    saved = ProjectStore(root).get(project.id)
    audio = store.project_dir(project.id) / saved.song.path
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    return client, store, project.id, audio, sidecar


def edit_analysis_record(root: Path, project_id: str, **fields) -> None:
    """Hand-edit the manifest's analysis record - the state the agreement check exists to catch."""
    saved = ProjectStore(root).get(project_id)
    for name, value in fields.items():
        setattr(saved.song.analysis, name, value)
    ProjectStore(root).save(saved)


def truncate_envelope_bands(sidecar: Path, keep: int) -> None:
    envelope = json.loads(sidecar.read_text(encoding="utf-8"))
    envelope["bands"] = envelope["bands"][:keep]
    sidecar.write_text(json.dumps(envelope), encoding="utf-8")


def test_the_read_and_the_analysis_agree_on_every_state_of_a_measurement(tmp_path: Path):
    """A10: one question, one answer, and both callers asking it.

    Two places on the server used to answer "is this envelope current?" and they answered it
    differently. Only the read path required the manifest record and the sidecar to agree about
    how the song was measured - so a measurement the read reported absent with
    `SONG_ENVELOPE_RECORD_DISAGREES` was current-and-skippable to the analysis, and, the
    non-forced caller being the render-landing path, stayed that way until something forced a
    measurement.

    **Driven, not asserted about the source.** Every row of the story's matrix is put into the
    files, then *both* paths are asked: the read over HTTP, and `analyze_project_song` with its
    `analyze_song` counted. "The analysis considered it current" is defined behaviourally - it
    returned success without measuring - because that is the only definition a caller can
    observe, and it is the one that was wrong.

    The digest count is checked in the same pass: the shared verdict has to settle a song of a
    different length on a `stat`, and it may not take one before the sizes are known to agree.
    """
    from music_video_producer import app as app_module

    #      name, how to reach the state, present?, the read's sentence, digests the read pays
    states = (
        ("current", lambda ctx: None, True, "", 1),
        (
            "record disagrees about the band count",
            lambda ctx: edit_analysis_record(ctx["root"], ctx["project_id"], band_count=3),
            False,
            SONG_ENVELOPE_RECORD_DISAGREES,
            1,
        ),
        (
            "record disagrees about the analysis rate",
            lambda ctx: edit_analysis_record(ctx["root"], ctx["project_id"], analysis_rate=60.0),
            False,
            SONG_ENVELOPE_RECORD_DISAGREES,
            1,
        ),
        (
            "the bands array is shorter than both headers",
            lambda ctx: truncate_envelope_bands(ctx["sidecar"], 3),
            False,
            SONG_ENVELOPE_RECORD_DISAGREES,
            1,
        ),
        (
            "bytes changed, and the length with them",
            lambda ctx: ctx["audio"].write_bytes(click_wav_bytes(bpm=120, seconds=6.0)),
            False,
            SONG_ENVELOPE_SONG_CHANGED,
            0,
        ),
        (
            "bytes changed underneath an identical length",
            lambda ctx: ctx["audio"].write_bytes(click_wav_bytes(bpm=90, seconds=4.0)),
            False,
            SONG_ENVELOPE_SONG_CHANGED,
            1,
        ),
        (
            "the sidecar is gone",
            lambda ctx: ctx["sidecar"].unlink(),
            False,
            SONG_ENVELOPE_FILE_UNREADABLE,
            1,
        ),
        (
            "the sidecar is not an envelope",
            lambda ctx: ctx["sidecar"].write_text("{}", encoding="utf-8"),
            False,
            SONG_ENVELOPE_FILE_UNREADABLE,
            1,
        ),
        (
            "no record at all",
            lambda ctx: edit_analysis_record(
                ctx["root"], ctx["project_id"], path="", song_fingerprint=""
            ),
            False,
            SONG_ENVELOPE_NOT_TAKEN,
            0,
        ),
        (
            "the song file is gone",
            lambda ctx: ctx["audio"].unlink(),
            False,
            SONG_ANALYSIS_MEDIA_MISSING,
            0,
        ),
    )

    for index, (name, mutate, present, reason, digests) in enumerate(states):
        root = tmp_path / f"state-{index}"
        client, store, project_id, audio, sidecar = measured_project_for_currency(root)
        mutate({"root": root, "project_id": project_id, "audio": audio, "sidecar": sidecar})

        calls = {"hash": 0, "measure": 0}
        real_fingerprint = app_module.song_fingerprint
        real_analyze = app_module.analyze_song

        # Both spies bind this iteration's counter and real function as defaults: a closure over
        # the loop variables would count into whichever dict the last iteration left behind.
        def counted_fingerprint(path, _real=real_fingerprint, _calls=calls):
            _calls["hash"] += 1
            return _real(path)

        def counted_analyze(source, _real=real_analyze, _calls=calls, **kwargs):
            _calls["measure"] += 1
            return _real(source, **kwargs)

        monkeypatch = pytest.MonkeyPatch()
        monkeypatch.setattr(app_module, "song_fingerprint", counted_fingerprint)
        monkeypatch.setattr(app_module, "analyze_song", counted_analyze)
        try:
            # The read first, because the analysis below repairs most of these states.
            answer = client.get(f"/api/projects/{project_id}/song/envelope").json()
            assert answer["present"] is present, name
            assert answer["reason"] == reason, name
            paid = calls["hash"]
            assert paid == digests, f"{name}: the read took {paid} digest(s), expected {digests}"

            # Then the automatic analysis path, over the same files, unforced.
            project = ProjectStore(root).get(project_id)
            outcome = analyze_project_song(store, project_id, project, audio)
        finally:
            monkeypatch.undo()

        skipped = calls["measure"] == 0 and outcome == ""
        verb = "skipped" if skipped else "re-measured"
        assert skipped is present, (
            f"{name}: the read says present={present} and the analysis {verb}"
        )

    assert len(states) == 10


def test_a_record_that_disagrees_with_its_file_is_re_measured_and_not_skipped(tmp_path: Path):
    """The divergence itself, end to end: the state that was stuck, and is no longer.

    A hand-edited record whose bytes still match the song passed the analysis path's old
    fingerprint-and-sidecar test, so the automatic route skipped it as current while the read
    refused to serve it. Nothing but a forced `POST /song/analyze` could clear it - and the
    non-forced caller is the render-landing path, so in practice nothing did.
    """
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Stuck"))
    import_measured_song(client, project.id)
    endpoint = f"/api/projects/{project.id}/song/envelope"
    assert client.get(endpoint).json()["present"] is True

    saved = ProjectStore(tmp_path).get(project.id)
    audio = store.project_dir(project.id) / saved.song.path
    saved.song.analysis.band_count = 3
    ProjectStore(tmp_path).save(saved)
    assert client.get(endpoint).json() == {
        "present": False,
        "reason": SONG_ENVELOPE_RECORD_DISAGREES,
    }

    # The automatic path, unforced. It re-measures, and the record it writes agrees with the file.
    stuck = ProjectStore(tmp_path).get(project.id)
    assert analyze_project_song(store, project.id, stuck, audio) == ""
    assert stuck.song.analysis.band_count == 8
    ProjectStore(tmp_path).save(stuck)
    served = client.get(endpoint).json()
    assert served["present"] is True
    assert len(served["envelope"]["bands"]) == 8


def test_the_landing_gate_reads_no_sidecar_and_takes_no_digest(tmp_path: Path):
    """The cheap question stays cheap, and folding it into the shared verdict would have ended it.

    `_song_bytes_moved` asks *could the bytes have moved?*, which a `stat` answers. The verdict
    the other two paths share asks *is this measurement usable?*, which costs a digest and a
    sidecar read. R-10 puts the landing trigger on an in-memory comparison precisely so the
    two-second poll pays neither, so both are counted here rather than argued about.
    """
    from music_video_producer import app as app_module

    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Cheap gate"))
    import_measured_song(client, project.id)
    client.post(
        f"/api/projects/{project.id}/generate/flux",
        json={
            "name": "Lead singer",
            "kind": "character",
            "prompt": "portrait",
            "width": 1024,
            "height": 1024,
            "steps": 4,
            "guidance": 4,
            "seed": 1,
        },
    )

    calls = {"hash": 0, "sidecar": 0}
    real_fingerprint = app_module.song_fingerprint
    real_read = store.read_song_envelope

    def counted_fingerprint(path):
        calls["hash"] += 1
        return real_fingerprint(path)

    def counted_read(project_id, relative_path):
        calls["sidecar"] += 1
        return real_read(project_id, relative_path)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "song_fingerprint", counted_fingerprint)
    monkeypatch.setattr(store, "read_song_envelope", counted_read)
    try:
        comfy.history = completed_history_for(
            [
                {
                    "subfolder": f"music-video-producer/{project.id}/assets",
                    "filename": "Lead singer_00001_.png",
                }
            ]
        )
        report = client.get(f"/api/projects/{project.id}/render-status")
        assert report.status_code == 200, report.text
        # The tick really did settle something, or this proves nothing at all.
        assert report.json()["assets"][0]["path"].endswith("Lead singer_00001_.png")
    finally:
        monkeypatch.undo()

    assert calls["hash"] == 0, "the landing gate hashed the song"
    assert calls["sidecar"] == 0, "the landing gate read the envelope sidecar"


def test_a_sidecar_that_is_not_an_envelope_is_never_served_as_one(tmp_path: Path):
    """End to end through the endpoint: the store's shape and version checks are what stand
    between a consumer and a `present: true` carrying no arrays to read."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Not an envelope"))
    import_measured_song(client, project.id)
    saved = ProjectStore(tmp_path).get(project.id)
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    endpoint = f"/api/projects/{project.id}/song/envelope"

    for payload in ("{}", '{"version": 1}', '{"version": 99, "rms": []}'):
        sidecar.write_text(payload, encoding="utf-8")
        assert client.get(endpoint).json() == {
            "present": False,
            "reason": SONG_ENVELOPE_FILE_UNREADABLE,
        }, payload

    # And the project's own manifest, which is inside the project directory and is a JSON object,
    # is refused rather than served as a measurement.
    saved.song.analysis.path = "project.json"
    ProjectStore(tmp_path).save(saved)
    assert client.get(endpoint).json()["present"] is False


def test_a_lost_save_race_leaves_no_envelope_nobody_points_at(tmp_path: Path):
    """The poll's compare-and-swap can refuse every attempt, and the sidecar is written before it.

    The manifest that would have named the file never lands, so the file is referenced by nothing:
    this tick's write already replaced whatever was there, and the pointer was dropped with the
    save. Sweeping it leaves the project in the state the refused save left everything else in,
    rather than a measurement on disk that no manifest mentions and nothing will ever clean up.
    """
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Lost race"))
    client.post(
        f"/api/projects/{project.id}/generate/music",
        json={"title": "Racing", "caption": "industrial synth rock", "duration": 4},
    )
    subfolder, filename, _audio = generated_song_take(store, project.id, bpm=120)
    comfy.history = completed_history_for([{"subfolder": subfolder, "filename": filename}])

    def always_refuse(*_args, **_kwargs):
        raise ProjectChangedDuringSave("another writer landed first")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module_save_target(), "save", always_refuse)
    try:
        report = client.get(f"/api/projects/{project.id}/render-status")
    finally:
        monkeypatch.undo()

    assert report.status_code == 200, "a lost race must not become an error"
    assert not (
        store.project_dir(project.id) / "media" / "analysis" / "song-envelope.json"
    ).exists(), "an envelope was left behind with no manifest pointing at it"


def app_module_save_target():
    from music_video_producer import app as app_module

    return app_module.ProjectStore


# ---------------------------------------------------------------------------
# Story 8.1, Director ruling during review triage: the re-analyze route.
#
# Three of this feature's absence reasons name a condition the Director can fix
# and, until this route, could then do nothing about. These are the tests that
# each of the three is genuinely clearable.
# ---------------------------------------------------------------------------


def analyze_song_route(client, project_id: str):
    return client.post(f"/api/projects/{project_id}/song/analyze")


def test_re_analyzing_clears_a_song_that_changed_underneath_its_envelope(tmp_path: Path):
    """The first terminal state. The Director replaced the audio; the stored fingerprint no longer
    describes it; every read says so and nothing could act on it. One click, and the envelope
    describes the track that is actually there."""
    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Changed"))
    import_measured_song(client, project.id, bpm=120)
    endpoint = f"/api/projects/{project.id}/song/envelope"

    saved = ProjectStore(tmp_path).get(project.id)
    audio = store.project_dir(project.id) / saved.song.path
    audio.write_bytes(click_wav_bytes(bpm=90, seconds=6.0))
    assert client.get(endpoint).json()["reason"] == SONG_ENVELOPE_SONG_CHANGED

    response = analyze_song_route(client, project.id)
    assert response.status_code == 200, response.text
    assert response.json()["song"]["analysis"]["bpm"] == pytest.approx(90, rel=0.05)

    assert client.get(endpoint).json()["present"] is True
    stored = ProjectStore(tmp_path).get(project.id).song.analysis
    assert stored.bpm == pytest.approx(90, rel=0.05)
    assert stored.song_fingerprint == song_fingerprint(audio)


def test_re_analyzing_clears_an_analysis_whose_sidecar_could_not_be_written(tmp_path: Path):
    """The second terminal state. The disk was full at import, so the Song was stored with no
    record at all; freeing the disk fixed the condition and left no way to act on it."""
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Was full"))

    def no_space(*_args, **_kwargs):
        raise OSError(28, "No space left on device")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module.ProjectStore, "write_song_envelope", no_space)
    try:
        import_measured_song(client, project.id, bpm=120)
    finally:
        monkeypatch.undo()

    assert ProjectStore(tmp_path).get(project.id).song.analysis == models.SongAnalysis()
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is False

    assert analyze_song_route(client, project.id).status_code == 200
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True
    assert ProjectStore(tmp_path).get(project.id).song.analysis.bpm == pytest.approx(
        120, rel=0.05
    )


def test_re_analyzing_clears_an_import_that_happened_while_ffmpeg_was_absent(tmp_path: Path):
    """The third terminal state, and the one whose remedy is furthest from the application.

    A Director imports before installing ffmpeg. The Song is stored whole and unmeasured, they
    install ffmpeg, and nothing they can do inside the interface takes the measurement — the only
    path to it was re-importing the track through a destructive confirmation gate.
    """
    from music_video_producer import app as app_module
    from music_video_producer.audio import FfmpegMissing

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="No ffmpeg yet"))

    def missing(*_args, **_kwargs):
        raise FfmpegMissing("ffmpeg was not found on PATH")

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "analyze_song", missing)
    monkeypatch.setattr(app_module.shutil, "which", lambda _name: None)
    try:
        import_measured_song(client, project.id, bpm=100)
        assert client.get(f"/api/projects/{project.id}/song/envelope").json()["reason"] == (
            SONG_ANALYSIS_FFMPEG_MISSING
        )
        # And the route refuses while ffmpeg is genuinely still missing, naming the same reason
        # rather than answering 500 or pretending to have measured something.
        refused = analyze_song_route(client, project.id)
        assert refused.status_code == 502
        assert refused.json()["detail"] == SONG_ANALYSIS_FFMPEG_MISSING
        assert ProjectStore(tmp_path).get(project.id).song.analysis == models.SongAnalysis()
    finally:
        monkeypatch.undo()

    # ffmpeg installed. The same click now works, with no re-import.
    assert analyze_song_route(client, project.id).status_code == 200
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True
    assert ProjectStore(tmp_path).get(project.id).song.analysis.bpm == pytest.approx(
        100, rel=0.05
    )


def test_re_analyzing_measures_again_even_when_the_envelope_is_already_current(tmp_path: Path):
    """What `force` means, and the whole difference between this route and the automatic path.

    The automatic path skips what is already done because it is not the Director asking. This one
    is, so a current envelope is re-measured rather than silently left alone — otherwise the button
    does nothing on the one project where the Director most wants to see it do something.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Already current"))
    import_measured_song(client, project.id, bpm=120)
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True

    saved = ProjectStore(tmp_path).get(project.id)
    sidecar = store.project_dir(project.id) / saved.song.analysis.path
    written = sidecar.read_bytes()
    sidecar.write_bytes(written + b"\n")  # a marker only a real re-measure erases

    calls = {"analyze": 0}
    real = app_module.analyze_song

    def counted(source, **kwargs):
        calls["analyze"] += 1
        return real(source, **kwargs)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "analyze_song", counted)
    try:
        assert analyze_song_route(client, project.id).status_code == 200
    finally:
        monkeypatch.undo()

    assert calls["analyze"] == 1, "force did not force"
    assert sidecar.read_bytes() == written, "the sidecar was not rewritten"
    assert ProjectStore(tmp_path).get(project.id).song.analysis == saved.song.analysis


def test_re_analyzing_is_one_request_and_one_measurement(tmp_path: Path):
    """Not a poll and not a job lane, which is what keeps the frozen Never intact rather than
    bending it. There is no task record, nothing to come back and ask about, and no client is
    expected to call this on a timer: one request in, one measurement taken, one Project out."""
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="One shot"))
    import_measured_song(client, project.id, bpm=120)

    calls = {"analyze": 0}
    real = app_module.analyze_song

    def counted(source, **kwargs):
        calls["analyze"] += 1
        return real(source, **kwargs)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "analyze_song", counted)
    try:
        response = analyze_song_route(client, project.id)
    finally:
        monkeypatch.undo()

    assert response.status_code == 200
    assert calls["analyze"] == 1
    # The answer is the Project, like every other song route, and it carries no envelope.
    body = response.json()
    assert body["id"] == project.id
    assert body["song"]["analysis"]["path"] == "media/analysis/song-envelope.json"
    assert "rms" not in json.dumps(body)
    # And no job record was invented to describe the work.
    assert ProjectStore(tmp_path).get(project.id).jobs == []


def test_re_analyzing_refuses_a_project_with_nothing_to_measure(tmp_path: Path):
    """The stated decision, covered. `align_song_lyrics` is the sibling and this follows it: a
    precondition nobody can measure past is a 422 naming the reason, never a 500 and never a
    cheerful 200 over a project where nothing happened."""
    client, store, _comfy = make_client(tmp_path)

    # No Song at all.
    project = store.create(Project(name="Songless"))
    refused = analyze_song_route(client, project.id)
    assert refused.status_code == 422
    assert refused.json()["detail"] == SONG_ANALYSIS_WITHOUT_SONG

    # A generated Song whose render has not landed: nothing on disk to measure, same sentence.
    project.song = models.Song(title="Queued", source="generated", path="", duration=4.0)
    store.save(project)
    refused = analyze_song_route(client, project.id)
    assert refused.status_code == 422
    assert refused.json()["detail"] == SONG_ANALYSIS_WITHOUT_SONG

    # A Song whose audio has gone: the containment accessor's own 404, the same answer every
    # other song route gives for a missing file rather than a second spelling of it.
    project.song = models.Song(
        title="Gone", source="imported", path="media/songs/000-gone.wav", duration=4.0
    )
    store.save(project)
    assert analyze_song_route(client, project.id).status_code == 404

    # And an unknown project is a 404 before any of that is considered.
    assert analyze_song_route(client, "project_deadbeef").status_code == 404


def test_a_refused_re_analysis_leaves_the_project_exactly_as_it_found_it(tmp_path: Path):
    """The import path's discipline, arriving here by a different route.

    `analyze_project_song` mutates the Project only on success and never saves, and the save is
    reached only when it returned no reason — so a failure cannot leave a half-applied record, and
    cannot move `updated_at` under a Director who is mid-edit somewhere else.
    """
    from music_video_producer import app as app_module

    client, store, _comfy = make_client(tmp_path)
    project = store.create(Project(name="Untouched"))
    import_measured_song(client, project.id, bpm=120)
    manifest = store.project_dir(project.id) / "project.json"
    before = manifest.read_bytes()

    for failure in (MemoryError("out of memory"), OSError(5, "I/O error"), RuntimeError()):
        def raising(*_args, _failure=failure, **_kwargs):
            raise _failure

        monkeypatch = pytest.MonkeyPatch()
        monkeypatch.setattr(app_module, "analyze_song", raising)
        try:
            refused = analyze_song_route(client, project.id)
        finally:
            monkeypatch.undo()

        assert refused.status_code == 502, type(failure).__name__
        assert refused.json()["detail"], "a refusal with no reason in it"
        assert manifest.read_bytes() == before, "a refused re-analysis wrote the manifest"

    # The envelope that was already there is still served, untouched by any of it.
    assert client.get(f"/api/projects/{project.id}/song/envelope").json()["present"] is True


# ---------------------------------------------------------------------------
# Slice C1 — the Effect Stack on the Shot: the routes, the guard, the catalogue.
#
# Everything here is driven through a real `TestClient` rather than asserted against
# `app.py`'s source. A source grep proves a convention and never a behaviour, and this
# epic has already shipped four tests that could not fail.
# ---------------------------------------------------------------------------


def project_with_two_shots(client, name: str = "Effects") -> str:
    """A project whose plan holds two ordinary shots, by the route a client would use."""
    project_id = client.post("/api/projects", json={"name": name}).json()["id"]
    saved = client.put(
        f"/api/projects/{project_id}/shots",
        json={
            "shots": [
                {"id": "shot_one", "start": 0, "duration": 4, "prompt": "A corridor"},
                {"id": "shot_two", "start": 4, "duration": 4, "prompt": "A threshold"},
            ]
        },
    )
    assert saved.status_code == 200, saved.text
    return project_id


def effects_url(project_id: str, shot_id: str = "shot_one") -> str:
    return f"/api/projects/{project_id}/shots/{shot_id}/effects"


def write_stack(client, project_id: str, stack: list[dict], shot_id: str = "shot_one"):
    return client.put(effects_url(project_id, shot_id), json={"effects": stack})


def test_a_shots_effect_stack_is_read_back_exactly_as_it_was_written(tmp_path: Path):
    """The round trip, through the manifest and not through the handler's own object.

    Re-read with a fresh `ProjectStore` over the same data root, because the response body is
    the in-memory Project the route just built and would answer identically for a write that
    never reached disk.

    **Stored as written, not as resolved.** `validate_stack` fills every declared parameter
    from the catalogue, and storing *that* would freeze each card at the defaults of the day
    it was saved — so the manifest keeps the two values a Director actually set and nothing
    else. See `app.stored_effect_stack`.
    """
    client, _store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)

    # A Shot that has never carried a look reads as an empty stack, which is a state and not
    # an error.
    empty = client.get(effects_url(project_id))
    assert empty.status_code == 200, empty.text
    assert empty.json() == {"shot_id": "shot_one", "effects": []}

    stack = [
        {"effect": "punch_in", "parameters": {"zoom": 1.2}},
        {"effect": "grain", "enabled": False, "parameters": {"strength": 8}},
    ]
    written = write_stack(client, project_id, stack)
    assert written.status_code == 200, written.text

    expected = [
        {"effect": "punch_in", "enabled": True, "parameters": {"zoom": 1.2}},
        {"effect": "grain", "enabled": False, "parameters": {"strength": 8}},
    ]
    assert client.get(effects_url(project_id)).json()["effects"] == expected
    reopened = ProjectStore(tmp_path).get(project_id)
    assert [spec.model_dump() for spec in reopened.shots[0].effects] == expected
    # A disabled card is *retained*, which is the point of the second entry: switching a
    # card off is not deleting it, and the numbers a Director dialled in survive it.
    assert reopened.shots[0].effects[1].enabled is False

    # The write is one Shot's, and the neighbour it shares a manifest with is untouched.
    assert reopened.shots[1].effects == []
    assert client.get(effects_url(project_id, "shot_two")).json()["effects"] == []

    # Emptying it is a write like any other — how a Director takes a look back off.
    assert write_stack(client, project_id, []).status_code == 200
    assert ProjectStore(tmp_path).get(project_id).shots[0].effects == []


def test_an_unwritable_stack_is_refused_by_the_chains_own_sentence_and_stores_nothing(
    tmp_path: Path,
):
    """Every refusal the matrix names, asserted as the whole sentence the chain composed.

    Whole, not `in`: these wordings name the offending effect, parameter and bound and are
    what a Director actually reads, so a substring assertion would pass for a route that had
    started paraphrasing them. They are `effects.py`'s own constants, formatted here from the
    same templates slice B asserts, so the two suites cannot drift into different wordings.

    And after every one of them the stored stack is still the good one: validation runs before
    anything is assigned, so a refusal writes no manifest at all.
    """
    from music_video_producer.effects import (
        EFFECT_LUT_UNKNOWN_REFUSAL,
        EFFECT_MISSING_ID_REFUSAL,
        EFFECT_PARAMETER_ABOVE_REFUSAL,
        EFFECT_UNKNOWN_KEY_REFUSAL,
        EFFECT_UNKNOWN_PARAMETER_REFUSAL,
        EFFECT_UNKNOWN_REFUSAL,
    )

    client, store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)
    good = [{"effect": "punch_in", "parameters": {"zoom": 1.2}}]
    assert write_stack(client, project_id, good).status_code == 200
    manifest = store.project_dir(project_id) / "project.json"
    untouched = manifest.read_bytes()

    refusals = [
        (
            [{"effect": "nope"}],
            EFFECT_UNKNOWN_REFUSAL.format(effect="nope"),
        ),
        (
            [{"effect": "punch_in", "parameters": {"zoom": 4.0}}],
            # `4` and `2`, not `4.0` and `2.0`: a refusal renders a number the way a sentence
            # does — `repr` with a trailing `.0` dropped, so a bound reads as a bound.
            EFFECT_PARAMETER_ABOVE_REFUSAL.format(
                effect="punch_in", parameter="zoom", value="4", bound="2"
            ),
        ),
        (
            [{"effect": "grain", "paramters": {}}],
            EFFECT_UNKNOWN_KEY_REFUSAL.format(
                effect="grain", key="paramters", declared="effect, enabled, parameters"
            ),
        ),
        (
            [{"effect": "grain", "parameters": {"strenght": 8}}],
            EFFECT_UNKNOWN_PARAMETER_REFUSAL.format(
                effect="grain", parameter="strenght", declared="seed, strength"
            ),
        ),
        (
            [{"effect": "punch_in"}, {}],
            EFFECT_MISSING_ID_REFUSAL.format(index=1),
        ),
        (
            # A look this machine does not hold. The id is compared against what the *server*
            # discovered — a client string is never joined onto a directory — so an invented
            # one is refused by name rather than resolved into a path.
            [{"effect": "lut_look", "parameters": {"lut": "../../etc/passwd"}}],
            EFFECT_LUT_UNKNOWN_REFUSAL.format(lut="../../etc/passwd"),
        ),
    ]
    for stack, sentence in refusals:
        response = write_stack(client, project_id, stack)
        assert response.status_code == 422, (stack, response.text)
        assert response.json()["detail"] == sentence, stack
        assert manifest.read_bytes() == untouched, f"a refused write moved the manifest: {stack}"

    assert [
        spec.model_dump() for spec in ProjectStore(tmp_path).get(project_id).shots[0].effects
    ] == [{"effect": "punch_in", "enabled": True, "parameters": {"zoom": 1.2}}]

    # A Shot this project does not hold is a 404, and it is answered before anything else —
    # a request naming nothing gets "Shot not found", never a lecture about a stack.
    missing = write_stack(client, project_id, good, shot_id="shot_nowhere")
    assert missing.status_code == 404
    assert client.get(effects_url(project_id, "shot_nowhere")).status_code == 404


def test_a_locked_shot_refuses_every_effects_write_by_name(tmp_path: Path):
    """FX-7's server half: the lock holds whatever a client draws.

    Asserted with a stack that is perfectly valid, so the refusal can only be the lock — and with
    the stored stack still intact afterwards, because a refusal that had already assigned
    would leave the Shot wearing a look the Director was told it did not get.
    """
    from music_video_producer.app import SHOT_EFFECTS_LOCKED_REFUSAL

    client, store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)
    assert write_stack(client, project_id, [{"effect": "vignette"}]).status_code == 200

    project = store.get(project_id)
    project.shots[0].locked = True
    store.save(project)

    refused = write_stack(client, project_id, [{"effect": "punch_in", "parameters": {"zoom": 1.5}}])
    # 422 with every other lock refusal in this application, not 409. The Director drew that line
    # on 2026-08-18 and `mark_ready` states it: 409 is a live render, which clears by waiting; a
    # lock is a fact about the Shot that clears only when a human unlocks it.
    assert refused.status_code == 422, refused.text
    assert refused.json()["detail"] == SHOT_EFFECTS_LOCKED_REFUSAL.format(
        shot=shot_label(store.get(project_id), store.get(project_id).shots[0])
    )
    # The Shot is named as the *timeline* names it — "SHOT 01", the number a Director can
    # find — and not as a bare id, which appears nowhere in the interface.
    assert refused.json()["detail"].startswith("SHOT 01")

    stored = ProjectStore(tmp_path).get(project_id).shots[0]
    assert [spec.effect for spec in stored.effects] == ["vignette"]
    # Clearing it is a write too, and the lock refuses that as firmly.
    assert write_stack(client, project_id, []).status_code == 422
    assert [
        spec.effect for spec in ProjectStore(tmp_path).get(project_id).shots[0].effects
    ] == ["vignette"]

    # The lock is one Shot's. Its neighbour still writes.
    assert write_stack(client, project_id, [{"effect": "vignette"}], "shot_two").status_code == 200


def test_a_smuggled_stack_is_counted_as_well_as_validated(tmp_path: Path):
    """The cap belongs on both doors, because `validate_stack` does not count.

    `_adopt_shot_effects` keeps a new Shot's arriving stack when it composes, which is what lets a
    Split carry its look (R-21). `validate_stack` answers "is every card composable", one card at
    a time, so a thousand composable cards are a thousand valid answers -- and the cap that
    `replace_shot_effects` applies *before* it calls the validator did not travel with the widening.
    The editing route was capped and this branch was widened in the same session, which is the
    sibling-door shape this route's own comments have now counted twelve times.

    Measured before the fix: 985 cards on an invented shot id survived here and built a
    34,686-character `-vf`, past the 32,767 Windows allows a command line -- so the export failed
    reporting a working ffmpeg as missing, a fault a client caused and the machine got blamed for.

    Every PUT re-reads first, deliberately. The whole-project route is now a compare-and-swap, and
    a body built once and sent twice is refused by *that* on its second use -- a 409 which is not
    this cap and would make this test pass for the wrong reason.
    """
    from music_video_producer.app import SHOT_EFFECT_STACK_LIMIT, SHOT_EFFECTS_TOO_MANY_REFUSAL

    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Counted", shots=[Shot(start=0.0, duration=2.0, prompt="a")]))

    def smuggle(count: int, shot_id: str):
        body = client.get(f"/api/projects/{project.id}").json()
        body["shots"] = list(body["shots"]) + [
            {
                **body["shots"][0],
                "id": shot_id,
                "effects": [
                    {"effect": "grain", "parameters": {"strength": 10}} for _ in range(count)
                ],
            }
        ]
        response = client.put(f"/api/projects/{project.id}", json=body)
        stored = store.get(project.id)
        held = next((len(s.effects) for s in stored.shots if s.id == shot_id), None)
        return response, held

    at_the_cap, held = smuggle(SHOT_EFFECT_STACK_LIMIT, "shot_at_cap")
    assert at_the_cap.status_code == 200, at_the_cap.text
    assert held == SHOT_EFFECT_STACK_LIMIT

    for count in (SHOT_EFFECT_STACK_LIMIT + 1, 985):
        refused, held = smuggle(count, f"shot_over_{count}")
        assert refused.status_code == 422, (count, refused.text)
        assert refused.json()["detail"] == SHOT_EFFECTS_TOO_MANY_REFUSAL.format(
            limit=SHOT_EFFECT_STACK_LIMIT, count=count
        )
        # Refused whole: the shot the body invented is not in the manifest at all.
        assert held is None


def test_the_generic_writes_can_neither_clear_nor_forge_an_effect_stack(tmp_path: Path):
    """**The guard.** `_adopt_shot_effects`, on both whole-shot write paths, both directions.

    The recorded hole in this codebase, met for the twelfth time by `replace_project`'s own
    count — and this test lands in the same commit as the field rather than after the save
    that eats one, which is AD-16 and BUILD-ORDER's explicit instruction.

    Four bodies, and every one of them is a body a real client sends:

    * a full-project `PUT` that simply **omits** `effects` — what every client written before
      this field existed sends, and what any hand-rolled API call sends forever;
    * the same `PUT` **inventing** one, which would write filter configuration straight past
      the catalogue validator that stands between a client's numbers and a filter string;
    * `PUT .../shots` omitting it — **the one that matters most**, because dragging a clip,
      splitting one or nudging a window all write the whole shot list back through it, so this
      is the gesture that would quietly cost a Director every look they had built;
    * `PUT .../shots` inventing one.

    A Shot the stored project does **not** hold is the other half, and it changed on 2026-08-25:
    it keeps the stack it arrived with, validated first. Split and Duplicate mint a new id and
    copy the plan — `effects` is plan content — so dropping it sent a Director's second half back
    ungraded. `test_a_split_saved_the_way_the_browser_saves_it_keeps_the_look_on_both_halves`
    drives that whole gesture; what is asserted here is the property that makes keeping it safe,
    which is that the catalogue still answers first and a stack it refuses takes the entire write
    down with it rather than being quietly dropped from a plan that saves anyway.
    """
    from music_video_producer.app import SHOT_EFFECTS_UNCOMPOSABLE_REFUSAL

    client, _store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)
    assert write_stack(
        client, project_id, [{"effect": "punch_in", "parameters": {"zoom": 1.2}}], "shot_one"
    ).status_code == 200
    assert write_stack(
        client, project_id, [{"effect": "grain", "parameters": {"strength": 12}}], "shot_two"
    ).status_code == 200

    def stacks() -> list[list[dict]]:
        return [
            [spec.model_dump() for spec in shot.effects]
            for shot in ProjectStore(tmp_path).get(project_id).shots
        ]

    intact = stacks()
    assert intact == [
        [{"effect": "punch_in", "enabled": True, "parameters": {"zoom": 1.2}}],
        [{"effect": "grain", "enabled": True, "parameters": {"strength": 12}}],
    ]

    # 1. The whole-project PUT, omitting the field entirely.
    body = client.get(f"/api/projects/{project_id}").json()
    for shot in body["shots"]:
        shot.pop("effects", None)
    body["name"] = "Renamed by an ordinary save"
    omitted = client.put(f"/api/projects/{project_id}", json=body)
    assert omitted.status_code == 200, omitted.text
    assert ProjectStore(tmp_path).get(project_id).name == "Renamed by an ordinary save"
    assert stacks() == intact, "an ordinary whole-project save erased every look"

    # 2. The whole-project PUT, inventing one — including onto a Shot that has never existed.
    body = client.get(f"/api/projects/{project_id}").json()
    body["shots"][0]["effects"] = [{"effect": "monochrome", "enabled": True, "parameters": {}}]
    body["shots"][1]["effects"] = []
    body["shots"].append(
        {
            "id": "shot_smuggled",
            "start": 8,
            "duration": 4,
            "prompt": "Invented",
            "effects": [{"effect": "mirror", "enabled": True, "parameters": {"axis": "horizontal"}}],
        }
    )
    forged = client.put(f"/api/projects/{project_id}", json=body)
    assert forged.status_code == 200, forged.text
    saved = ProjectStore(tmp_path).get(project_id)
    assert [shot.id for shot in saved.shots] == ["shot_one", "shot_two", "shot_smuggled"]
    # The two Shots this project already held keep exactly the stacks the narrow route wrote,
    # against a body that named a different look for one and cleared the other.
    assert stacks()[:2] == intact, "a whole-project save planted a look on a stored shot"
    # The Shot that is new to the plan keeps what it arrived with — which is how a Duplicate
    # made in the browser and saved through here lands with its look on.
    assert stacks()[2] == [
        {"effect": "mirror", "enabled": True, "parameters": {"axis": "horizontal"}}
    ]

    # 2b. And the catalogue still answers for that new Shot, which is what makes keeping it
    #     safe: an unvalidated stack would be filter configuration written past the one
    #     validator (AD-27) that stands between a client's numbers and an ffmpeg filter string.
    #     The whole write goes down with it — the rename in the same body included — because a
    #     save that landed the plan and silently dropped one look is the failure being fixed.
    body = client.get(f"/api/projects/{project_id}").json()
    body["name"] = "Renamed alongside an uncomposable stack"
    body["shots"].append(
        {
            "id": "shot_unusable",
            "start": 12,
            "duration": 4,
            "prompt": "Invented, and graded past the catalogue",
            "effects": [{"effect": "punch_in", "enabled": True, "parameters": {"zoom": 9.0}}],
        }
    )
    refused = client.put(f"/api/projects/{project_id}", json=body)
    assert refused.status_code == 422, refused.text
    assert refused.json()["detail"] == SHOT_EFFECTS_UNCOMPOSABLE_REFUSAL.format(
        shot="SHOT 04 (shot_unusable)",
        detail="punch_in's zoom is 9, above its maximum of 2. Nothing was composed.",
    )
    reopened = ProjectStore(tmp_path).get(project_id)
    assert [shot.id for shot in reopened.shots] == ["shot_one", "shot_two", "shot_smuggled"]
    assert reopened.name == "Renamed by an ordinary save", "a refused write saved the rest"

    # 3. `PUT .../shots`, omitting the field — the timeline's own gesture.
    body = client.get(f"/api/projects/{project_id}").json()
    shots = [dict(shot) for shot in body["shots"][:2]]
    for shot in shots:
        shot.pop("effects", None)
    shots[0]["start"] = 0.5  # a drag, which is what this route is for
    dragged = client.put(f"/api/projects/{project_id}/shots", json={"shots": shots})
    assert dragged.status_code == 200, dragged.text
    assert ProjectStore(tmp_path).get(project_id).shots[0].start == 0.5
    assert stacks() == intact, "dragging a clip erased every look in the project"

    # 4. `PUT .../shots`, inventing one on the two Shots this plan already holds.
    body = client.get(f"/api/projects/{project_id}").json()
    shots = [dict(shot) for shot in body["shots"][:2]]
    shots[0]["effects"] = [{"effect": "posterize", "enabled": True, "parameters": {}}]
    shots[1]["effects"] = []
    planted = client.put(f"/api/projects/{project_id}/shots", json={"shots": shots})
    assert planted.status_code == 200, planted.text
    assert stacks()[:2] == intact, "a shot-list save planted a look"

    # 5. The same route, with a Shot that is new to the plan carrying a stack the catalogue
    #    refuses. This is the sibling that matters most — Split and Duplicate both land here —
    #    so the refusal names the Shot the way the timeline does and nothing at all is saved.
    body = client.get(f"/api/projects/{project_id}").json()
    shots = [dict(shot) for shot in body["shots"]]
    shots.append(
        {
            "id": "shot_unusable",
            "start": 16,
            "duration": 4,
            "prompt": "A half nobody can compose",
            "effects": [{"effect": "grain", "enabled": True, "parameters": {"strenth": 8}}],
        }
    )
    refused = client.put(f"/api/projects/{project_id}/shots", json={"shots": shots})
    assert refused.status_code == 422, refused.text
    # `paramters` one level down is the misspelling this route's docstring argues about; this is
    # the same class one level further down still, and it is refused rather than composed at the
    # catalogue's defaults.
    assert refused.json()["detail"] == SHOT_EFFECTS_UNCOMPOSABLE_REFUSAL.format(
        shot="SHOT 03 (shot_unusable)",
        detail=(
            "grain has no parameter called 'strenth'. It takes seed, strength. "
            "Nothing was composed."
        ),
    )
    assert [shot.id for shot in ProjectStore(tmp_path).get(project_id).shots] == [
        "shot_one",
        "shot_two",
    ], "a refused write saved the shot list anyway"
    assert stacks()[:2] == intact


def test_a_write_that_names_no_effects_is_refused_rather_than_read_as_an_empty_stack(
    tmp_path: Path,
):
    """A misspelled top-level key destroyed a Director's grade and answered **200**.

    `effects` was `Field(default_factory=list)` under pydantic's `extra="ignore"`, so every one
    of these bound to `[]`, stored `[]`, and reported success — with `validate_stack` never
    seeing the body at all:

        PUT .../effects  {"efects": [...]}   -> 200, stored stack becomes []
        PUT .../effects  {}                  -> 200, stored stack becomes []
        PUT .../effects  {"other": 1}        -> 200, stored stack becomes []

    This route's own docstring argues at length that a misspelled `paramters` must not quietly
    do nothing *inside* an entry. One level up, `efects` did worse than nothing.

    **And `{"effects": []}` still works**, which is the constraint the fix had to respect: that
    is how a Director takes every card off, and a route that could not be cleared would be a
    second defect traded for the first. Asserted last, against the same graded Shot, so it
    cannot pass by the stack having been empty all along.
    """
    from music_video_producer.app import SHOT_EFFECTS_ABSENT_REFUSAL

    client, store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)
    good = [{"effect": "punch_in", "enabled": True, "parameters": {"zoom": 1.2}}]
    assert write_stack(client, project_id, good).status_code == 200
    manifest = store.project_dir(project_id) / "project.json"
    untouched = manifest.read_bytes()

    sentence = SHOT_EFFECTS_ABSENT_REFUSAL.format(
        shot=shot_label(store.get(project_id), store.get(project_id).shots[0])
    )
    for body in ({"efects": good}, {}, {"other": 1}, {"effects": None}):
        refused = client.put(effects_url(project_id), json=body)
        assert refused.status_code == 422, (body, refused.text)
        assert refused.json()["detail"] == sentence, body
        assert manifest.read_bytes() == untouched, f"a refused write moved the manifest: {body}"

    # The Shot is named the way the timeline names it, and the sentence says what to send.
    assert "SHOT 01 (shot_one)" in sentence
    assert '"effects": []' in sentence

    # Clearing every card is still one explicit write.
    assert write_stack(client, project_id, []).status_code == 200
    assert ProjectStore(tmp_path).get(project_id).shots[0].effects == []


def test_an_effect_stack_is_capped_before_it_can_outgrow_a_command_line(tmp_path: Path):
    """An unbounded stack made the *export* fail with a false diagnosis, so the bound is here.

    Measured 2026-08-25: 985 grain cards composed an argv of 32725 characters and exported;
    1200 composed 40060 and came back **502 "Assembly failed at the trim stage: ffmpeg is not
    installed or not on PATH"** — Windows raises `FileNotFoundError [WinError 206] The filename
    or extension is too long` and `run_tool` maps every `FileNotFoundError` to that sentence.
    The mapping predates this slice and is recorded separately; what is new is that a client can
    grow the argv without bound, so the refusal belongs at the write that grows it.

    The cap itself is asserted from the constant rather than written out, because the number is
    a judgement that may move; what must not move is that the boundary is enforced and that a
    stack *at* the limit is still accepted.
    """
    from music_video_producer.app import (
        SHOT_EFFECT_STACK_LIMIT,
        SHOT_EFFECTS_TOO_MANY_REFUSAL,
    )

    client, _store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)

    card = {"effect": "grain", "parameters": {"strength": 1}}
    over = [dict(card) for _ in range(SHOT_EFFECT_STACK_LIMIT + 1)]
    refused = write_stack(client, project_id, over)
    assert refused.status_code == 422, refused.text
    assert refused.json()["detail"] == SHOT_EFFECTS_TOO_MANY_REFUSAL.format(
        limit=SHOT_EFFECT_STACK_LIMIT, count=SHOT_EFFECT_STACK_LIMIT + 1
    )
    assert ProjectStore(tmp_path).get(project_id).shots[0].effects == []

    # The limit is a limit and not one less than one: a stack of exactly this many lands.
    at_limit = [dict(card) for _ in range(SHOT_EFFECT_STACK_LIMIT)]
    assert write_stack(client, project_id, at_limit).status_code == 200
    stored = ProjectStore(tmp_path).get(project_id).shots[0].effects
    assert len(stored) == SHOT_EFFECT_STACK_LIMIT

    # And a stack this size is nowhere near the 32767 the measurement is about — the cap is
    # what a stack can plausibly be, not the argv limit converted into cards.
    assert SHOT_EFFECT_STACK_LIMIT <= 64


def test_a_look_dropped_in_while_the_app_runs_is_found_by_the_write_that_names_it(
    tmp_path: Path,
):
    """The Director's actual gesture: drop a `.cube` in the folder, grade with it immediately.

    `discovered_looks` holds its answer for the life of the process — 221 ms cold on a 44.2 MB
    pack is the reason — and `rescan` was exposed only on `GET /api/effects/catalogue`. So a
    look that was *in the looks folder* was refused with:

        There is no look called 'midnight-alley' in the looks folder. Nothing was composed.

    a sentence naming the folder as the authority when the authority was a process-lifetime
    cache, and offering no remedy reachable from this route.

    Counted rather than timed, through the module the route resolves `discover_luts` from,
    because "it rescanned once" and "it rescans every time" are the two things this has to tell
    apart and both of them look instant.
    """
    from music_video_producer import app as app_module
    from music_video_producer.effects import (
        EFFECT_LUT_UNKNOWN_REFUSAL,
        cube_text,
        identity_transform,
        lut_directory,
    )

    client, _store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)

    reads = []
    real_discover = app_module.discover_luts

    def counted(*args, **kwargs):
        reads.append(args)
        return real_discover(*args, **kwargs)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "discover_luts", counted)
    try:
        # The picker opens: one folder read, and the new look does not exist yet.
        served = client.get("/api/effects/catalogue")
        assert served.status_code == 200, served.text
        assert "midnight-alley" not in {entry["lut_id"] for entry in served.json()["looks"]}
        assert len(reads) == 1

        # The Director drops a file in, with the application still running.
        (lut_directory(tmp_path) / "Midnight Alley.cube").write_text(
            cube_text(2, identity_transform, title="Midnight Alley"), encoding="utf-8"
        )

        graded = write_stack(
            client, project_id, [{"effect": "lut_look", "parameters": {"lut": "midnight-alley"}}]
        )
        assert graded.status_code == 200, graded.text
        assert len(reads) == 2, "the write did not look again, or looked more than once"
        assert [spec.parameters["lut"] for spec in
                ProjectStore(tmp_path).get(project_id).shots[0].effects] == ["midnight-alley"]

        # A look that genuinely is not there is still refused, by the same sentence, after
        # exactly one more look at the folder — the retry is bounded whatever the answer.
        missing = write_stack(
            client, project_id, [{"effect": "lut_look", "parameters": {"lut": "not-a-look"}}]
        )
        assert missing.status_code == 422, missing.text
        assert missing.json()["detail"] == EFFECT_LUT_UNKNOWN_REFUSAL.format(lut="not-a-look")
        assert len(reads) == 3

        # A refusal that the folder cannot answer — a number out of bounds — costs no read at
        # all beyond the one the validation itself needs, because re-reading the disk cannot
        # change what is wrong with it.
        assert write_stack(
            client, project_id, [{"effect": "punch_in", "parameters": {"zoom": 9.0}}]
        ).status_code == 422
        assert len(reads) == 3
    finally:
        monkeypatch.undo()


def test_the_catalogue_serves_a_looks_human_name_and_not_its_id(tmp_path: Path):
    """The picker's own text, which the id-shaped default set cannot prove.

    Every generated look is written as `filmic-contrast.cube`, so its name and its id are the
    same string and `name=entry.lut_id` served exactly the right answer for all five. A picker
    listing `midnight-alley` where the Director wrote `Midnight Alley` was invisible to the
    suite. One file whose name is not already a slug is the whole of the fix.
    """
    from music_video_producer.effects import cube_text, identity_transform, lut_directory

    client, _store, _ = make_client(tmp_path)
    assert client.get("/api/effects/catalogue").status_code == 200
    (lut_directory(tmp_path) / "Midnight Alley.cube").write_text(
        cube_text(2, identity_transform, title="Midnight Alley"), encoding="utf-8"
    )

    looks = client.get("/api/effects/catalogue?rescan=true").json()["looks"]
    entry = next(item for item in looks if item["lut_id"] == "midnight-alley")
    assert entry["name"] == "Midnight Alley"
    assert entry["name"] != entry["lut_id"]
    # And the id is still what a stack names — the two are served side by side precisely
    # because they are not the same thing.
    assert write_stack(
        client,
        project_with_two_shots(client, "Named"),
        [{"effect": "lut_look", "parameters": {"lut": entry["lut_id"]}}],
    ).status_code == 200


def test_a_manifest_written_before_effects_existed_round_trips_through_both_routes(
    tmp_path: Path,
):
    """Every project on the Director's disk has no `effects` key at all. This is that project.

    Proven to *load* by the model's default and nothing more, which is the class of defect that
    only shows on real data: the read, the write, and the ordinary whole-project save each have
    to survive a Shot whose stack was never written. The manifest is edited on disk rather than
    built through the routes, because a project this application created today cannot be one.
    """
    client, store, _ = make_client(tmp_path)
    project_id = project_with_two_shots(client)
    manifest = store.project_dir(project_id) / "project.json"

    body = json.loads(manifest.read_text(encoding="utf-8"))
    for shot in body["shots"]:
        shot.pop("effects", None)
    manifest.write_text(json.dumps(body), encoding="utf-8")
    assert "effects" not in manifest.read_text(encoding="utf-8")

    # It loads, and both reads answer for it.
    assert client.get(f"/api/projects/{project_id}").status_code == 200
    assert client.get(effects_url(project_id)).json() == {"shot_id": "shot_one", "effects": []}

    # It can be graded, and the grade survives an ordinary whole-project save from a client
    # that has never heard of the field — which is the same body this manifest was written by.
    assert write_stack(
        client, project_id, [{"effect": "vignette", "parameters": {"angle": 0.5}}]
    ).status_code == 200
    pre_c1 = client.get(f"/api/projects/{project_id}").json()
    for shot in pre_c1["shots"]:
        shot.pop("effects", None)
    saved = client.put(f"/api/projects/{project_id}", json=pre_c1)
    assert saved.status_code == 200, saved.text
    assert [
        spec.model_dump() for spec in ProjectStore(tmp_path).get(project_id).shots[0].effects
    ] == [{"effect": "vignette", "enabled": True, "parameters": {"angle": 0.5}}]


def test_the_effects_routes_are_discoverable_in_the_openapi_document(tmp_path: Path):
    """A13's own reason for every `response_model` on this slice, asserted rather than cited.

    A route whose shape is a bare dict appears in `/openapi.json` with no schema and no client
    can discover it — which is why the read declares `ShotEffectsResponse` and the catalogue
    declares `EffectCatalogueResponse`. Both are here, with the named schema each resolves to,
    so dropping a `response_model` fails the suite instead of quietly shrinking the document.
    """
    client, _store, _ = make_client(tmp_path)
    document = client.get("/openapi.json")
    assert document.status_code == 200, document.text
    paths = document.json()["paths"]

    catalogue = "/api/effects/catalogue"
    shot_effects = "/api/projects/{project_id}/shots/{shot_id}/effects"
    assert catalogue in paths and shot_effects in paths

    def schema_name(path: str, method: str) -> str:
        content = paths[path][method]["responses"]["200"]["content"]["application/json"]
        return content["schema"]["$ref"].rsplit("/", 1)[-1]

    assert schema_name(catalogue, "get") == "EffectCatalogueResponse"
    assert schema_name(shot_effects, "get") == "ShotEffectsResponse"
    # The write answers with the whole Project — the idiom every purpose-built shot action
    # follows, and what a client needs to redraw and to keep its concurrency stamp. FastAPI
    # names the serialisation-side variant `Project-Output`, so the schema is identified by
    # what it holds rather than by a name this application does not choose.
    written = schema_name(shot_effects, "put")
    assert written.startswith("Project"), written
    assert "shots" in document.json()["components"]["schemas"][written]["properties"]

    # The declared shapes are real schemas with the fields the routes promise, not empty
    # objects that happen to carry a name.
    schemas = document.json()["components"]["schemas"]
    assert set(schemas["ShotEffectsResponse"]["properties"]) == {"shot_id", "effects"}
    assert {"families", "effects", "looks"} <= set(
        schemas["EffectCatalogueResponse"]["properties"]
    )


def test_the_effect_catalogue_is_one_read_and_never_re_reads_the_looks_folder(tmp_path: Path):
    """FX-5's picker read: every effect with its bounds, every look, and one folder read.

    The folder read is the measured one — 221 ms cold on the Director's 44.2 MB pack, because
    a truncated `.cube` can only be told from a whole one by counting its data lines — so a
    picker that re-read it on every open is the named failure. Proven by counting calls to
    `discover_luts` through the module the route resolves it from, which is the only way to
    tell "held" from "fast enough that nobody noticed".

    The definitions are checked against `EFFECT_CATALOGUE` itself for *coverage* — an effect
    added to the table must appear here without anybody remembering — while the bounds of one
    card are written out by hand, because a test that derived them from the same table would
    pass just as happily for a table that had drifted.
    """
    from music_video_producer import app as app_module
    from music_video_producer.effects import EFFECT_CATALOGUE, FAMILY_ORDER

    client, _store, _ = make_client(tmp_path)

    reads = []
    real_discover = app_module.discover_luts

    def counted(*args, **kwargs):
        reads.append(args)
        return real_discover(*args, **kwargs)

    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(app_module, "discover_luts", counted)
    try:
        first = client.get("/api/effects/catalogue")
        assert first.status_code == 200, first.text
        for _ in range(5):
            assert client.get("/api/effects/catalogue").json() == first.json()
        # And a stack write validates against the same held listing.
        project_id = project_with_two_shots(client)
        assert write_stack(client, project_id, [{"effect": "vignette"}]).status_code == 200
        assert len(reads) == 1, f"the looks folder was read {len(reads)} times"

        # The one escape hatch: an explicit rescan, which a Director asks for after dropping a
        # `.cube` in the folder. Never something a picker does when it opens.
        assert client.get("/api/effects/catalogue?rescan=true").status_code == 200
        assert len(reads) == 2
    finally:
        monkeypatch.undo()

    served = first.json()
    assert served["families"] == list(FAMILY_ORDER)
    assert {entry["effect"] for entry in served["effects"]} == set(EFFECT_CATALOGUE)
    for entry in served["effects"]:
        assert entry["family"] in served["families"], entry["effect"]
        assert entry["label"], entry["effect"]

    # One card's declared bounds, written out rather than derived.
    punch_in = next(entry for entry in served["effects"] if entry["effect"] == "punch_in")
    assert punch_in["family"] == "geometry"
    assert punch_in["parameters"] == [
        {
            "name": "zoom",
            "label": "Zoom",
            "kind": "number",
            "default": 1.0,
            "minimum": 1.0,
            "maximum": 2.0,
            "integer": False,
            "choices": [],
        }
    ]

    # A choice parameter carries its words; a LUT parameter carries no default at all, because
    # a grade with no look chosen has nothing to apply and is refused by name.
    mirror = next(entry for entry in served["effects"] if entry["effect"] == "mirror")
    assert mirror["parameters"][0]["kind"] == "choice"
    assert mirror["parameters"][0]["choices"] == ["horizontal", "vertical", "both"]
    assert mirror["parameters"][0]["default"] == "horizontal"
    look = next(entry for entry in served["effects"] if entry["effect"] == "lut_look")
    assert [parameter["kind"] for parameter in look["parameters"]] == ["lut", "choice"]
    assert look["parameters"][0]["default"] is None

    # The looks are served with the id a client may name and the name a Director reads —
    # **and no path**, which is the security property of the whole Grade family.
    assert served["looks"], "the default set was not generated for a fresh data root"
    for entry in served["looks"]:
        assert set(entry) == {"lut_id", "name"}
    ids = [entry["lut_id"] for entry in served["looks"]]
    assert ids == sorted(ids), "the listing is not in a stable order"
    # And the ids the route serves are exactly the ids a stack may name.
    assert write_stack(
        client,
        project_with_two_shots(client, "Graded"),
        [{"effect": "lut_look", "parameters": {"lut": ids[0]}}],
    ).status_code == 200


def test_the_director_chat_is_never_shown_a_shots_effect_stack(tmp_path: Path):
    """The classification, proven at the prompt rather than at the set that declares it.

    `_withheld_fields` refuses at import for an unclassified field, which is what makes adding
    one loud — but it says nothing about whether the exclusion it returns is actually applied
    to the dump. Asserted here by planting a stack, running a real chat turn, and reading the
    context the model was handed: no key, and no value.
    """
    director = RevisingDirector()
    client, _store = make_client_with_director(tmp_path, director)
    project_id = project_with_two_shots(client)
    assert write_stack(
        client, project_id, [{"effect": "punch_in", "parameters": {"zoom": 1.77}}]
    ).status_code == 200

    reply = client.post(
        f"/api/projects/{project_id}/director/chat", json={"message": "What do you think?"}
    )
    assert reply.status_code == 200, reply.text

    serialised = json.dumps(director.contexts[0])
    assert "effects" not in serialised
    assert "punch_in" not in serialised
    assert "1.77" not in serialised
    # And the plan facts the Director *is* meant to read are still there, so this is a
    # withholding rather than an emptied dump.
    assert "A corridor" in serialised


# --------------------------------------------------------------------------------------------
# Read-modify-write races. Sites of one mechanism: a route reads the manifest, time passes, and
# the whole manifest is written back from the copy it read. `tests/race_support.py` holds the
# window open, so each of these is a race that definitely happened rather than one that might.
# --------------------------------------------------------------------------------------------


def test_a_document_restore_that_races_another_write_refuses_rather_than_swapping_blind(
    tmp_path: Path,
):
    """There is exactly **one** kept version, and this route both reads it and writes it.

    Two restores that overlap swap the same pair twice and leave the document where it started
    with the slot spent; a restore overlapping a hand edit or a chat turn writes the pre-turn
    text back over a document the Director had just accepted. Neither is detectable afterwards
    -- both leave a well-formed pair of strings, and both requests answer 200 -- which is why
    this is the one document route that cannot be left last-writer-wins.

    Refused rather than retried: a retry belongs to a loop that re-derives its verdict, and
    this is a click on a specific pair of documents the Director can see.
    """
    client, store, _ = make_client(tmp_path)
    project = store.create(Project(name="Restore races"))
    held = store.get(project.id)
    held.treatment = "The second draft"
    held.treatment_previous = "The first draft"
    store.save(held)
    gate = Interleaved()
    park_the_next_read(store, gate)

    restore, saved = gate.run(
        lambda: client.post(f"/api/projects/{project.id}/documents/treatment/restore"),
        lambda: client.put(
            f"/api/projects/{project.id}/documents",
            json={
                "creative_brief": "",
                "treatment": "A third draft, typed by hand",
                "style_bible": "",
            },
        ),
    )

    assert gate.fired == [True], "the second write never landed inside the restore"
    assert saved.status_code == 200, saved.text
    assert restore.status_code == 409, restore.text
    assert restore.json()["detail"] == SAVE_RACE_REFUSAL
    stored = store.get(project.id)
    assert stored.treatment == "A third draft, typed by hand"
    # And nothing of the refused restore is on disk: not the swap, not the spent slot, and not
    # the system message that would claim in the thread that a restore happened.
    assert stored.treatment_previous == "The first draft"
    assert stored.messages == []


def a_song_and_one_shot(client, name: str) -> str:
    """A project whose Song is a real file and whose plan is one ordinary, unrendered Shot."""
    project_id = client.post("/api/projects", json={"name": name}).json()["id"]
    imported = client.post(
        f"/api/projects/{project_id}/songs/upload",
        data={"title": "Spine", "duration": "180"},
        files={"file": ("song.wav", wav_bytes(0.25), "audio/wav")},
    )
    assert imported.status_code == 200, imported.text
    saved = client.put(
        f"/api/projects/{project_id}/shots",
        json={"shots": [{"id": "shot_a", "start": 0, "duration": 4, "prompt": "A corridor"}]},
    )
    assert saved.status_code == 200, saved.text
    return project_id


def test_detaching_a_song_cannot_revert_a_shot_saved_while_it_read(tmp_path: Path):
    """**"Shots are left exactly as they are" is a claim about a whole-manifest write.**

    `remove_song` changes one field and rewrites every other one from a copy read a moment
    earlier, so a `PUT /shots` landing inside that moment is not merely lost -- it is lost
    *through* the no-deletion guarantee, the shot list reverting to whatever it held when the
    detach was clicked while the reply reports a clean removal.
    """
    client, store, _ = make_client(tmp_path)
    project_id = a_song_and_one_shot(client, "Detach races a shot save")
    gate = Interleaved()
    park_the_next_read(store, gate)

    removed, saved = gate.run(
        lambda: client.delete(
            f"/api/projects/{project_id}/song?confirm_song_replacement=true"
        ),
        lambda: client.put(
            f"/api/projects/{project_id}/shots",
            json={
                "shots": [
                    {
                        "id": "shot_a",
                        "start": 0,
                        "duration": 4,
                        "prompt": "Typed while the song was being detached",
                    }
                ]
            },
        ),
    )

    assert gate.fired == [True], "the shot save never landed inside the detach"
    assert saved.status_code == 200, saved.text
    assert removed.status_code == 409, removed.text
    assert removed.json()["detail"] == SAVE_RACE_REFUSAL
    stored = store.get(project_id)
    assert [shot.prompt for shot in stored.shots] == [
        "Typed while the song was being detached"
    ]
    # Nothing of the refused detach landed either, which is what makes the 409 honest: the
    # Director re-reads and sees a song that is still attached.
    assert stored.song is not None


def test_a_shot_save_cannot_put_back_a_song_detached_while_it_read(tmp_path: Path):
    """The same race from the other side, and the direction `updated_at` cannot see.

    The revision token is compared at the *top* of `replace_shots`, against a manifest that
    still had the Song; the detach lands after that comparison and before the save. This body
    sends no token at all -- the wire has always allowed that, and a client that omits it used
    to have nothing between its stale shot list and the whole manifest.
    """
    client, store, _ = make_client(tmp_path)
    project_id = a_song_and_one_shot(client, "Shot save races a detach")
    gate = Interleaved()
    park_the_next_read(store, gate)

    saved, removed = gate.run(
        lambda: client.put(
            f"/api/projects/{project_id}/shots",
            json={
                "shots": [
                    {"id": "shot_a", "start": 0, "duration": 4, "prompt": "Nudged a clip"}
                ]
            },
        ),
        lambda: client.delete(
            f"/api/projects/{project_id}/song?confirm_song_replacement=true"
        ),
    )

    assert gate.fired == [True], "the detach never landed inside the shot save"
    assert removed.status_code == 200, removed.text
    assert saved.status_code == 409, saved.text
    assert saved.json()["detail"] == SAVE_RACE_REFUSAL
    stored = store.get(project_id)
    assert stored.song is None, "the shot save put back a Song the Director detached"
    assert [shot.prompt for shot in stored.shots] == ["A corridor"]


def test_a_second_music_generation_does_not_erase_the_first_ones_job_record(tmp_path: Path):
    """Two generations at once is the easiest concurrent state in this application to reach.

    Every music job carries `target_id="song"` and neither generate route refuses an in-flight
    sibling, so the Director clicking twice -- or two tabs -- puts two `/prompt` calls in the
    air at once. The route that saved the project it read *before* its submission took the
    other one's whole job record with it, leaving a prompt running on the card that
    `reconcilable_jobs` cannot count, the poll never asks about, and whose audio
    `apply_job_history` can never adopt.
    """
    client, store, comfy = make_client(tmp_path)
    project = store.create(Project(name="Two generations"))
    gate = Interleaved()
    prompt_ids = iter(["p-first", "p-second"])

    async def submit(prompt, client_id=None):
        comfy.prompts.append(prompt)
        answer = type("Submission", (), {"prompt_id": next(prompt_ids), "number": 1})()
        # After the id is taken and before the route writes it: the `/prompt` round trip this
        # application allows thirty seconds.
        gate.pause()
        return answer

    comfy.submit = submit

    def generate(title: str):
        return client.post(
            f"/api/projects/{project.id}/generate/music",
            json={"title": title, "caption": "A slow build", "duration": 30},
        )

    first, second = gate.run(lambda: generate("First"), lambda: generate("Second"))

    assert gate.fired == [True], "the second generation never landed inside the first"
    assert (first.status_code, second.status_code) == (202, 202), first.text
    stored = store.get(project.id)
    assert len(stored.jobs) == 2, "one generation's job record was erased by the other"
    assert sorted(job.prompt_id for job in stored.jobs) == ["p-first", "p-second"]
    # Both records are accepted rather than left on the pre-submission sentinel, so the
    # reconciler asks ComfyUI about each of them.
    assert {job.status for job in stored.jobs} == {"queued"}
    # The Song is still one Song, and it is the one whose route wrote last -- a take that
    # matches no `Song.prompt_id` stays recoverable from its own job's `output_files`.
    assert stored.song is not None
    assert stored.song.prompt_id in {"p-first", "p-second"}


def test_the_chat_merge_follows_the_shots_the_model_saw_not_their_positions(tmp_path: Path):
    """`PlannedShot` carries no id, so position is the only correspondence there is.

    It is a correspondence with the project as it stood when the prompt was built, and the
    route re-reads after the call -- deliberately, so a lock or a document committed during a
    model call that runs for many seconds is not reverted. One Shot added while the model was
    thinking shifts every index past it, and `start`, `duration` and `prompt` then land on a
    Shot the model never described. A wrong window is visible; a plausible prompt on the wrong
    Shot reads as intentional forever.
    """
    gate = Interleaved()

    class ParkedPlanningDirector(PlanningDirector):
        async def plan(self, **kwargs):
            answer = await super().plan(**kwargs)
            gate.pause()
            return answer

    director = ParkedPlanningDirector(
        shots=[(0.0, 4.0, "For the first window"), (4.0, 4.0, "For the second window")]
    )
    client, store = make_client_with_director(tmp_path, director)
    project = store.create(Project(name="Chat merge races an insert"))
    held = store.get(project.id)
    held.shots = [
        Shot(id="shot_a", start=0, duration=4, prompt="The corridor"),
        Shot(id="shot_b", start=4, duration=4, prompt="The clearing"),
    ]
    store.save(held)

    reply, saved = gate.run(
        lambda: client.post(
            f"/api/projects/{project.id}/director/chat",
            json={"message": "Retime the plan", "apply_shots": True},
        ),
        lambda: client.put(
            f"/api/projects/{project.id}/shots",
            json={
                "shots": [
                    {
                        "id": "shot_z",
                        "start": 0,
                        "duration": 2,
                        "prompt": "Inserted while the model was thinking",
                    },
                    {"id": "shot_a", "start": 0, "duration": 4, "prompt": "The corridor"},
                    {"id": "shot_b", "start": 4, "duration": 4, "prompt": "The clearing"},
                ]
            },
        ),
    )

    assert gate.fired == [True], "the insert never landed inside the model call"
    assert saved.status_code == 200, saved.text
    assert reply.status_code == 200, reply.text
    stored = store.get(project.id)
    assert [shot.id for shot in stored.shots] == ["shot_z", "shot_a", "shot_b"]
    assert [shot.prompt for shot in stored.shots] == [
        "Inserted while the model was thinking",
        "For the first window",
        "For the second window",
    ]


def app_py_saving_routes() -> dict[str, str]:
    """Every route in `app.py` whose own body writes the manifest, by name, with its source.

    Enumerated off the live app rather than listed, so a route added, renamed or moved is
    classified the moment it exists -- `test_frontend_contract`'s submission enumeration,
    applied to the other property every route in that module has. Comments are dropped first:
    each of these routes explains its guard in prose that quotes the guard's own name, and an
    assertion matching the explanation rather than the code would be measuring itself.
    """
    from music_video_producer.app import create_app

    saving: dict[str, str] = {}
    for route in create_app().routes:
        endpoint = getattr(route, "endpoint", None)
        if endpoint is None:
            continue
        try:
            source = inspect.getsource(endpoint)
        except (OSError, TypeError):  # pragma: no cover - a builtin or C-level endpoint
            continue
        code = "\n".join(
            line for line in source.splitlines() if not line.strip().startswith("#")
        )
        if "store.save(" in code or "record_submission(" in code:
            saving[endpoint.__name__] = code
    return saving


def test_every_manifest_write_is_classified():
    """`MANIFEST_WRITE_GUARDS` is the inventory, and this is what keeps it from being a wish.

    The table exists because the same read-modify-write hole was found in a sibling route six
    separate times, each by its own audit, with nothing anywhere saying which routes had been
    through and which had not. A table nobody enforces has exactly that failure mode again: a
    route added next month joins no group and is invisible until the next audit.

    Two claims, and the second is the one with teeth. First, the key set is exactly the routes
    that write -- so a new saving route fails here until somebody decides what guards it.
    Second, the classification is checked against the code rather than taken on trust: a route
    called a compare-and-swap must pass `if_generation`, one called last-writer-wins must not,
    and one called re-read-and-patch must write through a helper that re-reads.
    """
    saving = app_py_saving_routes()
    assert set(saving) == set(MANIFEST_WRITE_GUARDS), (
        "a route writes the manifest without being classified in MANIFEST_WRITE_GUARDS"
    )
    rereaders = ("record_submission(", "settle(", "settle_unsubmitted_jobs(")
    for name, code in sorted(saving.items()):
        guard = MANIFEST_WRITE_GUARDS[name]
        if guard == WRITE_GUARD_COMPARE_AND_SWAP:
            assert "if_generation" in code, f"{name} is not a compare-and-swap"
        elif guard == WRITE_GUARD_LAST_WRITER_WINS:
            assert "if_generation" not in code, (
                f"{name} passes if_generation but is classified as last writer wins"
            )
        else:
            assert guard == WRITE_GUARD_REREAD, f"{name}: unknown guard {guard!r}"
            assert any(marker in code for marker in rereaders), (
                f"{name} writes nothing through a re-reading helper"
            )
    # And the reason the table is worth reading: all three groups are populated, so it
    # describes a distribution rather than a policy nobody follows.
    assert len(set(MANIFEST_WRITE_GUARDS.values())) == 3


def test_the_two_recovery_slot_restores_are_written_the_same_way():
    """The document restore and the song-context restore are twins, and were not written alike.

    `restore_song_context`'s own docstring says it matches the document restore "exactly". That
    has to include how it is written, or the sentence is false in the way that costs something:
    both routes read a single kept version and write it back, both guard text nothing else can
    reproduce, and a swap made from a stale copy leaves a well-formed manifest either way. One
    of two identical doors closed reads as done to whoever comes next.
    """
    saving = app_py_saving_routes()
    for name in ("restore_document", "restore_song_context", "replace_song_context"):
        assert MANIFEST_WRITE_GUARDS[name] == WRITE_GUARD_COMPARE_AND_SWAP, name
        assert "get_project_for_update(" in saving[name], name


def test_a_song_context_restore_that_races_another_write_refuses(tmp_path: Path):
    """The document restore's twin, driven the same way and refused the same way.

    A lyric sheet is the largest hand-authored text this application accepts and the one it can
    least reproduce -- pasted in from somewhere the app cannot reach -- so the slot holding the
    previous one is the last thing that may be spent by a swap read from a stale copy.
    """
    client, store, _ = make_client(tmp_path)
    project_id = a_song_and_one_shot(client, "Lyrics restore races")
    held = store.get(project_id)
    held.song.lyrics = "The second sheet"
    held.song.lyrics_previous = "The first sheet"
    store.save(held)
    gate = Interleaved()
    park_the_next_read(store, gate)

    restore, saved = gate.run(
        lambda: client.post(f"/api/projects/{project_id}/song/context/lyrics/restore"),
        lambda: client.put(
            f"/api/projects/{project_id}/song/context",
            json={"lyrics": "A third sheet, pasted by hand", "caption": ""},
        ),
    )

    assert gate.fired == [True], "the second write never landed inside the restore"
    assert saved.status_code == 200, saved.text
    assert restore.status_code == 409, restore.text
    assert restore.json()["detail"] == SAVE_RACE_REFUSAL
    stored = store.get(project_id)
    assert stored.song.lyrics == "A third sheet, pasted by hand"
    assert stored.song.lyrics_previous == "The second sheet"


def test_a_second_render_does_not_erase_the_first_ones_job_record(tmp_path: Path):
    """The submission race at the hottest route there is, and the one Generate All drives.

    `generate_h3` read the project, saved the record, awaited `/prompt`, then wrote the shot's
    queued state onto that same pre-await object -- so two renders in the air at once left one
    of the two records nowhere, and the shot it belonged to still reading `ready` with a prompt
    running on the card.
    """
    client, store, comfy = make_client(tmp_path)
    project_id = client.post("/api/projects", json={"name": "Two renders"}).json()["id"]
    saved = client.put(
        f"/api/projects/{project_id}/shots",
        json={
            "shots": [
                {
                    "id": "shot_a", "start": 0, "duration": 4,
                    "prompt": "A corridor", "status": "ready",
                },
                {
                    "id": "shot_b", "start": 4, "duration": 4,
                    "prompt": "A clearing", "status": "ready",
                },
            ]
        },
    )
    assert saved.status_code == 200, saved.text
    gate = Interleaved()
    prompt_ids = iter(["p-shot-a", "p-shot-b"])

    async def submit(prompt, client_id=None):
        comfy.prompts.append(prompt)
        answer = type("Submission", (), {"prompt_id": next(prompt_ids), "number": 1})()
        gate.pause()
        return answer

    comfy.submit = submit

    def render(shot_id: str):
        return client.post(f"/api/projects/{project_id}/shots/{shot_id}/generate/h3", json={})

    first, second = gate.run(lambda: render("shot_a"), lambda: render("shot_b"))

    assert gate.fired == [True], "the second render never landed inside the first"
    assert (first.status_code, second.status_code) == (202, 202), first.text
    stored = store.get(project_id)
    assert len(stored.jobs) == 2, "one render's job record was erased by the other"
    assert sorted(job.prompt_id for job in stored.jobs) == ["p-shot-a", "p-shot-b"]
    # And both Shots carry the render that is actually on the card.
    assert [shot.status for shot in stored.shots] == ["queued", "queued"]
    assert sorted(shot.prompt_id for shot in stored.shots) == ["p-shot-a", "p-shot-b"]
